WITH payload AS (SELECT $archive_payload$[{"id":"ceca0cbf-8697-51c3-aedb-6ed337fbb7bf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش -حيازة احلشيش املخدر بقصد التعاطي -إقامة حد السكر على متعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","document_number":"3444750","case_number":"3410699","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"مخدرات -ترويج احلشيش -حيازة احلشيش املخدر بقصد التعاطي -إقامة حد السكر على متعاطي احلشيش -التعزير بالسجن واجللد والغرامة واملنع من السفر واملصادرة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3444750:‬تاريخه ‪1434/2/23:‬هـ‬\n                   ‫رقم الدعوى ‪3410699:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34191215‬تاريخه‪1434/4/17 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش ‪ -‬حيــازة احلشــيش املخــدر بقصــد‬\n‫التعاطــي ‪ -‬إقامــة حــد الســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر‬\n        ‫بالســجن واجللــد والغرامــة واملنــع مــن الســفر واملصــادرة‪.‬‬\n\n\n\n\n‫‪ -1‬الفقــرة (‪ )2‬مــن املــادة (‪)3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n‫‪ -2‬الفقــرة (‪ )1‬مــن املــادة (‪)38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪)56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪)62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪)60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                   ‫العقليــة‪.‬‬\n           ‫‪ -6‬املادة (‪ )53‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n                                                                                ‫‪258‬‬\n\f      ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا ‪ ،‬األول ‪ :‬بترويــج قطعــة مــن‬\n      ‫احلشــيش املخــدر بقصــد االجتــار ‪ ،‬وحيــازة قطعــة مــن احلشــيش بقصــد‬\n      ‫التعاطــي ‪ ،‬وحيــازة عقبــي ســيجارة حشــيش بقصــد التعاطــي ‪،‬وتعاطــي‬\n      ‫احلشــيش املخــدر‪ .‬الثانــي ‪ :‬االشــتراك بحيــازة عقبــي ســيجارة حشــيش‬\n      ‫بقصــد التعاطــي وتعاطــي احلشــيش املخــدر ‪ ،‬حيــث مت القبــض عليهمــا‬\n      ‫إثــر بــاغ عــن قيــام املدعــى عليــه الثانــي بترويــج املــواد املخــدرة ‪ ،‬ومت‬\n      ‫متكــن املصــدر مــن االتصــال بــه علــى جوالــه واالتفــاق علــى شــراء‬\n      ‫احلشــيش املخــدر ‪ ،‬ودخــل املصــدر لشــقة املدعــى عليــه وعــاد وبحوزتــه‬\n      ‫قطعــة حشــيش‪،‬ولم يتــم القبــض عليــه يف حينــه لضمــان عدم انكشــاف‬\n      ‫املصــدر ‪ ،‬ومت مداهمــة الشــقة و كان برفقتــه املدعــى عليــه األول ومت‬\n      ‫العثــور علــى املبلــغ املرقــم وكذلــك علــى قطعــة حشــيش وطلــب املدعــي‬\n      ‫العــام إثبــات مــا أســند إليهمــا واحلكــم علــى املدعــى عليــه األول بعقوبــة‬\n      ‫الســجن واجللــد والغرامــة واحلكــم علــى املدعــى عليــه الثانــي بعقوبــة‬\n      ‫الســجن ‪ ،‬ومنعهمــا مــن الســفر ‪ ،‬ومصــادرة الهاتــف اجلــوال و إســقاط‬\n      ‫شــريحته ‪ ،‬ولــم يحضــر املدعــى عليــه األول وحضــر املدعــى عليــه الثانــي‬\n      ‫وأقــر مبــا نســب إليــه ‪ ،‬بنــاء علــى مــا ســبق حكمــت احملكمــة بإثبــات‬\n      ‫إدانــة املدعــى عليــه الثانــي مبــا نســب إليــه واحلكــم عليــه بإقامــة حــد‬\n      ‫املســكر وبتعزيــره بالســجن واجللــد والغرامــة و املنــع مــن الســفر و‬\n      ‫مصــادرة الهاتــف اجلــوال وإســقاط شــريحته ‪ ،‬جــرى التنويــه أن املدعــى‬\n      ‫وصــدق‬‫عليــه األول ســيتم النظــر يف الدعــوى ضــده حــال حضــوره ‪ُ ،‬‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪259‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي باحملكمــة اجلزائيــة‬\n‫‪ ......‬ويف يــوم الثالثــاء ‪ ......‬افتتحــت اجللســة وفيهــا قــدم املدعــي العــام‬\n‫ا فيهــا‬‫‪ ......‬دعــواه ضــد املدعــي عليهمــا األول ‪ ......‬والثانــي ‪ ......‬قائ ـ ً‬\n‫‪ :‬باالطــاع علــى احملضــر املعــد مــن قبــل شــعبة مكافحــة املخــدرات‬\n‫بالدمــام بتاريــخ يــوم االثنــن املوافــق ‪ ......‬تبــن أنــه مت القبــض علــى‬\n‫ـاء‬\n‫املدعــى عليهمــا إثــر بــاغ عــن قيــام ‪ ......‬بترويــج املــواد املخــدرة وبنـ ً‬\n‫عليــه مت مقابلــه املصــدر ومت متكينــه مــن االتصــال بــه علــى جوالــه رقــم‬\n‫(‪ )......‬واالتفــاق معــه علــى شــراء احلشــيش املخــدر فطلــب مــن املصــدر‬\n‫احلضــور إليــه يف منزلــه ومت تزويــد املصــدر باملبلــغ احلكومــي وتفتيشــه‬\n‫تفتيشـ ًا دقيقـ ًا وقــام اثنــن مــن أعضــاء الفرقــة القابضــة مبرافقتــه وعنــد‬\n‫الوصــول إلــى منــزل ‪ ......‬قــام املصــدر باالتصــال عليــه فطلــب منــه‬\n‫الصعــود إليــه يف الشــقة التــي يســكنها فنــزل املصــدر إليــه وبعــد ذلــك‬\n‫عــاد وبحوزتــه قطعــه ســوداء اللــون بلــغ وزنهــا (‪ )5.3‬خمســة جرامــات‬\n‫وثالثــة مــن العشــرة مــن اجلــرام أثبــت التقريــر الكيمــاوي الشــرعي‬\n‫رقــم (‪ )......‬وتاريــخ ايجابيتهــا ملــادة احلشــيش املخــدر ولــم يتــم القبــض‬\n‫عليــه يف حينــه لضمــان عــدم انكشــاف املصــدر وبعــد مــا يقــارب األربــع‬\n‫ســاعات مت التوجــه للشــقة التــي يقيــم فيهــا ‪ ......‬وكانــت تنبعــث منهــا‬\n‫رائحــة احلشــيش املخــدر ومت طــرق البــاب فقــام ‪ ......‬بالــرد ورفــض فتــح‬\n‫البــاب بعــد معرفتــه لرجــال املكافحــة فتــم خلــع البــاب ودخــول املنــزل‬\n‫ومت القبــض عليــه وكان برفقتــه ‪ ......‬وبتفتيــش املجلــس مت العثــور‬\n‫علــى املبلــغ املرقــم وبتفتيــش غرفــه ‪ ......‬مت العثــور فيهــا علــى قطعــه مــن‬\n\n                                                                                       ‫‪260‬‬\n\f      ‫احلشــيش املخــدر بلــغ وزنهــا (‪ )3.8‬ثالثــة جرامــات وثمانيــة مــن العشــرة‬\n      ‫مــن اجلــرام أثبــت التقريــر املشــار اليــه إيجابيتهــا ملــادة احلشــيش املخــدر‬\n      ‫ومت العثــور كذلــك علــى عقبــي ســجائر ملفوفــه لــف يــدوي ومدخنــه بلــغ‬\n      ‫وزنهــا ( ‪ )0.5‬خمســة مــن العشــرة مــن اجلــرام أثبــت التقريــر املشــار اليــه‬\n      ‫إيجابيتهــا ملــادة احلشــيش املخــدر وباســتجواب ‪ ......‬أقــر بصحــة واقعــة‬\n      ‫القبــض عليــه وببيعــه للمــواد املخــدرة وتســليمها واســتالم مبلــغ مالــي‬\n      ‫مقابــل ذلــك وأفــاد أنــه مت القبــض عليــه رفــق ‪ ......‬أثناء مــا كان متواجدا‬\n      ‫معــه يف املنــزل حيــث حضــرت املكافحــة ومت القبــض عليــه ومت العثــور‬\n      ‫بحوزتــه علــى املبلــغ احلكومــي وقطعــه مــن احلشــيش املخــدر وأضــاف أن‬\n      ‫مرافقــه ‪ ......‬ال عالقــه لــه باالتفــاق الــذي مت بينــه وبــن املصــدر علــى بيــع‬\n      ‫املــواد املخــدرة وأنــه كان برفقتــه بغــرض تعاطــي املــواد املخــدرة ســويا‬\n      ‫وباســتجواب ‪ ......‬أنكــر عالقتــه مبــا قــام بــه ‪ ....‬مــن بيــع للمــواد املخــدرة‬\n      ‫وأفــاد أنــه كان متواجــد برفقــه ‪ ....‬بغــرض تعاطــي املــواد املخــدرة فقــط‬\n      ‫وأضــاف أن مــا مت العثــور عليــه مــن قطعــه للحشــيش املخــدر بعــد القبــض‬\n      ‫عليهمــا تعــود ‪ ......‬وأمــا األعقــاب املضبوطــة فقــد قــام بتعاطيهــا مــع ‪....‬‬\n      ‫وأقــر بتعاطيــه للحشــيش املخــدر وقــد انتهــى التحقيــق إلــى اتهــام ‪......‬‬\n      ‫باآلتــي‪ -1‬ببيــع مــا وزنــه (‪ )5.3‬خمســة جرامــات وثــاث أعشــار اجلــرام‬\n      ‫مــن مــادة احلشــيش املخــدر بقصــد االجتــار‪ -2‬بحيازتــه ملــا وزنــه(‪)3.8‬‬\n      ‫ثالثــة جرامــات وثمانيــة أعشــار اجلــرام مــن مــادة احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي‪ -3‬بحيازتــه لعقبــي ســيجاره ملفوفــه لــف يــدوي مدخنــه‬\n      ‫بلــغ وزنهــا (‪ )0.5‬خمســه مــن العشــرة مــن اجلــرام حتتــوي علــى مــادة‬\n      ‫احلشــيش املخــدر بقصــد التعاطــي ‪ -4‬بتعاطــي احلشــيش املخــدر كمــا‬\n      ‫أقــرر اتهــام ‪ ......‬باآلتــي ‪ -1‬باالشــتراك بحيــازة عقبــي ســيجاره ملفوفــه‬\n\n\n‫‪261‬‬\n\f‫لــف يــدوي مدخنــه بلــغ وزنهــا (‪ )0.5‬خمســه أعشــار اجلــرام حتتــوي علــى‬\n‫مــادة احلشــيش املخــدر بقصــد التعاطــي ‪ -2‬بتعاطــي احلشــيش املخــدر‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ -1‬مــا ورد يف أقوالهمــا‪ -2‬محضــر‬\n‫الضبــط والتفتيــش‪ -3‬التقريــر الكيميائــي الشــرعي وحيــث إن مــا‬\n‫أقــدم عليــه املذكوريــن‪ -‬وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا ‪-‬‬\n‫ـب عليــه شــرع ًا ونظامـ ًا أطلــب إثبــات مــا ُأســند إليهمــا‬‫فعــلٌ محــرم ومعاقـ ٌ‬\n‫وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واحلكــم‬\n‫عليهمــا مبــا يلــي ‪ -1 -:‬احلكــم علــى ‪ ......‬بعقوبــة الســجن واجللــد‬\n‫والغرامــة الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n‫املخــدرات مــع مراعــاة مــا تضمنتــه املــادة (‪ )62‬مــن النظــام ‪ -2‬احلكــم‬\n‫علــى ‪ ......‬بعقوبــة الســجن الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم‬\n‫(‪ )41‬مــن النظــام ‪3‬ـ مبنعهمــا مــن الســفر وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )56‬مــن نظــام مكافحــة املخــدرات‪4 .‬ـ مصــادرة الهاتــف اجلــوال العائــد‬\n‫‪ ......‬ذو الرقــم املصنعــي (‪ )......‬املســتخدم يف عمليــة الترويــج تطبيق ـ ًا‬\n‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات مــع إســقاط‬\n‫رقــم شــريحه اجلــوال املســتخدم يف عمليــه الترويــج وفق ـ ًا لتعميــم ســمو‬\n‫وزيــر الداخليــة رقــم (‪ )9798‬يف ‪1428/2/10‬ه ـ وبــاهلل التوفيــق ويف‬\n‫هــذه اجللســة حضــر املدعــى عليــه الثانــي ‪ ......‬مبوجــب بيانــات مواطــن‬\n‫مصــدق مــن مكافحــة املخــدرات ‪ ......‬املــدون بــه رقــم الهويــة ‪ ......‬وأمــا‬\n‫املدعــى عليــه األول ‪ ......‬فهــو مطلــق بالكفالــة ولــم يحضــر وبعــرض‬\n‫ا ‪ :‬مــا‬‫دعــوى املدعــي العــام علــى املدعــى عليــه الثانــي ‪ ......‬أجــاب قائ ـ ً‬\n‫ذكــره املدعــي العــام يف دعــواه فيمــا يخصنــي صحيــح حيــث بعــت علــى‬\n‫املصــدر قطعــة احلشــيش املخــدر املذكــورة يف الدعــوى وســلمت لــه هــذه‬\n\n\n                                                                                          ‫‪262‬‬\n\f      ‫القطعــة واســتلمت املبلــغ املرقــم املذكــور واســتخدمت هاتفــي اجلــوال‬\n      ‫املشــار إليــه يف الدعــوى للتنســيق مــع املصــدر يف عمليــة البيــع كمــا‬\n      ‫قــد كان يف حيازتــي مــا ُوجــد يف منزلــي مــن قطعــة احلشــيش املخــدر‬\n      ‫وعقبــي ســيجارتني حتتــوي احلشــيش املخــدر وكانــت حيازتــي لذلــك‬\n      ‫كلــه بقصــد التعاطــي حيــث أن الســيجارتني املذكورتــن كانــت يف‬\n      ‫األســاس لــي وتعاطــي واحــد ًة منهــا املدعــى عليــه األول ‪ ......‬وقــد تعاطيــت‬\n      ‫احلشــيش املخــدر يف نفــس يــوم القبــض ولــم يســبق أن صــدر علــي حكـ ٌـم‬\n      ‫بحــد املســكر هــذه إجابتــي ‪ .‬فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث صــادق املدعــى عليــه الثانــي ‪ ......‬علــى دعــوى املدعــي العــام وأقــر‬\n      ‫ببيعــه لقطعــة احلشــيش املخــدر املذكــورة يف الدعــوى واســتخدامه‬\n      ‫لهاتفــه اجلــوال يف هــذه العمليــة وأقــر بحيازتــه ملــا ُوجــد يف منزلــه مــن‬\n      ‫قطعــة حشــيش مخــدر وعقبــي ســيجارتني حتتــوي احلشــيش املخــدر‬\n      ‫بقصــد التعاطــي وأقــر بتعاطيــه للحشــيش املخــدر وبعــد االطــاع علــى‬\n      ‫طيــات املعاملــة ومــن ضمنهــا التقريــر الكيمــاوي الشــرعي الصــادر مــن‬\n      ‫املركــز اإلقليمــي ملراقبــة الســموم باملنطقــة الشــرقية برقــم ( ‪) ......‬‬\n      ‫املتضمــن إيجابيــة العينتــن رقــم ( ‪ )......‬و (‪ ) ......‬ملــادة احلشــيش املخــدر‬\n      ‫ـاء علــى‬\n              ‫واحتــواء العينــة رقــم ( ‪ ) ......‬علــى مــادة احلشــيش املخــدر وبنـ ً‬\n      ‫الفقــرة ( ‪ ) 2‬مــن املــادة رقــم ( ‪ ) 3‬والفقــرة (‪ ) 1‬مــن املــادة رقــم ( ‪) 38‬‬\n      ‫واملــادة رقــم ( ‪ ) 53‬والفقــرة ( ‪ ) 1‬مــن املــادة رقــم ( ‪ ) 56‬والفقــرة ( ‪) 1‬‬\n      ‫مــن املــادة رقــم (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫ولعــدم وجــود ســوابق علــى املدعــى عليــه الثانــي ‪ ......‬وصغــر ســنه وقلــة‬\n      ‫الكميــة املباعــة نســبي ًا ممــا يســتدعي إعمــال مقتضــى الفقــرة ( ‪ ) 1‬مــن‬\n      ‫املــادة رقــم ( ‪ ) 60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n\n\n‫‪263‬‬\n\f‫لذلــك كلــه فقــد قــررت مــا يلــي ‪ :‬أوالً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه‬\n‫الثانــي ‪ ......‬بترويــج قطعــة احلشــيش املخــدر املذكــورة يف الدعــوى البالــغ‬\n‫وزنهــا ( ‪ ) 5.3‬خمســة جرامــات وثالثــة مــن العشــرة مــن اجلــرام عــن طريق‬\n‫البيــع وقــررت معاقبتــه علــى ذلــك مبــا يلــي ‪ :‬أ‪ -‬ســجنه ملــدة ســنتني وثالثــة‬\n‫ـداء مــن تاريــخ إيقافــه وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت‬ ‫أشــهر ابتـ ً‬\n‫دفعــات متســاوية بــن كل دفعــة وأخــرى مــا ال يقــل عــن خمســة عشــر‬\n‫يوم ـ ًا وتغرميــه مبلغ ـ ًا وقــدره ( ‪ ) 1000‬ألــف ريــال ‪ .‬ب‪ -‬منعــه مــن الســفر‬\n‫ملــدة ســنتني وثالثــة أشــهر تبــدأ بعــد انتهــاء عقوبــة الســجن املقــررة‬\n‫يف حقــه يف الفقــرة ( أ ) مــن هــذا البنــد ‪ .‬ج‪ -‬مصــادرة هاتفــه اجلــوال‬\n‫املذكــور رقمــه املصنعــي يف الدعــوى الســتخدامه يف عمليــة البيــع‬\n‫املذكــورة مــع إســقاط شــريحة الهاتــف اجلــوال وعــدم صرفهــا لنفــس‬\n‫املدعــى عليــه ‪ .‬ثانيـاً‪ -‬ثبــت لــدي إدانــة املدعــى عليــه الثانــي ‪ ......‬بحيــازة‬\n‫قطعــة احلشــيش املخــدر املشــار إليهــا يف الدعــوى البالــغ وزنهــا ( ‪3.8‬‬\n‫) ثالثــة جرامــات وثمانيــة مــن العشــرة مــن اجلــرام وعقبــي ســيجارتني‬\n‫مدخنتــن وزنهمــا ( ‪ ) 0.5‬خمســة مــن العشــرة مــن اجلــرام وذلــك كلــه‬\n‫بقصــد التعاطــي وعقوبتــه يف ذلــك داخلــة يف العقوبــة الصــادرة يف حقــه‬\n‫ـاء بالعقوبــة األشــد ‪ .‬ثالث ـاً‪ -‬ثبــت لــدي إدانــة‬ ‫يف البنــد ( أو ًال ) اكتفـ ً‬\n‫املدعــى عليــه الثانــي ‪ ......‬بتعاطــي احلشــيش املخــدر وقــررت جلــده حــد‬\n‫املســكر ثمانــن جلــدة دفع ـ ًة واحــده علن ـ ًا مبجمـ ٍـع مــن النــاس علــى أن‬\n‫ُيفـ ّـرق بــن هــذا اجللــد واجللــد الصــادر يف حقــه يف الفقــرة ( أ ) مــن البنــد‬\n‫( أو ًال ) مبــد ٍة ال تقــل عــن خمســة عشــر يومـ ًا واكتفيــت مبــا صــدر عليــه‬\n‫مــن منـ ٍـع مــن الســفر املذكــور يف الفقــرة ( ب ) مــن البنــد ( أو ًال ) وبذلــك‬\n‫أجمــع حكمــت وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n\n\n                                                                                          ‫‪264‬‬\n\f      ‫الثانــي ‪ ......‬القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفــع احلكــم‬\n      ‫حملكمــة االســتئناف واكتفــى بالئحــة الدعــوى وأوراق املعاملــة عــن‬\n      ‫تقــدمي الئح ـ ٍة اعتراضيــة ف ُأجيــب لطلبــه وأمــا بالنســبة للمدعــى عليــه‬\n      ‫األول ‪ ......‬فســوف يتــم النظــر يف الدعــوى ضــده حــال حضــوره واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬احلمــد هلل‬\n      ‫وحــده وبعــد ويف يــوم االربعــاء املوافــق ‪ ......‬فتحــت اجللســة وقــد وردت‬\n      ‫املعاملــة مــن محكمــة االســتئناف باملنطقــة ‪ ......‬مبوجــب اخلطــاب رقــم‬\n      ‫‪ ......‬يف ‪ ......‬وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة ‪ ......‬رقــم ‪ ......‬يف ‪ ......‬املتضمــن‬\n      ‫املصادقــة علــى احلكــم لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى‬\n                                                                ‫نبينــا محمــد وآلــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة ‪ ......‬علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة ‪ ......‬برقــم ‪ ......‬وتاريــخ ‪ ......‬املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ ......‬وتاريــخ ‪ ......‬املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪ ......‬املســجل برقــم ‪ ......‬وتاريــخ‬\n      ‫‪ ......‬اخلــاص بدعوى‪/‬املدعــى العــام ضــد‪ ......-2 ...... -1/‬يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــه‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                          ‫وســلم حــرر يف ‪1434/4/17‬ه ـ‬\n\n\n\n\n‫‪265‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":258,"source_page_end":265,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ddf0a49efafe4a9124f4e67c7314b8eae49ad697fc148892831b5cdf8aadfe89","normalized_text_hash":"2a687e23548bbdb7dbff57dfc19db85319062eabad8e271d4ffc4ebee5d5fd02","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p258-3444750"},{"id":"0a5a073a-8d29-52dc-95cc-f593d53a2ec4","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج حبوب محظورة -حيازة احلشيش -حيازة ساح حتقيقا -تقرير كيميائي -نظر اجلرمية بدون ترخيص -إقرار األخرى أمام المحكمة املختصة -عليه سابقة ترويج مخدرات - شهادة شهود -إدانة -سجن وجلد -غرامة -مصادرة ومنع من السفر -إخاء سبيل مرافق املتهم.","document_number":"34248603","case_number":"3411277","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/27","year":"1434","subject":"مخدرات -ترويج حبوب محظورة -حيازة احلشيش -حيازة ساح حتقيقا -تقرير كيميائي -نظر اجلرمية بدون ترخيص -إقرار األخرى أمام المحكمة املختصة -عليه سابقة ترويج مخدرات - شهادة شهود -إدانة -سجن وجلد -غرامة -مصادرة ومنع من السفر -إخاء سبيل مرافق املتهم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34248603 :‬تاريخه‪1434/01/27 :‬هـ‬\n                      ‫رقم الدعوى‪3411277:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34169849‬تاريخه‪1434/3/23 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج حبــوب محظــورة ‪ -‬حيــازة احلشــيش‪ -‬حيــازة ســاح‬\n ‫حتقيقــا‪ -‬تقريــر كيميائــي ‪ -‬نظــر اجلرميــة‬\n                                           ‫ً‬      ‫بــدون ترخيــص ‪ -‬إقــرار‬\n ‫األخــرى أمــام احملكمــة املختصــة ‪ -‬عليــه ســابقة ترويــج مخــدرات ‪-‬‬\n ‫شــهادة شــهود ‪ -‬إدانــة ‪ -‬ســجن وجلــد ‪ -‬غرامــة ‪ -‬مصــادرة ومنــع مــن‬\n                                 ‫الســفر ‪ -‬إخــاء ســبيل مرافــق املتهــم‪.‬‬\n\n\n\n\n                 ‫‪ .1‬قوله تعالى «وال تفسدوا يف األرض بعد إصالحها»‪.‬‬\n ‫‪ .2‬الفقــرة (‪ )1‬مــن املــادة (‪ )39‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n         ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واﻤﻟﺆﺛﺮات اﻟﻌﻘﻠﻴﺔ‪.‬‬\n\n\n\n\n        ‫أقام املدعى العام دعواه ضد املدعى عليه طالب ًا احلكم عليه ب ـ ـ ـ‬\n                 ‫‪ .1‬إدانته بترويج حبوب مخدرة عن طريق البيع للمرة الثانية‪.‬‬\n ‫‪ .2‬تعاطــي احلبــوب احملظــورة وحيــازة احلشــيش بقصــد االســتعمال‬\n                                                               ‫ا لشــخصي ‪.‬‬\n ‫‪ .3‬تطبيــق الفقــرة ‪ 2‬مــن املــادة ‪ 3‬مــن نظــام مكافحــة املخــدرات‬\n                                                     ‫واملؤثــرات العقليــة‪.‬‬\n ‫ومبواجهــة املدعــى عليــه أنكــر التهمــة وشــكك يف حــدوث املكاملــة‬\n\n                                                                                     ‫‪266‬‬\n\f      ‫الهاتفيــة وأنــه أقــر يف التحقيــق حتــى يخــرج ابــن اختــه مــن القضيــة‬\n      ‫‪،‬وبعــد أن اســتمعت احملكمــة للشــهود وأطلعــت علــى محاضــر الضبــط‬\n                   ‫والتقاريــر وقارنــت بــن أقــوال الطرفــن قــررت احملكمــة‪:‬‬\n      ‫إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة وحيــازة احلشــيش مــن دون‬\n      ‫قصد خاص ‪ ،‬ورد طلب املدعى العام بالقتل تعزيراً‪،‬وحكمت بسجنه‬\n      ‫‪ 18‬عــام وجلــده ‪ 1800‬جلــدة وتغرميــه مائــة ألــف ريــال ســعودي‪،‬ومنعه‬\n      ‫مــن الســفر خمســة عشــر عــام ومصــادرة اجلــوال وإيــداع قيمتــه حلســاب‬\n      ‫االدارة العامــة ملكافحــة املخدرات‪،‬والغــاء الشــريحة الســعودية والزامــه‬\n           ‫بســداد مبلــغ مائــة ألــف ريــال ســعودي إلدارة مكافحــة املخــدرات ‪.‬‬\n      ‫ولــم يقنــع كل مــن املدعــى العــام واملدعــى عليه‪،‬وجــرى التصديــق مــن‬\n                                              ‫محكمــة اإلســتئناف بعــد التعديــل‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدينــا‬\n      ‫نحــن ‪ .......‬القضــاة باحملكمــة العامــة بنجــران وبنــاء علــى املعاملــة‬\n      ‫الــواردة إلينــا مــن فــرع هيئــة التحقيــق واالدعــاء العــام مبنطقــة جنــران‬\n      ‫برقــم ‪............‬وتاريــخ ‪1434/01/03‬ه ـ واملقيــدة باحملكمــة العامــة‬\n      ‫بنجــران برقــم‪ .......‬يف ‪1434/01/07‬ه ـ واحملالــة للمكتــب القضائــي‬\n      ‫‪ ........‬برقــم ‪ .........‬يف ‪1434/01/07‬ه ـ حضــر املدعــي العــام ‪........‬‬\n      ‫مبوجــب خطــاب التكليــف رقــم ه ـ ن ‪ ........‬مدعيـ ًا علــى احلاضــر معــه يف‬\n      ‫مجلــس احلكــم ‪ .......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫ا يف دعــواه بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة اإلدعــاء العــام‬\n                                                                       ‫‪ ...........‬قائ ـ ً‬\n      ‫لفــرع الهيئــة مبنطقــة جنــران أدعــي علــى املذكــور أعــاه أنــه ورديف‬\n\n‫‪267‬‬\n\f‫محضــر الشــراء املعــد مــن قبــل الفرقــة القابضــة لــدى مكافحــة‬\n‫املخــدرات بنجــران أنــه بتاريــخ ‪1433/11/21‬ه ـ حضــر لديهــم أحــد‬\n‫املصادر الســريني وأبدى اســتعداده بالتعاون واإلطاحة بأحد املروجني‪،‬‬\n‫فتــم تكليــف أحــد أفــراد الفرقــة وترقيــم مبلغ (‪ )100‬مائة ريال ســعودي‬\n‫واالتصــال علــى ذلــك املــروج علــى جوالــه رقــم (‪ )........‬فوافــق املــروج‬\n‫وطلــب مــن املصــدر احلضــور إليــه إلــى حــي ‪ ،....‬وبعــد الوصــول إلــى ‪.....‬‬\n‫مت االتصــال عليــه وذكــر لــه املصــدر بأنــه قريــب مــن منــزل املــروج‪،‬‬\n‫فقابلهــم ذلــك املــروج علــى ســيارة نــوع ‪ .........‬بيضــاء اللــون حتمــل اللوحــة‬\n‫رقــم (‪ )...........‬وقــام املــروج باســتالم املبلــغ مــن املصــدر وإخــراج كيــس‬\n‫بــه كميــة مــن احلبــوب احملظــورة وأعطــى املصــدر عــدد (‪ )2‬حبتــن‬\n‫يشــتبه أن تكــون مــن احلبــوب احملظــورة حتمــان عالمــة الكبتاجــون‬\n‫املميــزة وقــام بتســليمها الفــرد املكلــف مــع املصــدر‪ .‬كمــا ورد يف‬\n‫محضــر القبــض والتفتيــش املعــد مــن قبــل الفرقــة القابضــة مبكافحــة‬\n‫املخــدرات بنجــران أنــه بتاريــخ ‪1433/11/24‬ه ـ ويف متــام الســاعة‬\n‫ـاءا وأثنــاء مراقبــة أحــد األشــخاص املطلوبــن لهــم يف قضية‬      ‫العاشــرة مسـ ً‬\n‫ترويــج مســبق‪ ،‬مت مالحظــة املتهــم علــى ســيارة مــن نــوع ‪ ............‬فتمــت‬\n‫مراقبتــه وذلــك يف حــي‪ ،.........‬وأثنــاء وقوفــه مت النــزول إليــه واتضــح أنــه‬\n‫املتهــم أعــاه وبتفتيشــه شــخصي ًا مليعثــر معــه علــى شــيء مــن املمنوعــات‬\n‫وقــد ضبــط معــه اجلــوال الــذي مت تنســيق عمليــة الترويــج مــن خاللــه‬\n‫والــذي كان يحمــل الرقــم (‪ ،)..........‬واتضــح أنــه يرافقــه املدعــو ‪/‬‬\n‫‪ ،...........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪).........‬‬\n‫وبتفتيشــه شــخصي ًا وبتفتيــش الســيارة التــي كانــا يســتقالنها لــم يتــم‬\n‫العثــور علــى شــيء مــن املمنوعــات‪ ،‬وبفحــص جــوال املدعــو (‪)..........‬‬\n\n\n                                                                                         ‫‪268‬‬\n\f      ‫عثــر يف جوالــه علــى صــور حبــوب محظورة فتم التحفظ على األشــخاص‬\n      ‫ونقلهــم إلــى مقــر إدارة مكافحــة املخــدرات بنجــران ‪ -‬وباالنتقــال إلــى‬\n      ‫منــزل املتهــم املذكــور برفقــة عضــو هيئــة األمــر باملعــروف والنهــي عــن‬\n      ‫املنكــر والســجانات وبتفتيشــه عثــر علــى قطعــة ســمراء اللــون يشــتبه أن‬\n      ‫تكــون مــن مــادة احلشــيش املخــدر بلــغ وزنهــا (‪ 0.9‬جــم) تســعة أعشــار‬\n      ‫اجلــرام كانــت مخبأةخلــف جهــاز التلفزيــون‪ ،‬كمــا عثــر علــى مســدس‬\n      ‫نــوع ‪ ....‬يحمــل الرقــم (‪ )........‬وكذلــك وجــد به عدد (‪ )31‬واحد وثالثني‬\n      ‫طلقــة حيــة مخبــأة بــن الفــرش‪ ،‬ومت تســليم املنــزل ألخــي املتهــم املدعــو‬\n      ‫(‪ ، .)...........‬اإلجــراءات املتخــذة مت إيقافــه وإيداعــه شــعبة الســجن العــام‬\n      ‫بنجــران اســتنا ًدا للقــرار الــوزاري (‪ )1900‬املبنــي علــى املــادة (‪ )112‬مــن‬\n      ‫نظــام اإلجــراءات اجلزائيــة ‪ -‬مت مخاطبــة مكافحــة املخــدرات بنجــران‬\n      ‫بشــأن مصــدر املخــدرات املضبوطــة مــع املتهــم مبوجــب اخلطــاب رقــم‬\n      ‫(‪ )...........‬وتاريــخ ‪1433/11/28‬ه ـ ‪ ،‬مت رد الســيارة املضبوطــة بقيــادة‬\n      ‫املتهــم ملالكهــا مبوجــب أمــر رد املضبوطــات رقــم (‪ ).........‬وتاريــخ‬\n      ‫‪1433/11/28‬ه ـ ‪ ،‬مت حفــظ األوراق بحــق مرافــق املتهــم (‪).........‬‬\n      ‫اســتنا ًدا للمــادة (‪ )62‬الثانيــة والســتني مــن نظــام اإلجــراءات اجلزائيــة‪، .‬‬\n      ‫مت فــرز أوراق مســتقلة بشــأن قضيــة الســاح الختــاف جهــة التقاضــي‬\n      ‫وأحيلــت ملكافحــة املخــدرات بنجــران الســتكمال إجراءاتهــا مبوجــب‬\n      ‫اخلطــاب رقــم (‪ ).......‬وتاريــخ ‪1433/11/30‬هــ‪ - .‬وبســماع أقــوال املتهــم‬\n      ‫‪ /‬أفــاد بأنــه يســتخدم احلبــوب احملظــورة منــذ مايقــارب ثمــان ســنوات‪.‬‬\n      ‫وباســتجواب املتهــم‪ /‬أقــر بأنــه قــد روج عــدد (‪ )2‬حبتــن مــن احلبــوب‬\n      ‫احملظــورة بطريــق بيعهــا ألحــد املصــادر الســرية ملكافحــة املخــدرات‬\n      ‫بنجــران بتاريــخ ‪1433/11/21‬هــ‪ ،‬كمــا أقــر بحيازتــه لقطعــة مــن‬\n\n\n‫‪269‬‬\n\f‫احلشــيش املخــدر بلــغ وزنهــا (‪ 0.9‬جــم) بقصــد االســتخدام الشــخصي‪،‬‬\n‫وأنه يتعاطى احلبوب احملظورة يف السابق‪ - .‬وأثبت التقرير الكيميائي‬\n‫الشــرعي رقــم (‪ ).........‬الصــادر مــن مركــز مراقبــة الســموم والكيمياء‬\n‫الطبيــة الشــرعية مبنطقــة مكــة املكرمــة أن العينــة املرســلة باحلــرز‬\n‫الســري رقــم (‪ )........‬حتتــوي علــى احلشــيش املخــدر واملــادة الفعالــة لــه‪،‬‬\n‫واحلشــيش املخــدر مــن املــواد املدرجــة بجــداول املخــدرات واملؤثــرات‬\n‫العقليــة رقــم (‪ 1‬فئــة أ) امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪.‬‬\n‫كمــا أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ ).......‬الصــادر مــن‬\n‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة‬\n‫املكرمــة أن العينــة املرســلة باحلــرز الســري رقــم (‪ )...........‬حتتــوي علــى‬\n‫مــادة االمفيتامــن ‪ ،‬واالمفيتامــن مــن املــواد املدرجــة بجــداول املخدرات‬\n‫واملؤثــرات العقليــة رقــم (‪ 2‬فئــة ب) امللحقــة بنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ‬\n‫‪1426/7/8‬هــ‪ .‬وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة ترويــج‬\n‫مخــدرات وباإلطــاع علــى قرارهــا اتضــح أنهــا مثبتــة لإلدانــة كمــا‬\n‫يتضــح مــن القــرار رقــم (‪ )4/23‬وتاريــخ ‪1430/8/13‬ه ـ الصــادر مــن‬\n‫احملكمــة اجلزئيــة بنجــران ‪ .‬وانتهــى التحقيــق بتوجيــه االتهــام ل ـ ‪/‬‬\n‫‪................‬بترويــج (‪ )2‬حبتــن مــن احلبــوب احملظــورة احملتويــة علــى‬\n‫مادةاالمفيتامــن املؤثــرة عقليـ ًا عــن طريــق البيــع للمــرة الثانيــة وبتعاطيــه‬\n‫للحبــوب احملظــورة يف الســابق وبحيازتــه لقطعــة مــن احلشــيش املخــدر‬\n‫ا‬\n‫بلــغ وزنهــا (‪0.9‬جــم) بقصــد االســتخدام الشــخصي ممــا يعــد فع ـ ً‬\n‫مجرم ـ ًا اســتناد ًا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة‬\n\n\n                                                                                        ‫‪270‬‬\n\f      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي (م‪ )39/‬وتاريــخ‬\n      ‫‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف أقوالــه‬\n      ‫حتقيقــا املنــوه عنهــا املدونــة علــى الصفحتــن رقــم(‪ )6-1‬وإقــراره‬\n      ‫بالترويــج املــدون علــى الصفحــة رقــم (‪ )3‬مــن دفتــر التحقيــق املرفــق لفــة‬\n      ‫رقــم (‪ -2 )16‬مــا جــاء يف ســماع أقوالــه املنــوه عنهــا املدونــة على الصفحة‬\n      ‫رقــم (‪ )18‬مــن محضــر ضبــط اإلجــراءات األوليــة املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ -3‬محضــري الشــراء والقبــض والتفتيــش املنــوه عنهمــا املدونــان علــى‬\n      ‫الصفحــات رقــم (‪ )11،2‬مــن محضــر ضبــط بنجــران فصحيــح أمــا مــا‬\n      ‫ذكــره املدعــي العــام مــن أنــي قمــت بترويــج حبتــن من احلبــوب احملظورة‬\n      ‫فغيــر صحيــح وأمــا مــا ذكــره املدعــي العــام مــن انــه ورد إلــي اتصــال‬\n      ‫وعلــى إثــره قمــت ببيــع حبتــن فــا أعتقــد أنــه صحيــح هكــذا أجــاب‬\n      ‫ا بينتــي مــا هــو مرفــق‬  ‫وبســؤال املدعــي العــام عــن بينتــه أجــاب قائ ـ ً‬\n      ‫بــأوراق املعاملــة مــن أقــوال املدعــى عليــه حتقيق ـ ًا وأقوالــه األوليــة‬\n      ‫ومحضــري الشــراء والقبــض والتفتيــش والتقريريــن الكيميائيــن‬\n      ‫الشــرعيني املثبتــن إليجابيــة املــادة املروجــة هكــذا أجــاب ثــم جــرى منــا‬\n      ‫اإلطــاع علــى اإلقــرار املرفــق باملعاملــة باللفــة (‪ )16‬بالصفحــة رقــم (‪)3‬‬\n      ‫مــن ملــف التحقيــق رقــم (‪ )1‬ونصــه ( أقــر أنــا ‪ .........../‬ســعودي اجلنســية‬\n      ‫مبوجــب الهويــة الوطنيــة رقــم (‪ )..........‬وأنــا بكامــل قــواي العقليــة‬\n      ‫املعتبــرة شــرع ًا ومــن غيــر إكــراه وال إجبــار مــن احــد بأنــي قــد روجــت‬\n      ‫علــى أحــد املصــادر بتاريــخ ‪1433/11/21‬ه ـ عــدد (‪)2‬حبتــن من احلبوب‬\n      ‫احملظــورة مقابــل (‪)100‬مائــة ريــال ســعودي كمــا أقــر بحيــازة قطعــة مــن‬\n      ‫احلشــيش املخــدر بلــغ وزنهــا (‪0.9‬جــم) بقصــد االســتخدام الشــخصي‬\n      ‫وأقــر بحيــازة ســاح نــوع مســدس ‪ .....‬وذخيــرة حيــة وهــي جميعهــا عائــدة‬\n\n\n‫‪271‬‬\n\f‫لــي أنــا وليــس ملرافقــي (‪ )..........‬أي عالقــة أو علــم بهــا وعلــى ذلــك أقــر‬\n‫وأوقــع ) كمــا جــرى منــا اإلطــاع علــى األقوال األوليــة املدونة بالصفحة‬\n‫رقــم (‪ )18‬مــن ملــف اإلجــراءات األوليــة املرفــق باملعاملــة لفــة رقــم (‪)1‬‬\n‫واملتضمــن إنــكاره بترويــج شــيء مــن احلبــوب وإقراره باســتخدام احلبوب‬\n‫احملظــورة مــن ســبع إلــى ثمــان ســنوات وإقــراره بأنــه مت القبــض علــي‬\n‫بقضيــة بيــع حبــوب مخــدرات قبــل ثمــان ســنوات وبعــرض ذلــك علــى‬\n‫ا أمــا األقــوال األوليــة فصــدرت منــي وهــي‬       ‫املدعــى عليــه أجــاب قائ ـ ً‬\n‫صحيحــة وأمــا اإلقــرار حتقيق ـ ًا فصحيــح أنــه صــدر منــي إال أنــي قلتــه‬\n‫بغيــة يف إخــراج ابــن أختــي املرافــق معــي أثنــاء القبــض ‪................‬مــن‬\n‫القضيــة ولكــن الصحيــح مــا ذكــرت آنفـ ًا مــن أنــي لــم أروج شــيئ ًا مــن‬\n‫احلبــوب احملظــورة هكــذا أجــاب ثــم جــرى منــا اإلطــاع علــى محضــري‬\n‫الشــراء والقبــض والتفتيــش املرفــق باملعاملــة علــى الصفحــات (‪)2,11‬‬\n‫فوجدنــاه مطابقـ ًا ملــا ذكــره املدعــي العــام ثــم جــرى منــا اإلطــاع علــى‬\n‫التقريــر الكيميائــي الشــرعي رقــم ‪.........‬الصــادر مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة مكــة املكرمــة برقــم‬\n‫‪47/205/1/29706‬م يف ‪1433/12/4‬ه ـ املرفــق باملعاملــة لفــة (‪)40‬‬\n‫واملتضمــن إيجابيــة املــادة املفحوصــة وأنهــا مــن احلشــيش املخــدر كمــا‬\n‫جــرى منــا االطــاع علــى التقريــر الكيميائــي الشــرعي رقــم ‪.........‬‬\n‫الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية‬\n‫مبنطقــة مكــة املكرمــة برقــم ‪ .........‬يف ‪1433/11/30‬ه ـ املرفــق‬\n‫باملعاملــة باللفــة (‪ )39‬واملتضمــن إيجابيــة املــادة املفحوصــة املســتخدمة‬\n‫يف الترويــج وأنهــا حتتــوي علــى مــادة االمفيتامــن كمــا جــرى منــا‬\n‫اإلطــاع علــى صــورة مــن القــرار الشــرعي الصــادر مــن احملكمــة‬\n\n\n                                                                                        ‫‪272‬‬\n\f      ‫اجلزئيــة بنجــران رقــم ‪ 4/23‬يف ‪1430/8/13‬ه ـ واملتضمــن إدانــة املدعــى‬\n      ‫عليــه بترويــج خمــس وعشــرين حبــة محظــورة املــرة األولــى وإدانتــه‬\n      ‫بحيــازة بعــض احلبــوب احملظــورة بقصــد التعاطــي ويف جلســة أخــرى‬\n      ‫ال مــن‬\n            ‫حضــر فيهــا الطرفــان وأحضــر املدعــي العــام معــه للشــهادة ك ً‬\n      ‫‪ .......‬اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬و ‪ ........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وبســؤالهما عــن تاريــخ‬\n      ‫ا بأنــي مــن‬   ‫مولدهمــا وعملهمــا ومقــر إقامتهمــا فأجــاب ‪ ..........‬قائ ـ ً‬\n      ‫مواليــد ‪ ........‬ه ـ وأســكن ‪ ....‬وأعمــل مبكافحــة املخــدرات مبنطقــة‬\n      ‫ا بأنــي مــن مواليــد ‪ ......‬وأســكن بيشــه‬           ‫جنــران ثــم أجــاب ‪ .....‬قائ ـ ً‬\n      ‫وأعمــل مبكافحــة املخــدرات مبنطقــة جنــران كمــا جــرى ســؤالهما‬\n      ‫ا وردنــا بــاغ مــن أحــد املصــادر الســرية‬   ‫عــن شــهادتهما أجــاب ‪ .........‬قائـ ً‬\n      ‫بقيــام املدعــى عليــه ببيــع احلبــوب احملظــورة وأبــدى اســتعداده بالتعــاون‬\n      ‫ويف يــوم األحــد املوافــق ‪1433/11/21‬ه ـ ثــم اتصــال املصــدر علــى‬\n      ‫ا أبي أشــتري منك حبوب‬            ‫املدعــى عليــه وطلــب منــه حبوبـ ًا محظــورة قائـ ً‬\n      ‫فقــال املدعــى عليــه تعالــى للبيــت يف ‪.........‬ثــم انتقلــت مــع املصــدر إلــى‬\n      ‫بيــت املدعــى عليــه ونــزل املصــدر مــن الســيارة ووقفــت بالقــرب منهــم‬\n      ‫وأنــا أشــاهد جيــد ًا فقــام املصــدر بتســليم املدعــى عليــه املبلــغ وقــام‬\n      ‫املدعــى عليــه بإخــراج كيــس مــن احلبــوب ثــم أخــرج منــه حبتــن وســلمها‬\n      ‫للمصــدر ثــم ركــب املصــدر وانصرفنــا هــذه شــهادتي وبســؤاله هــل‬\n      ‫ا لــم يكــن معــي ســوى املصــدر حيــث إن‬        ‫كان برفقتــه أحــد أجــاب قائـ ً‬\n      ‫املروجــن ال يقومــون ببيــع احلبــوب احملظــورة اذا كان مــع املشــتري‬\n      ‫أكثــر مــن شــخص هكــذا أجــاب وبســؤال الشــاهد اآلخــر ‪ .........‬لديــه‬\n      ‫ا بأنــه لــم يســتمع للمكاملــات ولــم يشــاهد‬             ‫مــن شــهادة أجــاب قائ ـ ً‬\n\n\n‫‪273‬‬\n\f‫االســتالم والتســليم هكــذا قــرر وبعــرض الشــهادة والشــهود علــى‬\n‫ا أمــا الشــهادة فغيــر صحيحــة وامنــا الصحيــح‬       ‫املدعــى عليــه أجــاب قائ ـ ً‬\n‫مــا ذكرتــه أنــا وأمــا الشــهود فــا أعرفهــم ال بخيــر وال بشــر هكــذا‬\n‫أجــاب ويف جلســة أخــرى حضــر املدعــي العــام وأحضــر مزكيــن‬\n‫ا‬‫لشــاهديه وهــم كل مــن ‪ ........‬وشــهد كل واحــد منهمــا مبفــرده قائـ ً‬\n‫أنــي أعــرف الشــاهدين ‪ ........‬معرفــة جيــدة وأنهمــا عــدالن ثقتــان عــرف‬\n‫عنهمــا الصــدق واألمانــة هكــذا شــهد كل واحــد منهمــا مبفــرده ويف‬\n‫ـاء‬\n‫جلســة أخــرى وبعــد التأمــل يف أوراق املعاملــة ومــا ضبــط لدينــا وبنـ ً‬\n‫علــى مــا فيهــا مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه مبــا نســب‬\n‫إليــه يف الدعــوى لــدى جهــة التحقيــق وإقــراره بذلــك يف مجلــس احلكــم‬\n‫إال الترويــج وإقــراره يف مجلــس احلكــم بــأن إقــراره بالترويــج صــدر منــه‬\n‫ودفــع بــأن ســبب إقــراره رغبتــه يف حتمــل القضيــة عــن ابــن أختــه ولكون‬\n‫دفعــه هــذا ضعيــف ال يقبــل إذ لــو كان املدعــى عليــه وابــن أختــه لــم‬\n‫يفعــا جرمـ ًا ملــا احتــاج أحدهمــا أن يتحمــل القضيــة عــن اآلخــر وإلقــراره‬\n‫بعائديــة اجلــوال املذكــور والســيارة املذكــورة إليــه وأن جوالــه ال‬\n‫يســتخدمه غيــره أحــد وكان بحوزتــه أثنــاء القبــض عليــه ولشــهادة‬\n‫شــاهد واحــد معــدل شــرع ًا بــأن اجلــوال الــذي أقــر املدعــى عليــه بعائديتــه‬\n‫إليــه مت مــن خاللــه التنســيق لبيــع حبــوب محظــورة ولشــهادته أيضـ ًا بأنــه‬\n‫شــاهد املدعــى عليــه أخــرج كيس ـ ًا مــن احلبــوب ســلم املصــدر منهــا‬\n‫حبتــن مقابــل مائــة ريــال ســعودي اتضــح فيمــا بعــد أنهــا مــن احلبــوب‬\n‫احملظــورة ولعــدم جــزم املدعــى عليــه بنفــي االتصــال الــوارد إلــى جوالــه‬\n‫بشــأن طلــب حبــوب محظــورة يف مجلــس احلكــم وذلــك بقولــه ( ال أعتقد‬\n‫أنــه صحيــح ) وإلقــراره بحيــازة تســعة أعشــار اجلــرام من احلشــيش املخدر‬\n\n\n                                                                                         ‫‪274‬‬\n\f      ‫ولســابقة الترويــج علــى املدعــى عليــه والثابــت فيــه اقــرار شــرعي والتــي‬\n      ‫أقــر بهــا املدعــى عليــه يف مجلــس احلكــم وللتقريريــن الكيميائيــن‬\n      ‫املرفقــن املثبــت أحدهمــا ايجابيــة املــادة املفحوصــة وأنهــا مــن احلبــوب‬\n      ‫احملظــورة والثانــي بــأن املــادة املفحوصــة مــن احلشــيش املخــدر ولكــون‬\n      ‫القتــل التعزيــري جائــز وليــس بواجــب وألن اخلطــأ يف العفــو خيــر مــن‬\n      ‫اخلطــأ يف العقوبــة وحفظ ـ ًا للدمــاء وخلطــورة املخــدرات وعظــم فســادها‬\n      ‫ولقولــه تعالــى (وال تفســدوا يف األرض بعــد إصالحهــا) وقولــه جــل وعــا‬\n      ‫(واهلل ال يحــب الفســاد) وللبنــد ثانيــا مــن املــادة الســابعة والثالثــن مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وللفقــرة األولــى مــن املــادة‬\n      ‫السادســة واخلمســن مــن ذات النظــام وللفقــرة األولــى مــن املــادة (‪)53‬‬\n      ‫الثالثــة واخلمســن مــن ذات النظــام وللفقــرة األولــى مــن املــادة التاســعة‬\n      ‫والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )47‬وتاريــخ ‪ 1421/2/18‬ه ـ لتعميــم صاحــب‬\n      ‫الســمو امللكــي وزيــر الداخليــة (يرحمــه اهلل) رقــم (‪9798/4/5/1‬س)‬\n      ‫يف ‪ 1428/2/10-9‬ه ـ ولبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة‬\n      ‫(رحمــه اهلل) رقــم ‪ 65980/4/5/1‬وتاريــخ ‪ 1428/10/23-22‬ه ـ‬\n                                        ‫ولذلك كله فقد حكمنا إجماع ًا مبا يلي ‪:‬‬\n      ‫( أو ًال ) إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة املذكــورة يف‬\n                                                                              ‫الدعــوى ‪.‬‬\n      ‫(ثاني ـاً) إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر تــزن‬\n                                      ‫تســعة أعشــار اجلــرام مــن دون قصــد خــاص‪.‬‬\n                             ‫(ثالثا) رد طلب املدعي العام قتل املدعى عليه تعزيراً‪.‬‬\n      ‫(رابعـاً) ســجن املدعــى عليــه مــدة ثمانيــة عشــر عامـ ًا حتتســب منهــا مــدة‬\n\n\n‫‪275‬‬\n\f                                                        ‫إيقافــه علــى ذمــة القضيــة‪.‬‬\n‫(خامس ـاً) جلــد املدعــى عليــه ألــف وثمامنائــة جلــدة مفرقــة علــى دفعــات‬\n                                                  ‫يف كل دفعــة خمســون جلــدة‪.‬‬\n                        ‫(سادساً) تغرمي املدعى عليه مائة ألف ريال سعودي ‪.‬‬\n‫(ســابعاً) منــع املدعــى عليــه مــن الســفر خــارج البــاد بعــد انقضــاء‬\n                                   ‫محكوميتــه ملــدة خمــس عشــرة ســنة ‪.‬‬\n‫(ثامن ـاً) مصــادرة جهــاز اجلــوال املضبــوط مــع املدعــى عليــه واملســتخدم‬\n‫يف عميلــة الترويــج والــذي يحمــل الرقــم املصنعــي (‪ ).........‬وإيــداع قيمتــه‬\n                              ‫يف حســاب اإلدارة العامــة ملكافحــة املخــدرات‪.‬‬\n‫(تاســعاً) إلغــاء الشــريحة الســعودية للرقــم (‪ )................‬وعــدم صرفهــا‬\n                                                             ‫ملــن أســاء اســتخدامها‪.‬‬\n‫(عاشــراً) إلــزام املدعــى عليــه بســداد مبلــغ وقــدره مائــة ريــال ســعودي‬\n‫إلدارة مكافحــة املخــدرات مبنطقــة جنــران مبــا تقــدم حكمنــا وبعرض‬\n‫احلكــم عليهمــا قــرر املدعــي العــام عــدم قناعتــه باحلكــم وطلــب‬\n‫اســتئناف احلكــم ورفعــه واملعاملــة حملكمــة االســتئناف واســتعد بتقــدمي‬\n‫الئحــة اعتراضيــة وجــرى إفهامــه باســتالم نســخة مــن احلكــم يف هــذا‬\n‫اليــوم وأن عليــه أن يســلم الئحتــه خــال مــدة أقصاهــا ثالثــون يومـ ًا تبــدأ‬\n‫مــن هــذا اليــوم الثالثــاء املوافــق ‪1433/01/27‬ه ـ وأنــه إن وافــق آخــر يوم‬\n‫مــن املــدة إجــازة رســمية فيكــون آخــر يــوم لــه هــو أول يــوم دوام رســمي‬\n‫كمــا جــرى إفهامــه بأنــه إن لــم يتقــدم بالئحتــه االعتراضيــة خــال املــدة‬\n‫النظاميــة فإنــه ســيتم رفــع احلكــم واملعاملــة حملكمــة االســتئناف بــا‬\n‫الئحــة كمــا قــرر املدعــى عليــه عــدم قناعتــه باحلكــم مكتفيـ ًا بــأوراق‬\n‫املعاملــة ومــا ضبــط لدينــا وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n\n\n                                                                                         ‫‪276‬‬\n\f                    ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/01/27‬هــ‪.‬‬\n      ‫احلمــدهلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪1434/5/7‬ه ـ حضــر الطرفــان وقــد عــادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار الصــادر مــن الدائــرة‬\n      ‫اخلماســية األولــى برقــم ‪ 34169849‬وتاريــخ ‪1434/3/23‬ه ـ ونــص‬\n      ‫احلاجــة منــه‪( :‬وبدراســة القــرار الشــرعي وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي‪ :‬أوالً‪ :‬اجلــزاء احملكــوم بــه‬\n      ‫ـجن وجلــد كثيــر وال بــد مــن إعــادة النظــر يف‬‫علــى املدعــى عليــه مــن سـ ٍ‬\n      ‫ذلــك‪ .‬ثانيـاً‪ :‬احلكــم مبنــع املدعــى عليــه مــن الســفر خمــس عشــرة ســنة‬\n      ‫مخالــف لنظــام مكافحــة املخــدرات فعلــى أصحــاب الفضيلــة مالحظــة‬\n      ‫مــا ذكــر وإحلــاق مــا يجرونــه يف الضبــط وصورتــه والقرار الشــرعي ومن‬\n      ‫ثــم تعــاد املعاملــة إلكمــال الزمهــا‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف ‪ ....‬ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف‪ ....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ ...‬ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف‪ ....‬ختمــه وتوقيعــه رئيــس الدائــرة‪ .....‬مجــاز وموقــع على‬\n      ‫األصــل) ا‪ .‬ه ـ وعليــه جنيــب أصحــاب الفضيلــة قضــاة االســتئناف علــى‬\n      ‫املالحظــة األولــى بأنــه وملــا مت ذكــره يف تســبيب احلكــم ولعظــم فســاد‬\n      ‫املخــدرات وملــا ترتــب عليــه مــن فواحــش وألن املــروج ركـ ُـن أســاس يف‬\n      ‫انتشــار هــذه اآلفــة إذ جعــل الترويــج مهنــة ميتهنهــا ولكــون البنــد (ثانيـاً)‬\n      ‫مــن املــادة الســابعة والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة جعــل احلــد األدنــى مــن العقوبــة خمس عشــرة ســنة وجعلــت تقدير‬\n      ‫الزيــادة للقضــاة ناظــري الدعــوى ولكــون مكابــرة املدعــى عليــه وعــدم‬\n      ‫إقــراره وندمــه دليــل علــى إصــداره علــى ذنبــه رغــم حضــور مــن يشــهد‬\n\n\n‫‪277‬‬\n\f‫بخــاف مــا يذكــر واجتمــاع عــدد مــن القرائــن اجتاهــه فقــد رأينــا‬\n‫الزيــادة علــى احلــد األدنــى املذكــور يف املــادة وأمــا مــا ذكــره أصحــاب‬\n‫الفضيلــة يف املالحظــة الثانيــة فلوجاهــة مــا ذكــروه فقــد رجعنــا عمــا‬\n‫حكمنــا بــه ســابق ًا يف الفقــرة (ســابعاً) وحكمنــا بــد ًال عنهــا مبنــع‬\n‫املدعــى عليــه مــن الســفر خــارج البــاد بعــد انقضــاء محكوميتــه مــدة‬\n‫ثمــان عشــر ســنة وبعــرض احلكــم علــى الطرفــن قــررا عــدم قناعتهمــا‬\n‫باحلكــم وطلبــا رفعــه واملعاملــة حملكمــة االســتئناف بــا الئحــة‬\n‫اعتراضيــة مكتفيــن باالعتــراض الســابق ومــا يف املعاملــة مــن أوراق‬\n‫ومــا ضبــط يف القضيــة مــن أقــوال لــذا فقــد أمرنــا برفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف مبنطقــة عســير لتدقيــق احلكــم حســب‬\n‫األنظمــة واملتبــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                       ‫وصحبــه وســلم حــرر يف ‪1434/5/7‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫ففــي هــذا اليــوم األحــد املوافــق ‪1434/07/09‬ه ـ وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف مبنطقــة عســير برقــم ‪ ...........‬وتاريــخ‬\n‫‪1434/07/04‬ه ـ برفقهــا القــرار الصــادر مــن الدائــرة اخلماســية األولــى‬\n‫برقــم ‪ ..........‬وتاريــخ ‪1434/06/12‬ه ـ ونــص احلاجــة منــه ‪( :‬وباالطــاع‬\n‫علــى مــا أجــاب بــه أصحــاب الفضيلــة وأحلقــوه بالقــرار وصــورة ضبطــه‬\n‫بنــاء علــى قرارنــا رقــم ‪ .........‬وتاريــخ ‪1434/03/23‬ه ـ تقــررت املوافقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ‪ .......‬وحتى ال يخفى‬\n‫جــرى حتريــره وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم حــرر يف ‪ 1434/07/09‬ه ـ ‪.‬‬\n\n\n                                                                                       ‫‪278‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n      ‫القضايــا اخلماســية مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة ب ــنجران برقــم ‪..........‬‬\n      ‫‪1434/5/26‬ه ـ املرفــق بهــا ال ــقرار الشــرعي الصــادر مــن أصحــاب‬\n      ‫الفضيلــة القضــاة باحملكمــة ‪ .........‬برقــم ‪ .....‬وتاريــخ ‪1434/1/27‬ه ـ‬\n      ‫اخلــاص بدعــوى املدعــي العــام ضــد‪( ......../‬ســعودي اجلنســية) التهامــه يف‬\n      ‫قضيــة ( ترويــج مخــدرات) علــى الصفــة املوضحــة يف ال ــقرار املتضمــن‬\n      ‫حكــم أصحــاب الفضيلــة مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق‬\n      ‫دراســة ال ــقرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‪،‬‬\n      ‫وباالطــاع علــى مــا أجــاب بــه أصحــاب الفضيلــة وأحلقوه بال ــقرار وصورة‬\n      ‫ـاء علــى قرارنــا رقــم ‪ .......‬وتاريــخ ‪1434/3/23‬ه ـ تقــررت‬     ‫ضبطــه بنـ ً‬\n      ‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل‬\n                                     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪279‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":266,"source_page_end":279,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"11c532354adb8eb94b4cc247341f5ac244b9256289140ab9aa2eabedc388cfe2","normalized_text_hash":"0fa17fc579462b10a9549a3699bd7e38273b60b1c79f7a70ed807d6b491c87bc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p266-34248603"},{"id":"69853cfc-af3b-5f3a-8b1c-075f34d5a4f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -مسكر -اإلجتار يف احلبوب احملظورة «إمفيتامينات» -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر -حيازة احلشيش مخدر -شرب املسكر -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادره اجلوال والشريحة املستخدمة واملنع من","document_number":"443813","case_number":"3414585","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/23","year":"1434","subject":"مخدرات -مسكر -اإلجتار يف احلبوب احملظورة «إمفيتامينات» -ترويج احلبوب احملظورة -تعاطي احلشيش املخدر -حيازة احلشيش مخدر -شرب املسكر -ثبوت إدانة -تعزير بالسجن واجللد والغرامة ومصادره اجلوال والشريحة املستخدمة واملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 443813 :‬تاريخه‪1434/2/23 :‬هـ‬\n                   ‫رقم الدعوى‪3414585:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34171107‬تاريخه‪ 1434/3/24 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬مســكر ‪ -‬اإلجتــار يف احلبــوب احملظــورة «إمفيتامينــات»‬\n‫‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬حيــازة‬\n‫احلشــيش مخــدر ‪ -‬شــرب املســكر ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n‫واجللــد والغرامــة ومصــادره اجلــوال والشــريحة املســتخدمة واملنــع مــن‬\n                                                                  ‫الســفر‪.‬‬\n\n\n\n\n‫‪ -‬قــول الرســول صلــى اهلل عليــه وســلم‪ :‬كل مســكر خمــر وكل خمــر‬\n                                                                       ‫حــرام‪.‬‬\n‫‪ -‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة‬\n                                           ‫املخــدرات واملؤثــرات العقليــة‪.‬‬\n‫‪ -‬قــال شــيخ اإلســام ابــن تيميــة رحمــه اهلل يف احلشيشــة‪ ( :‬الــذي عليــه‬\n‫جمهــور األئمــة أن قليلهــا وكثيرهــا حــرام بــل الصــواب أن آكلهــا‬\n                                                                     ‫ُيحــد )‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج وتعاطــي املخــدرات‬\n‫«احلشــيش املخدر‪،‬احلبــوب احملظــورة» وشــرب املســكر‪ ،‬بقصــد‬\n\n                                                                                 ‫‪280‬‬\n\f      ‫الكســب املــادي‪ ،‬مت القبــض علــى املدعــى عليــه وبحوزتــه املبلــغ‬\n      ‫املرقــم ‪ ،‬أقــر املدعــى عليــه بالتعاطــي وأنكــر الترويــج‪ ،‬أثبــت التقريــر‬\n      ‫الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى احلشــيش املخــدر‪-‬‬\n      ‫طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بحــده حــد املســكر لقــاء‬\n      ‫شــربه املســكر‪ ،‬وبعقوبــة تعزيريــة لقــاء حيازتــه املســكر‪ ،‬وبالســجن‬\n      ‫واجللــد والغرامــة واملنــع مــن الســفر لقــاء مــا أســند إليــه ومصــادرة جــوال‬\n      ‫املســتخدم يف عمليــة الترويــج وإلغــاء الشــريحة املســتخدمة يف عمليــة‬\n      ‫الترويــج وعــدم صرفهــا لــه مجــددا‪ ،‬تشــديد العقوبــة عليــه لقــاء حيازتــه‬\n      ‫احلشــيش املخــدر والعــرق املســكر‪ .‬وقــد حكمــت احملكمــة بثبــوت‬\n      ‫إدانــة املدعــى عليــه بالترويــج واحليازة‪،‬وقــررت احملكمــة احلكــم‬\n      ‫بتعزيــره بالســجن خمــس ســنوات للقرائــن والتهــم ‪ ،‬تبــدأ مــن تاريــخ‬\n      ‫إيقافــه‪ ،‬وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات كل دفعــة‬\n      ‫خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة أيام‪،‬وإلزامــه بدفــع‬\n      ‫غرامــة ماليــة قدرهــا ألــف ري ــال لصالــح بيــت مــال املســلمني‪،‬وإقامة حــد‬\n      ‫املســكر بجلــده ثمانــن جلــدة دفعــة واحــدة‪ ،‬ومصــادرة هاتفــه النقــال‬\n      ‫وإلغــاء الشــريحة املســتخدمة يف عمليــة الترويج‪،‬ومنعــه مــن الســفر خلارج‬\n      ‫البــاد مــدة خمــس ســنوات بعــد انتهــاء فتــرة محكوميته‪،‬وقــرر املدعــى‬\n      ‫عليــه عــدم قناعتــه باحلكــم‪،‬ومت تصديــق احلكــم مــن قبــل محكمــة‬\n                                                                            ‫االســتئناف‪.‬‬\n\n\n\n\n‫‪281‬‬\n\f‫احلمد هلل وحده وبعد لدي أنا ‪..........‬القاضي باحملكمة اجلزائية بتبوك‬\n‫بنــاء علــى املعاملــة الــواردة إلــى احملكمــة مــن هيئــة التحقيــق واإلدعــاء‬\n‫العــام بتبــوك بكتابهــم رقــم ‪..........‬وتاريــخ ‪1434/1/4‬ه ـ واحملالــة إلــي‬\n‫مــن فضيلــة الرئيــس املكلــف برقــم ‪..........‬وتاريــخ ‪1434/1/10‬ه ـ عليــه‬\n‫حضــر املدعــي العــام ‪..........‬املكلــف لــدى احملكمــة مبوجــب كتــاب‬\n‫التعميــد رقــم ‪..........‬يف ‪1433/9/5‬ه ـ وادعــى علــى واحلاضــر معــه‬\n‫ا‬‫‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )..........‬قائ ـ ً‬\n‫يف حتريــر دعــواه ورد محضــر التنســيق والشــراء والقبــض املعــد مــن‬\n‫قبــل مكافحــة املخــدرات بتبــوك املتضمــن أنــه بتاريــخ ‪1433/10/17‬ه ـ‬\n‫توفــرت لديهــم معلومــات مــن أحــد مصادرهــم الســرية تفيــد بوجــود‬\n‫شــخص يقيــم بحــي ‪.........‬ويدعــى ‪..........‬ويقــوم ببيــع احلبــوب احملظــورة‬\n‫وبالفعــل متكــن املصــدر مــن االتصــال باملذكــور علــى مــرأى ومســمع‬\n‫مــن أفــراد الفرقــة علــى اجلــوال رقــم (‪ )..........‬واالتفــاق معــه علــى شــراء‬\n‫حبــوب محظــورة مببلــغ وقــدره (‪ )100‬ريــال ومت االتفــاق علــى موقــع‬\n‫االســتالم بحــي ‪.........‬خلــف مدرســة‪.........‬ومت ترقيــم مبلــغ للجنــدي رقــم‬\n‫(‪ )...‬وقــدره مائــة ريــال (‪ ).........‬لتمثيــل دور املشــتري مبرافقــة الفرقة ومت‬\n‫بعدهــا مقابلــة املذكــور يف املوقــع املتفــق عليــه وتســلم املبلــغ احلكومــي‬\n‫وســلم كيــس نايلــون للممثــل دور املشــتري وعثــر بداخلــه علــى مــا عــدده‬\n‫(‪ )4‬أربــع حبــات يشــتبه أن تكــون مــن احلبــوب احملظــورة فتــم القبــض‬\n‫عليــه وبتفتيشــه شــخصي ًا لــم يتــم العثــور علــى ممنوعــات وعثــر بحوزتــه‬\n‫علــى املبلــغ املرقــم يف جيــب ثوبــه العلــوي وكذلــك علــى اجلــوال املنســق‬\n\n                                                                                        ‫‪282‬‬\n\f      ‫عليــه واملســتخدم يف عمليــة الترويــج واســتناد ًا للمــادة (‪ )43‬مــن نظــام‬\n      ‫اإلجــراءات اجلزائيــة وبعــد أخــذ اإلذن بتفتيــش منــزل املدعــى عليــه مت‬\n      ‫االنتقــال ملنزلــه برفقــة الســجانة وأفــراد الفرقــة وبتفتيشــه عثــر بغرفــة‬\n      ‫االســتقبال داخــل األبجــورة علــى لفافــة تبــغ واحــدة ملفوفــة ويشــتبه‬\n      ‫أن تكــون مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪920‬ملــج) تســعمائة‬\n      ‫وعشــرون ملــي جرامـ ًا كمــا عثــر بداخــل مخــزن ســري بجانــب البوابــة‬\n      ‫الرئيســية للشــقة علــى قارورتــي مــاء حجمهمــا (‪500‬مــل) مملــوءة‬\n      ‫بســائل شــفاف ذي رائحــة كريهــة وقــارورة شــبه مملــوءة بســائل شــفاف‬\n      ‫ذي رائحــة كريهــة حجمهــا (‪1.5‬لتــر ) يشــتبه أن تكــون مــن العــرق‬\n      ‫املســكر ومت إغــاق بــاب املنــزل وإحالــة املدعــى عليــه إلدارة مكافحــة‬\n      ‫املخــدرات الســتكمال اإلجــراءات وجــرى إيقافــه اســتناد ًا للفقــرة (‪)4‬‬\n      ‫مــن القــرار الــوزاري رقــم (‪ )1900‬باســتجواب املدعــى عليــه‪......... /‬‬\n      ‫أقــر بأنــه اتفــق مــع شــخص مصــري اجلنســية بعــد اتصالــه علــى هاتفــه‬\n      ‫رقــم (‪ )..........‬وتعــرف عليــه عــن طريــق شــربهما للمســكر ســوي ٌا قبــل‬\n      ‫مــا يقــارب الشــهرين لتأمــن مــا عــدده (‪ )4‬أربــع حبــات مــن احلبــوب‬\n      ‫احملظــورة ألحــد أصدقائــه ومت تســليم الكميــة للشــخص خلــف مــدارس‬\n      ‫(‪ )...‬بحي‪.........‬وقــام املشــتري بوضــع املبلــغ املتفــق عليــه بجيبــه العلــوي‬\n      ‫وبتفتيــش منزلــه عثــر علــى قارورتــن مــن املــاء األولــى ســعة (‪500‬مــل)‬\n      ‫و األخــرى ســعة (‪1.5‬لتــر ) بهــا عــرق مســكر كمــا عثــر علــى لفافــة‬\n      ‫تبــغ ملفوفــة ومخلوطــة باحلشــيش املخــدر بلــغ وزنها(‪920‬ملــج) تســعمائة‬\n      ‫وعشــرون ملــي جــرام وجميــع مــا مت ضبطــه بقصــد االســتخدام وأقــر‬\n      ‫بتعاطيــه الســابق للحشــيش املخــدر واحلبــوب احملظــورة وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم ( ‪ ).........‬الصــادر مــن مركــز‬\n\n\n‫‪283‬‬\n\f                          ‫مراقبــة الســموم والكيميــاء الطبيــة بصحــة تبــوك‬\n‫إيجابيــة العينــة لإلمفيتامــن املنبــه للجهــاز العصبــي وهــو مــن املؤثــرات‬\n‫العقليــة اخلاضعــة للرقابــة املنــوه عنهــا باجلــدول الثانــي فئــة ( ب) كمــا‬\n‫أثبــت التقريــر الكيميائــي إيجابيــة مســتخلص العينــة للحشــيش املخــدر‬\n‫للفافــة تبــغ ال يعلوهــا آثــار حــرق وهــو مــن املــواد املخــدرة اخلاضعــة للرقابة‬\n‫املنــوه عنهــا باجلــدول األول فئــة (أ) يف تعميم صاحب الســمو امللكي ولي‬\n‫العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪)89400/19‬‬\n‫يف ‪1426/10/25‬ه ـ كمــا أثبــت التقريــر إيجابيــة العينــات املرســلة عدد‬\n‫قارورتــن ســعة (‪ 500‬ملــل) قــدر حجــم الســائل بهــا (‪ 490‬ملــل) وقــارورة‬\n‫ســعة ‪ 1500‬ملــل للكحــول اإليثيلــي املســكر وقــد أســفر التحقيــق عــن‬\n‫توجيــه االتهــام للمدعــى عليــه‪......... /‬بترويــج مــا عــدده (‪ )4‬أربــع حبــات‬\n‫مــن حبــوب االمفيتامــن املنبــه للجهــاز العصبــي احملظــورة عــن طريــق‬\n‫البيــع وحيــازة لفافــة تبــغ مخلوطــة باحلشــيش املخدر بلغ وزنهــا (‪920‬ملج)‬\n‫تســعمائة وعشــرين مليجرامــا وحيــازة قارورتــي مــاء حتــوي مــادة العــرق‬\n‫املســكر بلــغ حجمهمــا (‪ )490‬أربعمائــة وتســعني ملــم وقــارورة عــرق‬\n‫مســكر ســعة (‪ 1500‬ملــم) بقصــد التعاطــي أو االســتخدام والشــرب‬\n‫وشــربه العــرق املســكر يف الســابق وتعاطيــه للحشــيش املخــدر واحلبــوب‬\n‫احملظــورة يف الســابق اســتناد ًا للفقــرة (‪ )2‬مــن املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وذلــك لألدلــة والقرائــن التاليــة ‪.1‬مــا جــاء‬\n‫بإقــراره املنــوه عنــه واملــدون علــى اللفــة رقــم ( ‪.2 ) 14‬مــا جــاء يف محضــر‬\n‫التنســيق والشــراء والقبــض والتفتيــش املنــوه عنــه املــدون صفحــة‬\n‫رقــم (‪ )3-2‬املرفــق لفــة رقــم (‪.3 )1‬العثــور علــى املبلــغ املرقــم بحوزتــه‬\n\n\n                                                                                          ‫‪284‬‬\n\f      ‫واملــدون مبحضــر الضبــط لفــة رقــم (‪.4 )1‬مــا جــاء بالتقريــر الكيمائــي‬\n      ‫الشــرعي املرفــق رقــم (‪ /2720‬م س ت) لفــة رقــم (‪ )34‬وحيــث إن مــا‬\n      ‫أقــدم عليــه املذكــور فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر لعــام ‪1426‬ه ـ يف‬\n      ‫عقوباتهــا ألصليــة والتكميليــة لــذا أطلــب ‪.1‬إثبــات إدانتــه مبــا أســند‬\n      ‫إليــه ‪.2‬احلكــم عليــه بحــد املســكر لقــاء شــربه للمســكر ‪.3‬احلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة لقــاء حيازتــه املســكر ‪.4‬احلكــم عليــه بالســجن‬\n      ‫واجللــد والغرامــة لقــاء مــا أســند إليــه اســتناد ًا للفقــرة (‪ )1‬مــن املــادة‬\n      ‫(‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‬\n      ‫أعــاه أعمــا ًال للفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن ذات النظــام املشــار إليــه‬\n      ‫‪.5‬احلكــم عليــه مبنعــه مــن الســفر خــارج اململكــة اســتناد ًا للفقــرة (‪)1‬‬\n      ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫املشــار إليــه أعــاه ‪.6‬احلكــم مبصــادرة جهــاز اجلــوال املســتخدم يف‬\n      ‫عمليــة الترويــج مــن نــوع ( ‪ ) ....‬يحمــل الكــود رقــم (‪ ).........‬اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه ‪.7‬إلغــاء الشــريحة املســتخدمة يف عمليــة الترويــج‬\n      ‫وعــدم صرفهــا لــه مجــدد ًا اســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n      ‫ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم (‪9798‬‬\n      ‫) وتاريــخ ‪1428/2/10-9‬ه ـ ‪.8‬تشــديد العقوبــة عليــه اســتناد ًا لتعميــم‬\n      ‫صاحــب الســمو امللكــي ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر‬\n      ‫الداخليــة رقــم (‪2/8346/4/5/1‬س) وتاريــخ (‪1427/2/8‬هــ) هــذه‬\n      ‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه وســؤاله عنهــا‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي العــام يف دعــواه مــن حيازتــي للحشــيش‬\n\n\n‫‪285‬‬\n\f                                                        ‫املخــدر والعــرق املســكر‬\n‫وقــررت مــا يلــي أو ًال تعزيــر املدعــى عليــه لقــاء مــا ثبــت بحقــه مــن الترويــج‬\n‫واحليــازة بســجنه ملــدة خمــس ســنوات يحتســب مــن ذلــك مــدة إيقافــه‬\n‫بســبب هــذه القضيــة وجلــده خمســمائة جلــدة مفرقــة علــى عشــر دفعــات‬\n‫كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وتغرميــه‬\n‫مبلــغ ألــف ريــال لصالــح بيــت مــال املســلمني يصــرف يف املصالــح العامــة‬\n‫ثانيـ ًا إقامــة حــد املســكر علــى املدعــى عليــه بجلــده ثمانــن جلــدة ثالثـ ًا‬\n‫مصــادرة هاتــف املدعــى عليــه النقــال املســتخدم يف عمليــة الترويــج نــوع‬\n‫‪ ....‬يحمــل الرقــم التسلســلي (‪ ).........‬لصالــح بيــت مــال املســلمني يصــرف‬\n‫يف املصالــح العامــة رابع ـ ًا إلغــاء شــريحة املدعــى عليــه املســتخدمة يف‬\n‫عمليــة الترويــج وعــدم صرفهــا لــه مــرة أخــرى خامس ـ ًا منــع املدعــى‬\n‫عليــه مــن الســفر خــارج اململكــة ملــدة خمــس ســنوات بعــد انتهــاء فتــرة‬\n‫محكوميتــه وبذلــك حكمــت وبعــرض احلكــم علــى الطرفــن قــررا‬\n‫اعتراضهمــا مكتفــن مبــا جــاء يف أقوالهمــا وأوراق املعاملــة عــن تقــدمي‬\n‫الئحــة اعتراضيــة وللبيــان حــرر يف ‪1434/2/20‬ه ـ وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولى‬\n‫لتدقيــق القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك املكلــف‬\n‫برقــم ‪ 3468532‬وتاريــخ ‪1434/3/2‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة الشــيخ‪.......... /‬رقــم ‪..........‬وتاريــخ ‪1434/2/23‬ه ـ اخلــاص‬\n‫بدعــوى املدعــي العــام ضــد‪ .......... /‬يف قضيــة مخــدرات علــى النحــو‬\n‫املوضــح يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n\n\n                                                                                            ‫‪286‬‬\n\f      ‫فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى احلكــم‪ .‬مــع تنبيــه فضيلتــه إلــى عــرض إقــرار املدعــى عليــه حتقيقـ ًا‬\n      ‫عليــه وســؤاله عنــه كمــا أنــه يحســن بفضيلتــه النــص علــى علنيــة جلــد‬\n      ‫احلــد وأن يكــون بينــه وبــن دفعــات جلــد التعزيــر مــدة زمنيــة مناســبة‬\n              ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪287‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":280,"source_page_end":287,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15b56580c426716b7a5a4b2ceac8350b7554eebb8015a9ac7c08bb8deb1427de","normalized_text_hash":"6df26831a4580ec7c1a760a3a1176b4864318a5c1c0f3b54286a91838735bfc8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p280-443813"},{"id":"7b048e65-43fb-508c-81b9-871e469c22d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -حيازة قطعه من احلشيش بقصد الترويج والتعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد و الغرامة و املنع من السفر و مصادرة السيارة و الهاتف اجلوال .","document_number":"3465016","case_number":"3414607","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/17","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -حيازة قطعه من احلشيش بقصد الترويج والتعاطي -تعاطي احلشيش املخدر -إقامة حد املسكر على متعاطي احلشيش -التعزير بالسجن واجللد و الغرامة و املنع من السفر و مصادرة السيارة و الهاتف اجلوال .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3465016 :‬تاريخه ‪1434/03/17 :‬هـ‬\n                     ‫رقم الدعوى ‪3414607:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34231726‬تاريخه‪1434/06/05 :‬هـ‬\n\n\n ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬حيــازة قطعــه مــن احلشــيش‬\n ‫بقصــد الترويــج والتعاطــي ‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إقامــة حــد‬\n ‫املســكر علــى متعاطــي احلشــيش ‪ -‬التعزيــر بالســجن واجللــد و الغرامة‬\n              ‫و املنــع مــن الســفر و مصــادرة الســيارة و الهاتــف اجلــوال ‪.‬‬\n\n\n\n\n ‫‪ -1‬قــال شــيخ اإلســام رحمــه اهلل يف الفتــاوى رقــم (‪: )135/29‬‬\n ‫(والصحيــح أن احلشيشــة مســكرة كالشــراب و أن آكلهــا يحــد منهــا‬\n ‫فهــي خمــر ) ‪ .‬وقــال ايضـ ًا ‪ ( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر و‬\n ‫إن كان يف اخلمــر مفســده ليســت فيهــا و هــي احلــدة فهــي بالتحــرمي‬\n ‫أولــى مــن اخلمــر ألن ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر‬\n ‫اخلمــر و شــارب اخلمــر علــى النــاس أشــد إال أنــه يف هــذه اإلزمــان لكثــرة‬\n ‫آكل احلشيشــة صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن‬\n                                                ‫اخلمــر )‪ .‬الفتــاوى (‪.)142/29‬‬\n ‫‪ -2‬الفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                         ‫العقليــة‪.‬‬\n ‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n ‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n                                                                                       ‫‪288‬‬\n\f      ‫‪ -5‬الفقــرة (‪ )2‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n      ‫‪ -6‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n      ‫‪ -7‬الفقــرة (‪ )1‬مــن املــادة (‪ )60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n      ‫‪ -8‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                          ‫العقليــة‪.‬‬\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بترويــج قطعــه مــن احلشــيش‬\n      ‫املخــدر‪ ،‬وحيــازة قطعــة مــن احلشــيش بقصــد الترويــج و التعاطــي‪،‬‬\n      ‫وتعاطــي احلشــيش املخــدر ‪ ،‬حيــث إنــه ارتكــب جرميــة ترويــج املــواد‬\n      ‫املخــدرة يف الســابق ‪ ،‬وقــد ورد بــاغ ملكافحــة املخــدرات مــن أحــد‬\n      ‫املصــادر الســرية عــن قيــام املدعــى عليــه بترويــج احلشــيش املخــدر و‬\n      ‫يســتخدم اجلــوال يف ذلــك ‪ ،‬ومت متكــن املصــدر مــن االتصــال باملدعــى‬\n      ‫عليــه و طلــب منــه شــراء قطعــه مــن احلشــيش ‪ ،‬فوافــق املدعــى عليــه‬\n      ‫علــى ذلــك ‪ ،‬حيــث إنــه مت تفتيــش املصــدر وتزويــده باملبلــغ احلكومــي‬\n      ‫املرقــم و حتــرك حتــت أنظــار الفرقــة القابضــة و متــت عمليــه االســتالم‬\n      ‫و التســليم ‪ ،‬و مت القبــض علــى املدعــى عليــه و عثــر بجيبــه علــى املبلــغ‬\n      ‫احلكومــي املرقــم و اجلــوال الــذي مت التنســيق معــه ‪ ،‬و بتفتيــش ســيارته‬\n      ‫عثــر بداخلهــا علــى قطعــة مــن احلشــيش ‪ ،‬و أقــر أمــام الفرقــة القابضــة‬\n      ‫بصحــة واقعــة الضبــط و ذكــر بــأن هــذه املــرة الثانيــة التــي يقــوم فيهــا‬\n\n‫‪289‬‬\n\f‫بالترويــج علــى ســيارته وطلــب املدعــي العــام إثبــات مــا أســند للمدعــي‬\n‫عليــه و احلكــم عليــه بالعقوبــة الــواردة بالفقــرة األولى من املادة (‪ )38‬من‬\n‫نظــام مكافحــة املخــدرات و تطبيــق العقوبــة األشــد و منعــه مــن الســفر‬\n‫ومصــادرة الســيارة والهاتــف اجلــوال و إســقاط شــريحته‪ ،‬أقــر املدعــي‬\n‫عليــه بالتعاطــي كمــا أقــر باحليــازة و أنهــا لقصــد التعاطــي وأنكــر بيــع‬\n‫احلشــيش ‪ ،‬أحضــر املدعــي العــام بينتــه وهــي أعضــاء الفرقــة القابضــة‬\n‫و مت رصــد الشــهادة و بالرجــوع إلــى محضــر واقعــة القبــض و الضبــط‬\n‫والتفتيــش و التقريــر الكيميائــي الشــرعي وهــو مطابــق ملــا جــاء يف‬\n‫دعــوى املدعــي العــام ‪ ،‬وبنــاء علــى مــا ســبق حكمــت احملكمــة بثبــوت‬\n‫إدانــة املدعــى عليــه بإقامــة حــد املســكر و تعزيــره بالســجن و اجللــد‬\n‫والغرامــة و املنــع مــن الســفر و مصــادرة الســيارة و الهاتــف اجلــوال و إلغــاء‬\n                   ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬      ‫شــريحته ‪ُ ،‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n‫‪ ...‬القاضــي باحملكمــة اجلزائيــة بالدمــام بنــاء علــى املعاملــة الــواردة مــن‬\n‫هيئــة التحقيــق واإلدعــاء العــام واملقيــدة لــدى احملكمة برقــم ‪3468614‬‬\n‫وتاريــخ ‪1434/1/10‬ه ـ واحملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالدمــام برقــم ‪ 3414607‬وتاريــخ ‪1434/1/10‬ه ـ افتتحــت‬\n‫اجللســة يف يــوم الســبت ‪1434/2/23‬ه ـ الســاعة الواحــدة وفيهــا قــدم‬\n‫املدعــي العــام ‪ ...‬دعــواه ونصهــا اآلتــي‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬\n‫اإلدعــاء العــام لفــرع املنطقــة الشــرقية أدعــي علــى ‪ ... /‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...‬حيــث إنــه باالطــاع علــى محاضر البالغ‬\n\n                                                                                       ‫‪290‬‬\n\f      ‫واالتصــال والقبــض والتفتيــش تبــن أنــه يف يــوم األحــد ‪1433/11/ 28‬ه ـ‬\n      ‫ورد بــاغ إلــى مكافحــة املخــدرات مــن أحــد مصادرهــم الســرية عــن‬\n      ‫وجــود شــخص يدعــى‪ ... /‬يســكن حــي ‪ ....‬بالدمــام ويقــود ســيارة مــن‬\n      ‫نــوع ‪ ....‬موديــل ‪2012‬م يقــوم بترويــج احلشــيش املخــدر ويســتخدم اجلــوال‬\n      ‫رقــم ‪ ...‬وقــد أفــاد املصــدر بأنــه علــى اســتعداد تــام باإلطاحــة بــه باجلــرم‬\n      ‫املشــهود فتــم متكــن املصــدر مــن االتصــال باملــروج وطلــب منــه شــراء‬\n      ‫قطعــة حشــيش مببلــغ خمســمائة ريــال فوافــق املــروج وطلــب منــه أن‬\n      ‫يحضــر إلــى حــي ‪ ....‬علــى شــارع ‪ ....‬مقابــل محــات (‪ )...‬بعدها مت تفتيش‬\n      ‫املصــدر تفتيشـ ًا دقيقـ ًا إبــراء للذمــة ومت تزويــده باملبلــغ احلكومــي املرقــم‬\n      ‫وحتــرك حتــت أنظــار الفرقــة القابضــة إلــى املــكان احملــدد بعدهــا‬\n      ‫حضــر املتهــم املذكــور علــى ســيارة مــن نــوع ‪ ....‬موديــل ‪2012‬م وتقابــل‬\n      ‫مــع املصــدر وقــام بتســليم املصــدر قطعــة ســمراء اللــون يشــتبه أن تكــون‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )11,3‬إحــدى عشــر جــرام وثالثــة مــن‬\n      ‫العشــرة مــن اجلــرام واســتلم قيمتهــا مبلــغ (‪ )250‬ريــال بعدهــا حتــرك‬\n      ‫املــروج فتــم متابعتــه حتــى توقــف عنــد أحــد احملــات فتــم الســيطرة عليــه‬\n      ‫وبتفتيشــه عثــر بجيبــه األيســر علــى املبلــغ احلكومــي املرقــم وعثــر علــى‬\n      ‫اجلــوال الــذي مت التنســيق معــه مــن نــوع (‪ )....‬اللــون أبيــض يحمــل الرقــم‬\n      ‫املصنعــي (‪ )........................‬وبتفتيــش املركبــة وعثــر علــى قطعــة‬\n      ‫ســمراء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪)11,3‬‬\n      ‫إحــدى عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام وقــد أقــر أمــام الفرقــة‬\n      ‫القابضــة بصحــة واقعــة الضبــط وذكــر بــأن هــذه املــرة هــي املــرة الثانيــة‬\n      ‫التــي يقــوم فيهــا بالترويــج علــى ســيارته وقــد قــام بالتعــاون مــع الفرقــة‬\n      ‫القابضــة مــا أدى إلــى القبــض علــى الشــخص الــذي يــزوده باملخــدرات‬\n\n\n‫‪291‬‬\n\f‫وقــد وأثبــت التقريــر الكيميائــي الشــرعي رقــم (‪4344‬ك ش) لعــام‬\n‫‪1433‬ه ـ إيجابيــة العينــات املرســلة مــن الكميــة املضبوطــة والكميــة‬\n‫املباعــة ملــادة احلشــيش املخــدر باســتجواب املدعــى عليــه أنكــر قيامــه‬\n‫ببيــع قطعــة احلشــيش املخــدر البالــغ وزنهــا (‪ )11,3‬إحــدى عشــر جــرام‬\n‫وثالثــة مــن العشــرة مــن اجلــرام وذكــر بأنــه قــام بشــراء قطعــة حشــيش‬\n‫مببلــغ (‪ )500‬ريــال لــه ولشــخص أخــر وقــام بتقســيمها بينهمــا وتقابــل‬\n‫معــه وقــام بأخــذ قيمتهــا مبلــغ ‪250‬ريــال وقــام بتســليمه لنصــف الكميــة‬\n‫وأقــر بأنــه يتعاطــى احلشــيش املخــدر وقــد انتهــى التحقيــق إلــى توجيــه‬\n‫االتهــام ‪ ...‬باآلتــي ‪-1:‬بارتــكاب جرميــة بيــع مــا وزنــه (‪ )11,3‬إحــدى‬\n‫عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام مــن مــادة احلشــيش املخــدر‬\n‫لقصــد االجتــار ‪ -2‬ارتــكاب جرميــة حيــازة قطعــة حشــيش تــزن (‪)11,3‬‬\n‫إحــدى عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام مــن مــادة احلشــيش‬\n‫املخــدر بقصــد الترويــج والتعاطــي ‪ -3‬تعاطي احلشــيش املخــدر ‪ -4‬قيامه‬\n‫بارتــكاب جرميــة ترويــج املــواد املخــدرة يف الســابق‪ .‬وذلــك لألدلــة‬\n‫والقرائــن التاليــة ‪ -1:‬إقــرار املدعــى عليــه مبــا أســند إليــه واملرفــق‬\n‫بــاألوراق لفــه رقــم (‪ -2 )15-14‬مــا ورد مبحضــر البــاغ والقبــض‬\n‫والتفتيــش املرفــق بــاألوراق لفــه رقم (‪ -3 )1‬ما ورد بالتقرير الكيميائي‬\n‫الشــرعي املنــوه عنــه املرفــق لفــه (‪ )16‬وبالبحــث عــن ســوابقه لــم يعثــر لــه‬\n‫علــى أي ســابقة وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل‬\n‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومعاقــب عليــه نظامـ ًا مبوجــب‬\n‫نظــام مكافحــة املخــدرات يف عقوباتــه األصليــة والتكميليــة أطلــب مــا‬\n‫يلــي ‪ -1:‬إثبــات مــا أســند إليــه وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )3‬مــن نظــام‬\n‫مكافحــة املخــدرات واحلكــم عليــه بالعقوبــة الــواردة بالفقــرة رقــم (‪)1‬‬\n\n\n                                                                                          ‫‪292‬‬\n\f      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه وتطبيــق العقوبــة األشــد وفقــا للمــادة (‪ )62‬مــن نظــام مكافحــة‬\n      ‫املخــدرات ‪ -2‬منعــه مــن الســفر وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة (‪)56‬‬\n      ‫مــن نظــام مكافحــة املخــدرات ‪ -3‬احلكــم مبصــادرة الســيارة مــن نــوع‬\n      ‫جمــس ‪ ....‬صنــع عــام ‪2012‬م حتمــل لوحــة رقــم (‪ )...‬اســتناد ًا للمــادة‬\n      ‫(‪ )53‬مــن ذات النظــام الســتخدامهما يف اجلرميــة مــع املطالبــة بإســقاط‬\n      ‫شــريحة الهاتــف اجلــوال وعــدم صرفهــا لنفــس املتهــم وفقــا لتعميــم ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪)9798‬وتاريــخ ‪1428/10/23‬ه هكــذا ادعــى‬\n      ‫ا مــا ذكــره املدعــي‬    ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫العــام مــن قيامــي بحيــازة احلشــيش وتعاطيــه فذلــك صحيــح وقصــدي مــن‬\n      ‫احليــازة التعاطــي فقــط وأمــا بيــع احلشــيش فذلــك غير صحيــح والصحيح‬\n      ‫أننــي كنــت قــد اتفقــت مــع املصــدر علــى أن أشــتري لــه احلشــيش حيــث‬\n      ‫إننــا كنــا نتعاطــى ســوي ًا وبعــد ذلــك اتصلــت بــه عــن طريــق اجلــوال‬\n      ‫وواعدتــه وبعــد حضــوره ســلمته نصيبــه مــن احلشــيش الــذي اشــتريته‬\n      ‫وقيمتــه مائتــان وخمســون ريــا ًال اســتلمتها منــه ثــم بعــد ذلــك قبــض علــي‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي العــام قــال مــا ذكــره املدعــى‬\n      ‫عليــه غيــر صحيــح والصحيــح مــا ذكــرت يف دعــواي هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــي العــام البينــة علــى دعــواه فقــال أطلــب مهلــة‬\n      ‫إلحضارها ولذا رفعت اجللســة إلى يوم الثالثاء ‪1434/3/17‬هـ الســاعة‬\n      ‫احلاديــة عشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/2/23‬ه ـ ويف يــوم‬\n      ‫الثالثــاء ‪1434/3/17‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان ثــم‬\n      ‫جــرى ســؤال املدعــي العــام عمــا طلــب االســتمهال ألجلــه فقــال إننــي‬\n\n\n‫‪293‬‬\n\f‫أحضــرت معــي بعــض أعضــاء الفرقــة القابضــة وهمــا‪ ... /‬و‪...‬وبســؤال‬\n‫الشــاهدين عمــا لديهمــا مــن شــهادة قــال كل واحــد منهمــا مبفــرده‬\n‫(أشــهد بــاهلل يف يــوم األحــد ‪1433/11/28‬ه ـ ورد بــاغ إلــى مكافحــة‬\n‫املخــدرات مــن أحــد مصادرنــا الســرية عــن قيــام املدعــى عليــه ‪ ...‬الــذي‬\n‫يســكن بحــي ‪ ....‬بالدمــام بترويــج احلشــيش املخــدر ويســتخدم اجلــوال‬\n‫رقــم ‪ ...‬وقــد أفــاد املصــدر بأنــه علــى اســتعداد تــام باإلطاحــة بــه باجلــرم‬\n‫املشــهود فتــم متكــن املصــدر مــن االتصــال باملــروج وطلــب منــه شــراء‬\n‫قطعــة حشــيش مببلــغ خمســمائة ريــال فوافــق املــروج وطلــب منــه أن‬\n‫يحضــر إلــى حــي ‪ ....‬علــى ‪ ....‬مقابــل محــات (‪ )...‬بعدهــا مت تفتيــش‬\n‫املصــدر تفتيشـ ًا دقيقـ ًا إبــراء للذمــة ومت تزويــده باملبلــغ احلكومــي املرقــم‬\n‫وحتــرك حتــت أنظــاري وأنظــار الفرقــة القابضــة إلــى املــكان احملــدد‬\n‫بعدهــا حضــر املدعــى عليــه علــى ســيارة مــن نــوع ‪ .....‬صنــع عــام ‪2012‬م‬\n‫وتقابــل مــع املصــدر وشــاهدته يقــوم بتســليم املصــدر قطعــة ســمراء اللــون‬\n‫يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )11,3‬إحــدى عشــر‬\n‫جــرام وثالثــة مــن العشــرة مــن اجلــرام واســتلم قيمتهــا مبلــغ (‪ )250‬ريــال‬\n‫بعدهــا حتــرك املــروج فتــم متابعتــه حتــى توقــف عنــد أحــد احملــات فتــم‬\n‫الســيطرة عليــه وبتفتيشــه عثــر بجيبــه األيســر علــى املبلــغ احلكومــي‬\n‫املرقــم كمــا عثــر علــى اجلــوال الــذي مت التنســيق معه وبتفتيــش املركبة‬\n‫عثرنــا علــى قطعــة ســمراء اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر‬\n‫بلــغ وزنهــا (‪ )11,3‬إحــدى عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n‫وقــد أقــر أمامــي وأمــام الفرقــة القابضــة بصحــة واقعــة الضبــط وذكــر‬\n‫بــأن هــذه املــرة هــي املــرة الثانيــة التــي يقــوم فيهــا بالترويــج علــى ســيارته‬\n‫وقــد قــام بالتعــاون مــع الفرقــة القابضــة مــا أدى إلــى القبــض علــى‬\n\n\n                                                                                            ‫‪294‬‬\n\f      ‫الشــخص الــذي يــزوده باملخــدرات) هكــذا شــهدا وبعــرض الشــهود‬\n      ‫وشــهادتهم علــى املدعــى عليــه قــال أمــا الشــهود فــا أعرفهــم وأمــا‬\n      ‫شــهادتهم فغيــر صحيحــة والصحيــح مــا ذكرتــه يف إجابتــي علــى‬\n      ‫الدعــوى هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام املزكــن للشــهود‬\n      ‫فقــال إننــي أحضرتهمــا معــي وهمــا‪ ... /‬و‪....‬وبســؤالهما عمــا لديهمــا قــال‬\n      ‫كل واحــد منهمــا مبفــرده ( أشــهد بــاهلل أن الشــاهدين ‪ ..‬و‪ ..‬عدلــن‬\n      ‫ثقــات ومقبولــي الشــهادة يف الديــن واملــروءة) هكــذا شــهدا ثــم جــرى‬\n      ‫االطــاع علــى املعاملــة فوجــدت علــى لفــة رقــم (‪ )1‬دفتــر التحقيــق ص‬\n      ‫(‪ )13-12‬محضــر واقعــة القبــض والضبــط والتفتيــش وهــو طبــق مــا‬\n      ‫ذكــر املدعــي العــام يف دعــواه كمــا وجــدت علــى لفــة رقــم (‪ )17‬كــرت‬\n      ‫بصمــات املدعــى عليــه املتضمــن عــدم وجــود ســوابق لــه كمــا وجــدت‬\n      ‫علــى لفــة رقــم (‪ )19‬تقريــر كيمــاوي شــرعي رقــم (‪4344‬ك ش)‬\n      ‫املتضمــن ايجابيــة العينــات املرســلة ملــادة احلشــيش املخــدر كمــا وجــدت‬\n      ‫علــى لفــة رقــم (‪ )25‬تقريــر مفصــل عــن ســيارة مــن نــوع ‪ ....‬صنــع عــام‬\n      ‫‪2012‬م رقــم اللوحــة (‪ )...‬مملوكــة للمدعــى عليــه ‪ -4 ...‬مصادرة الهاتف‬\n      ‫اجلــوال العائــد للمدعــى عليــه والــذي يحمــل الرقــم املصنعــي (‪)............‬‬\n      ‫ورقــم االتصــال (‪ )...‬الســتخدامه يف الترويــج وفقـ ٌا للفقــرة رقــم (‪ )1‬مــن‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي‬‫املــادة (‪ )53‬مــن ذات النظــام ‪ ،‬فبنـ ً‬\n      ‫العــام وإجابــة املدعــى عليــه وإقــراره بتعاطــي احلشــيش املخــدر وحيازتــه‬\n      ‫ـاء علــى شــهادة الشــهود‬ ‫بقصــد التعاطــي وقيامــه باالتصــال بجوالــه وبنـ ً‬\n      ‫املعدلــن التعديــل الشــرعي املتضمنــة قيــام املدعى عليه بترويج احلشــيش‬\n      ‫املخــدر والتنســيق عــن طريــق جوالــه واحلضــور ملوقــع التســليم بســيارته‬\n      ‫ـاء علــى الفقــرة (‪ )2‬مــن‬ ‫ونظــر ًا لعــدم وجــود ســوابق للمدعــى عليــه وبنـ ً‬\n\n‫‪295‬‬\n\f‫املــادة (‪ )3‬والفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪)2( )41‬‬\n‫مــن املــادة (‪ )53‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬والفقــرة (‪ )1‬مــن املــادة‬\n‫(‪ )60‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n‫واملؤثرات العقلية ومبا أن احلشــيش مســكر حيث ذكر شــيخ اإلســام‬\n‫ابــن تيميــة يف مجمــوع الفتــاوى مــا نصــه‪( :‬والصحيــح أن احلشيشــة‬\n‫مســكرة كالشــراب وأن آكلهــا يحــد منهــا فهــي خمــر ) (ج‪/29‬‬\n‫ص‪ )135‬كمــا قــال‪( :‬وفيهــا مــن املفاســد مــا ليــس يف اخلمــر وإن كان‬\n‫يف اخلمــر مفســدة ليســت فيهــا وهــي احلــدة فهــي بالتحــرمي أولــى مــن اخلمــر‬\n‫ألن ضــرر آكل احلشيشــة علــى نفســه أشــد مــن ضــرر اخلمــر وضــرر‬\n‫شــارب اخلمــر علــى النــاس أشــد إال أنــه يف هــذه األزمــان لكثــرة أكل‬\n‫احلشيشــة صــار الضــرر الــذي منهــا علــى النــاس أعظــم مــن اخلمــر)‬\n‫مجمــوع الفتــاوى (ج‪/29‬ص‪ )142‬لــذا كلــه فقــد ثبــت لــدي إدانــة املدعى‬\n‫عليــه ‪ ...‬ببيــع مــا وزنــه (‪ )11,3‬إحــدى عشــر جــرام وثالثــة مــن العشــرة‬\n‫مــن اجلــرام مــن مــادة احلشــيش املخــدر بقصــد االجتــار وحيــازة قطعــة‬\n‫حشــيش تــزن (‪ )11,3‬إحــدى عشــر جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n‫مــن مــادة احلشــيش املخــدر بقصــد الترويــج والتعاطــي وإدانتــه بقيامــه‬\n‫بارتــكاب جرميــة ترويــج املــواد املخــدرة يف الســابق كمــا ثبــت لــدي‬\n‫إدانتــه بتعاطــي احلشــيش املخــدر وقــررت معاقبتــه علــى ذلــك مبــا يلــي‪:‬‬\n‫أوالً‪ :‬ســجن املدعــى عليــه ملــدة ســنتني حتتســب منهــا مــدة إيقافــه وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى دفعــات متســاوية بــن كل دفعــة وأخــرى‬\n‫مــدة ال تقــل عــن أســبوعني وتغرميــه ألــف ريــال تدفــع للجهــة املختصــة‬\n‫وذلــك لقــاء بيعــه احلشــيش املخــدر وحيازتــه‪ .‬ثانيـاً‪ :‬منعــه مــن الســفر ملــدة‬\n‫ســنتني تبــدأ بعــد انتهــاء محكوميتــه املقــررة يف البنــد أوالً‪ .‬ثالث ـاً‪:‬‬\n\n\n                                                                                        ‫‪296‬‬\n\f      ‫مصــادرة الســيارة املوصوفــة يف الدعــوى وإيداعهــا أو ثمنهــا لــدى اجلهــة‬\n      ‫املختصــة‪ .‬رابعـاً‪ :‬مصــادرة الهاتــف اجلــوال املوصــوف يف الدعوى وإيداعه‬\n      ‫أو ثمنهــا لــدى اجلهــة املختصــة وعــدم صــرف الشــريحة لــه‪ .‬خامسـاً‪ :‬جلده‬\n      ‫ثمانــن جلــدة دفعــة واحــدة حــد املســكر ويكــون التنفيــذ يف مــكان‬\n      ‫عــام يحضــره جمــع مــن النــاس‪ .‬وبــكل مــا تقــدم حكمــت وبعــرض‬\n      ‫احلكــم علــى الطرفــن قــرر املدعــي العــام واملدعــى عليــه عــدم القناعــة‬\n      ‫باحلكــم وطلبــا االســتئناف بالئحــة يقدمهــا كل واحــد منهمــا‬\n      ‫فأفهمتهمــا بأنــه ســوف يجــري بعــد قليــل تســليم كل واحــد منهمــا‬\n      ‫نســخة مــن احلكــم ليقــدم اعتراضــه خــال ثالثــن يومـ ًا مــن اآلن يكون‬\n      ‫حقهمــا يف االســتئناف بعــد مضــي هــذه املــدة ســاقط ًا ففهمــا ذلــك وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                 ‫يف ‪1434/03/17‬هـ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1434/06/20‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة الســابعة وفيهــا وردتنــا املعاملــة مــن محكمة االســتئناف‬\n      ‫باملنطقــة الشــرقية برقــم ‪ 341477966‬يف ‪1434/06/19‬ه ـ وبرفقهــا‬\n      ‫القــرار الصــادر مــن الدائــرة اجلزائيــة األولــى برقــم ‪ 34231726‬يف‬\n      ‫‪1434/06/05‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                    ‫‪1434/06/20‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1435/01/23‬ه ـ الســاعة‬\n      ‫الواحــدة والنصــف افتتحــت اجللســة وفيهــا وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف باملنطقــة الشــرقية برقــم‪ 35206014‬يف ‪1435/01/18‬ه ـ‬\n      ‫وبرفقهــا القــرار الصــادر مــن الدائــرة األولــى برقــم ‪ 35109851‬يف‬\n\n\n‫‪297‬‬\n\f‫‪1435/01/09‬ه ـ املتضمــن (وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة لوحــظ ان فضيلتــه لــم يــدون يف الضبــط أســباب تقــدمي‬\n‫االلتمــاس واعــادة النظــر يف ضبطــه ليكــون معلومــا لديــه مســتقبال‬\n‫يف حــال تقــدمي التمــاس اخــر لكــون صحيفــة االلتمــاس حتفــظ مــع‬\n‫األوراق يف محكمــة االســتئناف ملالحظــه مــا ذكــر وإكمــال الــازم‬\n‫ومــن ثــم إعــادة املعاملــة واهلل املوفــق) عليــه أجيــب أصحــاب الفضيلــة بــأن‬\n‫مضمــون أســباب االلتمــاس كالتالــي‪ -1:‬أنــه يوجــد مســتند باملعاملــة‬\n‫يثبــت رجــوع املصــدر عــن أقوالــه‪ -2 .‬أن احلكــم بنــي علــى شــهادة تبــن‬\n‫أنهــا كاذبــة‪ -3 .‬أن منطــوق احلكــم يناقــض بعضــه بعضـ ًا وأمــرت برفــع‬\n‫املعاملــة إلــى محكمــة االســتئناف وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1435/01/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪34377841‬‬\n‫وتاريــخ ‪1434/4/29‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/1084088‬‬\n‫وتاريــخ ‪1434/5/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪ ...‬املســجل برقــم ‪ 3465016‬وتاريــخ ‪1434/3/17‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪ .../‬يف قضيــة مخــدرات وقــد تضمن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والالئحتــن االعتراضيتــن وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫آلــه وصحبــه وســلم حرريف‪1434/6/3‬ه ـ‬\n\n\n\n                                                                                         ‫‪298‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":288,"source_page_end":298,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"900fff9484c0254e58d2d80d015b8c13b1bcb4ec3c58102f8a162fd955ea1a82","normalized_text_hash":"6110606de0c78ca71775892b214c133b21ed213ca03aaf3bbee086a7f4ea95e8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p288-3465016"},{"id":"ca147e6e-24ef-5621-b84d-0f86c834d8d5","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر واحلبوب احملظورة «إمفيتامن» -تعاطي احلشيش املخدر واحلبوب احملظورة -وجود سوابق قضائية -تعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال والشريحة املستخدمة واملبلغ املضبوط.","document_number":"3459136","case_number":"3419990","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/10","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر واحلبوب احملظورة «إمفيتامن» -تعاطي احلشيش املخدر واحلبوب احملظورة -وجود سوابق قضائية -تعزير بالسجن واجللد واملنع من السفر ومصادرة اجلوال والشريحة املستخدمة واملبلغ املضبوط.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3459136 :‬تاريخه‪1434/3/10 :‬هـ‬\n                          ‫رقم الدعوى‪3419990:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34234270‬تاريخه‪1434/6/7 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر واحلبــوب احملظــورة «إمفيتامــن»‬\n      ‫‪ -‬تعاطــي احلشــيش املخــدر واحلبــوب احملظــورة ‪ -‬وجــود ســوابق‬\n      ‫قضائيــة ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن الســفر ومصــادرة اجلوال‬\n                                  ‫والشــريحة املســتخدمة واملبلــغ املضبــوط‪.‬‬\n\n\n\n\n      ‫(أول) مــن املــادة (‪)37‬‬\n                           ‫الفقــرة (‪ )2‬مــن املــادة (‪ )3‬والفقــرة (‪ )5‬مــن البنــد ً‬\n      ‫واملــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪ )1‬مــن املــادة (‪)56‬‬\n      ‫واملــادة (‪ )58‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات‬\n                                                                ‫واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليهــم حضــر منهــم الثانــي والثالــث والرابــع‬\n      ‫واخلامــس ولــم يحضــر األول لقيامهــم بترويــج املخــدرات احلبــوب‬\n      ‫احملظــورة واحلشــيش املخــدر بقصــد الكســب املــادي‪ ،‬حيــث مت القبــض‬\n      ‫علــى املدعــى عليهــم وبحوزتهــم مــادة احلشــيش واملبلــغ املرقــم ‪ ،‬أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى احلشــيش‬\n      ‫ـاء علــى مــا ورد يف نصــوص نظــام‬  ‫واإلمفيتامــن‪ ،‬طلــب املدعــي العــام بنـ ً‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة احلكــم بالقتــل تعزيــرا للتهــم‬\n\n‫‪309‬‬\n\f‫والقرائــن علــى املدعــى عليــه اخلامــس ‪ ،‬وبالســجن واجللــد والغرامــة علــى‬\n‫املدعــى عليــه الرابــع ‪ ،‬وبالســجن علــى املدعــى عليهمــا األول والثالــث‪،‬‬\n‫منــع املدعــى عليهــم األول والثالــث والرابــع مــن الســفر بعــد انتهــاء تنفيــذ‬\n‫عقوبتهمــا ‪ ،‬واحلكــم علــى املدعــى عليهــم األول والثانــي والثالــث‬\n‫والرابــع بعقوبــة تعزيريــة للتهــم والقرائــن الجتماعهــم علــى مفســدة‪،‬‬\n‫ومصــادرة املبلــغ املالــي املضبــوط بحــوزة املدعــى عليــه اخلامــس وقــدره‬\n‫مائــه وثمانــون ري ــال وتشــديد العقوبــة علــى املدعــى عليــه الثالــث كونــه‬\n‫عســكريا ‪ ،‬وتعزيــر املدعــى عليــه الثانــي لقــاء إعــداد منزلــه وكــرا‬\n‫لترويــج وتعاطــى املخــدرات‪ ،‬وتشــديد العقوبــة علــى املدعــى عليهــم‬\n‫الثانــي والثالــث والرابــع لقــاء تعــدد وتكــرار ســوابقهم‪ ،‬ومصــادرة‬\n‫جــوال املدعــى عليــه اخلامــس املــروج ‪ .‬املســتخدم يف ارتــكاب اجلرميــة‬\n‫وإلغــاء الشــريحة املســتخدمة يف عمليــة الترويــج ‪ .‬أنكــر املدعــى عليهــم‬\n‫الدعــوى مــا عــدا الثالــث فقــد أجــاب باملصادقــة علــى احليــازة ألجــل‬\n‫االســتخدام وتعاطيــه احلبــوب احملظــورة ‪ -‬أشــار املدعــي العــام إلــى بينتــه‬\n‫وهــم شــهود القبــض ومحاضــر االعتــراف ‪ -‬توجــه التهمــة ضــد املدعــى‬\n‫عليهــم باالجتمــاع علــى مفســدة وإدانــة الثالــث واخلامــس باحليــازة وألجــل‬\n‫التعاطــي وتوجيــه التهمــة علــى اخلامــس بالترويــج ‪ ،‬قــررت احملكمــة‬\n‫احلكــم علــى املدعــى عليــه الثانــي بالســجن تســعة أشــهر تعزيــرا تبــدأ‬\n‫مــن تاريــخ إيقافــه‪ ،‬وجلــده مائــة جلــدة مفرقــة علــى دفعتــن مقــدار‬\n‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى أســبوعا لقــاء توجــه‬\n‫التهمــة يف حقــه باالجتمــاع علــى املفســدة‪ ،‬وتعزيــر املدعــى عليــه الثالــث‬\n‫بســجنه ســنتني اعتبــارا مــن تاريــخ توقيفــه لقــاء حيازتــه احلشــيش‬\n‫واحلبــوب احملظــورة‪ ،‬واملنــع مــن الســفر مــدة مماثلــة لســجنه‪ ،‬وتعزيــره‬\n\n\n                                                                                       ‫‪310‬‬\n\f      ‫ايضــا بســجنه ســتة أشــهر وجلــده مائــة جلــدة مفرقــة علــى دفعتــن مقــدار‬\n                                                                                   ‫ً‬\n      ‫كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى أســبوعا لقــاء توجــه‬\n      ‫التهمــة يف حقــه باالجتمــاع علــى املفســدة‪ ،‬وتعزيــر املدعــى عليــه الرابــع‬\n      ‫بســجنه ســتة أشــهر اعتبــارا مــن تاريــخ إيقافــه‪ ،‬وجلــده مائــة جلــدة‬\n      ‫مفرقــة علــى دفعتــن مقــدار كل دفعــة خمســون جلــدة بــن كل دفعــة‬\n      ‫وأخــرى أســبوعا لقــاء توجــه التهمــة يف حقــه باالجتمــاع علــى املفســدة‪،‬‬\n      ‫وتعزيــر املدعــى عليــه اخلامــس بســجنه أربــع ســنوات تبــدأ مــن تاريــخ‬\n      ‫إيقافــه‪ ،‬وجلــده ثالثــة آالف جلــدة مفرقــة علــى ســتني دفعــة مقــدار كل‬\n      ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى أســبوعا لقــاء توجــه شــبهة‬\n      ‫الترويــج واالجتمــاع علــى املفســدة يف حقــه‪ ،‬ومصــادرة املبلــغ املضبــوط‬\n      ‫بحوزتــه‪ ،‬ومصــادرة جوالــه وإلغــاء الشــريحة املســتخدمة يف عمليــة‬\n      ‫الترويــج‪ ،‬وأمــا املدعــى عليــه األول فقــررت احملكمــة عــدم احلكــم‬\n      ‫عليــه لعــدم حضــوره إال يف اجللســة األولــى‪ ،‬وقــرر املدعــى عليهــم الثانــي‬\n      ‫والثالــث والرابــع القناعــة واعتــرض اخلامــس علــى احلكــم‪ ،‬ومت تصديــق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ ،‬فلدينــا نحــن‬\n      ‫‪..........‬القضــاة باحملكمــة العامــة مبكــة املكرمــة‪ ،‬و بنــاء علــى‬\n      ‫املعاملــة الــواردة لنــا مــن فــرع هيئــة التحقيــق واالدعــاء العــام مبكــة‬\n      ‫املكرمــة برقــم ‪..........‬يف ‪1434/01/10‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة برقــم ‪..........‬يف ‪1434/01/12‬ه ـ واملقيــدة برقــم‬\n      ‫‪..........‬يف ‪1434/01/12‬ه ـ حضــر املدعــي العــام ‪..........‬حامــل الســجل‬\n\n‫‪311‬‬\n\f‫املدنــي رقــم ‪..........‬وقــدم الئحــة دعــواه ضــد ‪..........‬حامــل الســجل‬\n‫املدنــي رقــم ‪....................‬قائــا يف دعــوه عليهــم‪ :‬بصفتــي مدعي ـ ًا عام ـ ًا‬\n‫بدائــرة االدعــاء العــام لفــرع الهيئــة مبنطقــة مكــة املكرمــة أدعــي علــى‬\n‫املذكوريــن أعــاه وذلــك أنــه بتاريــخ ‪1433 / 8/ 21‬ه ـ وردت معلومــات‬\n‫إلدارة مكافحــة املخــدرات بالعاصمــة املقدســة مــن احــد مصادرهــا‬\n‫مفادهــا قيــام املدعــى عليــه اخلامــس ‪........./‬بترويــج احلبــوب احملظــورة‬\n‫بحــي ‪ ....‬واســتعد املصــدر الشــراء منــه‪ ،‬عليــه مت متكــن املصــدر مــن‬\n‫االتصــال علــى هاتفــه اجلــوال رقــم ‪..........‬حيــث طلــب منــه شــراء كميــة‬\n‫مــن احلبــوب احملظــورة مببلــغ ( ‪ ) 200‬مائتــي ريــال وأســتعد املدعــى عليــه‬\n‫اخلامــس ‪.........‬بالبيــع للمصــدر ‪،‬وطلــب مــن املصــدر احلضــور لــه بحــي ‪....‬‬\n‫مبفــرده‪ ،‬ومت تفتيــش املصــدر و تزويــده باملبلــغ املرقــم ‪،‬وعنــد الوصــول‬\n‫للموقــع احملــدد شــوهد املدعــى عليــه اخلامــس ‪.........‬أثنــاء مقابلتــه‬\n‫للمصــدر ويركــب معــه بســيارته وطلــب منــه التحــرك لداخــل احلــي ‪،‬‬\n‫بعدهــا تقابــا مــع املدعــى عليــه الرابــع ‪......... /‬وركــب معهــم وتوقفــوا‬\n‫عنــد أحــد املنــازل ونزلــوا مــن الســيارة جميعهــم ودخلــوا أحــد املنــازل ومت‬\n‫وضــع املنــزل حتــت املراقبــة وبعــد عشــرة دقائــق تقريب ـ ًا خــرج املصــدر‬\n‫وتقابــل مــع أفــراد الفرقــة القابضــة وقــام بتســليم قائــد الفرقــة الكميــة‬\n‫املشــتراة وهــي عبــارة عــن عــدد (‪ )5‬خمــس حبــات يشــتبه أن تكــون‬\n‫مــن حبــوب ا احملظــورة والتــي حصــل عليهــا مــن املدعــى عليــه اخلامــس‬\n‫‪.........‬مقابــل تســليمه املبلــغ املرقــم بحضــور أشــخاص كانــوا يجلســون‬\n‫عنــده‪ ،‬عليــه مت وضــع املنــزل حتــت املتابعــة املســتمرة وهــو عائــد‬\n‫للمدعــى عليــه الثانــي ‪......... /‬ومــن خــال املراقبــة شــوهد مجموعــة‬\n‫كبيــرة مــن األشــخاص يتــرددون عليــه وكان املدعــى عليــه الثانــي ‪/‬‬\n\n\n                                                                                          ‫‪312‬‬\n\f      ‫‪.........‬يقــوم باخلــروج ويتقابــل مــع أشــخاص ويقــوم بأخــذ أشــياء ويعطيهــم‬\n      ‫شــيء بطريقــة ســرية ولــم يتــم القبــض عليهــم لعــدم الكشــف عــن أفــراد‬\n      ‫الفرقــة ملــن هــم بداخــل الغرفــة وكذلــك شــوهد املدعــى عليــه الثانــي ‪/‬‬\n      ‫‪.........‬أثنــاء خروجــه مــن املنــزل فتــم القبــض عليــه وأفــاد أن الغرفــة عائده‬\n      ‫لــه شــخصي ًا وال مانــع لديــه مــن تفتيشــها وأن املدعــى عليــه اخلامــس ‪/‬‬\n      ‫‪.........‬موجــود بداخلهــا فتــم مداهمــة الغرفــة و مت القبــض علــى املدعــى‬\n      ‫عليــه اخلامــس ‪......... /‬وبتفتيشــه شــخصي ًا عثــر بجيــب ثوبــه األيســر‬\n      ‫الســفلي علــى كيــس صغيــر بداخلــه عــدد ( ‪ )111‬مئــة وأحــدى عشــر‬\n      ‫حبــة يشــتبه أن تكــون مــن احلبــوب احملظــورة و قطعــة بنيــة اللــون يشــتبه‬\n      ‫أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا (‪ ) 80‬ثمانــون جرامـ ًا كمــا‬\n      ‫عثــر علــى املبلــغ املرقــم كامــا بجيــب ثوبــه العلــوي و مبلــغ مالــي آخــر‬\n      ‫قــدره (‪ )680‬ســت مئــة وثمانــون ريــال وعلــى جهــاز هاتــف جــوال مــن نــوع‬\n      ‫‪ ....‬يحمــل نفــس الرقــم الــذي مت التنســيق عليــه‪ ،‬كمــا مت القبــض علــى‬\n      ‫املدعــى عليــه الرابــع ‪ ،......... /‬وكذلــك مت القبــض علــى املدعــى عليــه‬\n      ‫الثالــث ‪......... /‬وبتفتيشــه شــخصي ًا عثــر بجيــب ثوبــه األيســر الســفلي‬\n      ‫علــى قطعــة بنيــة اللــون يشــتبه أن تكــون مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫( ‪ )4‬أربــع جرامــات وعــدد (‪ )4‬أربــع حبــات يشــتبه أن تكــون مــن احلبــوب‬\n      ‫احملظــورة ‪ ،‬ومت القبــض علــى املدعــى عليــه األول ‪......... /‬وبتفتيشــه‬\n      ‫شــخصي ًا عثــر بجيــب بنطالــه اخللفــي األيســر علــى كيــس نايلــون‬\n      ‫بداخلــه عــدد (‪ )4.5‬أربــع حبــات ونصــف احلبــة يشــتبه أن تكــون مــن‬\n      ‫احلبــوب احملظــورة وكان يفــوح مــن الغرفــة رائحــة احلشــيش املخــدر‪-.‬‬\n      ‫عثــر للمدعــى عليــه اخلامــس ‪......... /‬علــى ســابقة ( ترويــج املخــدرات)‬\n      ‫ثبــت إدانتــه فيهــا ببيــع احلبــوب احملظــورة مبوجــب القــرار الشــرعي رقــم‬\n\n\n‫‪313‬‬\n\f‫(‪ ) 2/244‬وتاريــخ ‪1418/5/12‬ه ـ الصــادر مــن احملكمــة املســتعجلة‬\n                                                      ‫مبكــة ( املرفــق صورتــه )‪.‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ( ‪ ).........‬احتــواء العينات‬\n‫(أ‪،‬ب‪،‬ج) مــن احلبــوب املباعــة واملضبوطــة واملرســلة للتحليــل علــى مــادة‬\n‫األمفيتامــن املؤثــرة عقلي ـ ًا املدرجــة باجلــدول رقــم ( ‪ )2‬الفئــة (ب ) ‪،‬‬\n‫وايجابيــة العينــة (د) املضبوطــة واملرســلة للتحليــل للحشــيش املخــدر‬\n‫واحتوائهــا علــى املــادة الفعالــة لــه ‪،‬وهــو مــن املــواد املخــدرة املدرجــة‬\n‫باجلــدول رقــم (‪ )1‬فئــة (أ) امللحقــن بنظــام مكافحــة املخــدرات‬\n‫واملؤثــرات العقليــة الصــادر باملرســوم امللكــي الكــرمي رقــم ( م‪ )39 /‬يف‬\n‫‪1426 /7 /8‬هــ‪ .‬باســتجواب املدعــى عليــه اخلامــس ‪ :......... /‬أقــر بحيازة‬\n‫كيــس نايلــون بداخلــه عــدد( ‪ )111‬مئــة وأحــدى عشــرة حبــة مــن احلبــوب‬\n‫احملظــورة ‪ ،‬وقطعــة مــن احلشــيش املخــدر وزنهــا ( ‪ ) 80‬ثمانــون جرامــا ‪،‬‬\n‫بقصــد التعاطــي ‪ ،‬وأفــاد بــان ملكيــة الشــريحة ذات الرقــم ( ‪).........‬‬\n‫تعــود لــه ‪ ،‬وكذلــك ملكيــة جهــاز الهاتــف اجلــوال مــن نــوع ‪ .....‬ذو الرقــم‬\n‫( ‪ . ).........‬باســتجواب املدعــى عليــه الثالــث ‪ :......... /‬أقــر بحيــازة قطعــة‬\n‫مــن احلشــيش املخــدر وزنهــا ( ‪ )4‬أربــع جرامــات و عــدد ( ‪ )4‬أربــع حبــات‬\n‫مــن احلبــوب احملظــورة بقصــد التعاطــي ‪ .‬باســتجواب املدعــى عليــه األول‬\n‫‪ :.........‬أقــر بحيــازة كيــس نايلــون بداخلــه عــدد (‪ ) 4.5‬أربــع حبــات‬\n‫ونصــف احلبــة مــن احلبــوب احملظــورة بقصــد التعاطــي‪ ،‬وأقــر بتعاطــي‬\n‫نصــف حبــة مــن ذات الكميــة املضبوطــة معــه قبــل حوالــي شــهر مــن‬\n‫تاريــخ القبــض عليــه ‪ ،‬وذكــر بأنــه شــاهد املدعــى عليــه اخلامــس ‪/‬‬\n‫‪.........‬يقــوم ببيــع عــدد مــن احلبــوب احملظورة على شــخص كان متواجد ًا‬\n‫معهــم يف الغرفــة وخــرج منهــا ‪ .‬وقــد انتهــى التحقيــق إلــى توجيــه االتهــام‬\n\n\n                                                                                        ‫‪314‬‬\n\f      ‫لــكل مــن ‪ - 1 :‬املدعــى عليــه اخلامــس ‪......... /‬بترويــج عــدد (‪ )5‬خمــس‬\n      ‫حبــات ثبــت احتوائهــا علــى مــادة األمفيتامــن املؤثــرة عقلي ـ ًا عــن طريــق‬\n      ‫البيــع للمــرة الثانيــة وبحيــازة عــدد (‪ )111‬مئــة وأحــدى عشــر حبــة ثبــت‬\n      ‫احتوائهــا علــى مــادة األمفيتامــن املؤثــرة عقلي ـ ًا و(‪ )80‬ثمانــون جرام ـ ًا‬\n      ‫مــن احلشــيش املخــدر بقصــد الترويــج والتعاطــي و االجتماع على مفســدة‬\n      ‫‪ - 2.‬توجيــه االتهــام للمدعــى عليــه الثانــي ‪ ..... /‬بإعــداد منزلــه وكــرا‬\n      ‫لبيــع وتعاطــي املخــدرات واالجتمــاع علــى مفســدة‪ - 3.‬توجيــه االتهــام‬\n      ‫للمدعــى عليــه الرابــع ‪......... /‬باالشــتراك مــع املدعــى عليــه اخلامــس ‪/‬‬\n      ‫‪.........‬يف ترويــج ذات الكميــة عــن طريــق املســاعدة واالجتمــاع علــى‬\n      ‫مفســدة ‪ - 4.‬توجيــه االتهــام للمدعــى عليــه الثالــث ‪ :......... /‬بحيــازة ( ‪)4‬‬\n      ‫أربــع جرامــات مــن احلشــيش املخــدر وعــدد (‪ )4‬أربع حبات ثبــت احتوائها‬\n      ‫علــى مــادة األمفيتامــن املؤثــرة عقلي ـ ًا بقصــد التعاطــي والتعاطــي‬\n      ‫لنوعهمــا ســابقاً‪ ،‬واالجتمــاع علــى مفســدة‪ - 5 .‬توجيــه االتهــام للمدعــى‬\n      ‫عليــه األول ‪......... /‬بحيــازة عــدد (‪ )4.5‬أربــع حبــات ونصــف احلبــة ثبــت‬\n      ‫احتوائهــا علــى مــادة األمفيتامــن املؤثــرة عقلي ـ ًا بقصــد التعاطــي‬\n      ‫والتعاطــي مــن ذات الكميــة واالجتمــاع علــى مفســدة‪ .‬املؤيــد مبوجــب‬\n      ‫قــرار جلنــة إدارة الهيئــة رقــم (‪ ).........‬وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n      ‫‪ -1‬مــا ورد مبحضــر القبــض والضبــط والتفتيــش املنــوه عنهــا واملــدون‬\n      ‫علــى الصفحــة رقــم (‪ ) 13 ،12 ،11‬لفــة رقــم( ‪ -2 )1‬مــا ورد بالتقريــر‬\n      ‫الكيميائــي الشــرعي املنــوه عنــه واملرفــق لفــة رقــم (‪ -3 .)94‬مــا ورد‬\n      ‫مبحضــر البــاغ املنــوه عنــه املرفــق املــدون علــى الصفحــة رقــم (‪ ) 2‬لفــة‬\n      ‫رقــم (‪ -4.) 1‬مــا ورد مبحضــر ترقيــم ومطابقــة املبلــغ احلكومــي املنــوه‬\n      ‫عنــه املرفــق املــدون علــى الصفحــة رقــم (‪ ) 4‬لفــة رقــم (‪ -5.) 1‬مــا ورد يف‬\n\n\n‫‪315‬‬\n\f‫إقــرار املدعــى عليــه اخلامــس املــروج ‪......... /‬املنــوه عنــه لفــة رقــم (‪-6.)66‬‬\n‫مــا ورد يف إقــرار املدعــى عليــه الثالــث ‪......... /‬املنــوه عنــه لفــة رقــم‬\n‫(‪ -7.)55‬مــا ورد يف إقــرار املدعــى عليــه األول ‪......... /‬املنــوه عنــه لفــة‬\n‫رقــم (‪ -8 .)60‬مــا ورد مبحضــر االتصــال املنــوه عنــه املرفــق املــدون علــى‬\n‫الصفحــة رقــم (‪ ) 2‬لفــة رقــم (‪ -9.) 1‬مــا جــاء بإقــرار للمدعــى عليــه األول‬\n‫‪ ......... /‬مــن مشــاهدته للمدعــى عليــه اخلامــس املــروج ‪......... /‬وهــو يقــوم‬\n‫بترويــج عــدد مــن احلبــوب احملظــورة لشــخص كان موجــود معهــم‬\n‫بالغرفــة وخــرج منهــا لفــة رقــم (‪ -10 -10 ) 60‬كبــر الكمية املضبوطة‬\n‫مــع املدعــى عليــه اخلامــس املــروج ‪......... /‬قرينــة علــى أنهــا معــدة للترويــج‪.‬‬\n‫وحيــث إن مــا قــام بــه املدعــى عليهــم وهــم بكامــل أهليتهــم املعتبــرة‬\n‫شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظامـ ًا وفقـ ًا للمــادة ( الثالثــة ) الفقــرة‬\n‫( الثانيــة ) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم ( م‪ ) 39 /‬وتاريــخ ‪ 1426 / 7 / 8‬ه ـ واملعاقــب‬\n‫عليهــا اســتناد ًا للمــادة (‪ )37‬مــع مراعــاة مــا ورد باملــادة ( ‪ )62‬مــن ذات‬\n‫النظــام ‪،‬لــذا أطلــب إثبــات إدانتهــم مبــا أســند إليهــم ومعاقبتهــم‬\n‫بالعقوبــات األصليــة والتكميليــة التاليــة ‪1 -:‬ـ بالقتــل تعزيــز ًا للمدعــى‬\n‫عليــه اخلامــس املــروج ‪......... /‬لقــاء مــا أســند إليــه ‪ ،‬اســتناد ًا للفقــرة (‪)5‬‬\n‫مــن املــادة ( ‪ )37‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫املشــار إليــه ‪ -2.‬بالســجن واجللــد والغرامــة للمدعــى عليــه الرابــع ‪/‬‬\n‫‪،.........‬اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ ) 38‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة املشــار إليــه ‪،‬وتشــديد العقوبــة عليــه وفقـ ًا‬\n‫للفقــرة (‪/2‬ج) مــن ذات املــادة وإعمــال املــادة(‪ )58‬بحقــه‪ -3.‬بالســجن‬\n‫للمدعــى عليهمــا األول ‪......... /‬والثالــث ‪ ،......... /‬اســتناد ًا للفقــرة ( ‪)1‬‬\n\n\n                                                                                           ‫‪316‬‬\n\f      ‫مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثرات العقلية املشــار‬\n      ‫إليــه ‪ -4‬منــع املدعــى عليهــم‪ /‬األول ‪......... /‬والثالــث ‪......... /‬والرابــع‪/‬‬\n      ‫‪.........‬مــن الســفر خلــارج اململكــة بعــد انتهــاء تنفيــذ عقوبتهــم ‪ ،‬إســتناد ًا‬\n      ‫للفقــرة ( ‪ )1‬مــن املــادة ( ‪ ) 56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه‬\n      ‫‪ -5.‬احلكــم علــى املدعــى عليهــم ‪ /‬األول ‪.........‬والثاني‪.........‬والثالــث‬\n      ‫‪.........‬والرابــع‪......... /‬بعقوبــة تعزيريــة الجتماعهــم علــى مفســدة ‪-6‬‬\n      ‫مصــادرة جهــاز الهاتــف اجلــوال للمدعــى عليــه اخلامــس املــروج ‪ ... /‬ذو‬\n      ‫الرقــم املصنعــي ( ‪ ).........‬املســتخدم يف ارتــكاب اجلرميــة اســتناد ًا للفقرة‬\n      ‫( ‪ )1‬مــن املــادة ( ‪ )53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه و إلغــاء‬\n      ‫شــريحته ذات الرقــم ( ‪ )..........‬اســتناد ًا لبرقيــة صاحــب الســمو امللكــي‬\n      ‫وزيــر الداخليــة رقــم ( ‪ )9798‬يف ‪1428 /2/ 10-9‬ه ـ ‪ -7‬مصــادرة املبلــغ‬\n      ‫املضبــوط بحــوزة املدعــى عليــه اخلامــس املــروج ‪......... /‬و قــدره ( ‪)680‬‬\n      ‫ســت مئــة وثمانــون ريــال ســعودي ‪ ،‬اســتناد ًا للفقــرة رقــم ( ‪ )2‬مــن املــادة‬\n      ‫( ‪ ) 53‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪ -8‬تشــديد العقوبــة‬\n      ‫علــى املدعــى عليــه الثالــث ‪ ... /‬كونــه عســكرياً‪ ،‬اســتناد ًا للفقــرة ( أ)‬\n      ‫مــن ثانيـ ًا مــن املــادة ( ‪ )41‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ‪9.‬‬\n      ‫‪ -‬تعزيــر املدعــى عليــه الثانــي ‪......... /‬لقــاء إعــداد منزلــه وكــر ًا لترويــج‬\n      ‫وتعاطــي املخــدرات ‪-10 .‬التشــديد علــى املدعــى عليهــم الثانــي ‪......... /‬‬\n      ‫والثالــث ‪ ........./‬والرابــع‪.........‬يف العقوبــة لقــاء تعــدد وتكــرار ســوابقهم‬\n      ‫التــي لــم تردعهــم عقوباتهــا‪ ،‬إســتناد ًا لتعميــم صاحــب الســمو امللكــي‬\n      ‫وزيــر الداخليــة رقــم (‪ ) 93958/ 5/ 5/ 1‬وتاريــخ ‪1429 / 8 / 23‬هــ‪ .‬وبــاهلل‬\n      ‫التوفيــق ويف هــذا اجللســة حضــر املدعــى عليهــم الثانــي ‪.........‬حامــل‬\n      ‫الســجل املدنــي رقــم ‪..........‬واملدعــى عليــه الثالــث ‪..........‬حامــل الســجل‬\n\n\n‫‪317‬‬\n\f‫املدنــي رقــم ‪..........‬واملدعــى عليــه الرابــع ‪..........‬حامــل الســجل املدنــي‬\n‫رقــم ‪..........‬واملدعــى عليــه اخلامــس ‪..........‬حامــل الســجل املدنــي ‪..........‬‬\n‫ولــم يحضــر املدعــى عليــه األول ‪..........‬وبعــرض دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام‬  ‫علــى املدعــى عليــه الثانــي ‪..........‬أجــاب قائ ـ ً‬\n‫غيــر صحيــح فلــم أجهــز منزلــي لبيــع وتعاطــي املخــدرات والصحيــح أنــه‬\n‫حضــر املدعــى عليــه اخلامــس والثالــث برفقــة أخــي املدعــى عليــه الرابــع‬\n‫يريــدان اســتئجار شــقة يف حارتنــا يف شــارع ‪.........‬ولــم يجــدوا صاحــب‬\n‫العمــارة فأدخلتهــم يف غرفــة يف بيتــي إلــى حــن وصــول صاحــب العمــارة‬\n‫ثــم قبــض علينــا ووجــدوا بحــوزة املدعــى عليــه اخلامــس والثالــث حبــوب‬\n‫وحشــيش ولــو كنــت أعلــم بحيازتهمــا لهمــا مــا أدخلتهمــا هكــذا أجــاب‬\n‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه الثالــث ‪.........‬أجــاب‬\n‫ا مــا ذكــره املدعــي العــام مــن حيازتي ألربعة جرامات من احلشــيش‬             ‫قائـ ً‬\n‫املخــدر وأربــع حبــات مــن اإلمفيتامــن بقصــد التعاطــي فصحيــح ومــا‬\n‫ذكــره مــن التعاطــي ســابق ًا فصحيــح إال أنــه مــن ضمــن الســوابق التــي‬\n‫علــي أخــذت جزائــي عليهــا هكــذا أجــاب وبعــرض دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام‬   ‫علــى املدعــى عليــه الرابــع ‪.........‬أجــاب قائ ـ ً‬\n‫مــن قيامــي باالشــتراك مــع املدعــى عليــه اخلامــس بترويــج احلبــوب فغيــر‬\n‫صحيــح والصحيــح أنــه تربطنــي عالقــة قدميــة باملدعــى عليــه اخلامــس‬\n‫وقــد أتصــل بــي وطلــب منــي شــقة فذكــرت لــه أنــه يوجــد شــقة قريبــة‬\n‫مــن منــزل أخــي املدعــى عليــه الثانــي فحضــر املدعــى عليــه اخلامــس‬\n‫واتصلنــا علــى صاحبــة الشــقة فذكــرت أنهــا بعيدة فطلبت منــه الدخول‬\n‫إلــى منــزل أخــي إلــى حــن حضــور صاحبــة الشــقة ثــم صعــدت عنــد‬\n‫والدتــي يف نفــس العمــارة يف الــدور الثالــث فجــاء أبــن أخــي وذكــر لــي‬\n\n\n                                                                                          ‫‪318‬‬\n\f      ‫أنــه مت القبــض علــى املوجوديــن يف منــزل أخــي هكــذا أجــاب وبعــرض‬\n      ‫ا مــا‬ ‫دعــوى املدعــي العــام علــى املدعــى عليــه اخلامــس ‪ ...‬أجــاب قائ ـ ً‬\n      ‫ذكــره املدعــي العــام مــن قيامــي بترويــج احلبــوب احملظــورة فغير صحيح‬\n      ‫ومــا ذكــره مــن حيازتــي احلبــوب احملظــورة ( الكبتاغــون) واحلشــيش‬\n      ‫فصحيــح إال أن الكميــة التــي ذكرهــا غيــر صحيحــة والصحيــح أن‬\n      ‫احلبــوب عددهــا ســتون حبــة واحلشــيش وزنــه خمســة وســتون جرام ـ ًا‬\n      ‫هكــذا أجــاب وبســؤال املدعــي العــام هــل لديــه بينــة علــى دعــواه قــال‬\n      ‫نعــم وأطلــب مهلــه إلحضارهــا ‪ ،‬ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫واملدعــى عليهــم الثانــي والثالــث والرابــع واخلامــس‪ ،‬وحــن حضــر‬\n      ‫املدعــى عليــه األول وقــد مت طلبــه بخطابنــا ملديــر شــرطة احملاكــم برقــم‬\n      ‫‪34/486793‬يف‪1434/2/26‬هـ ـ وبســؤال املدعــي العــام هــل أحضــر‬\n      ‫البينــة التــي اســتمهل مــن أجلهــا قــال نعم‪ ،‬وأحضــر ‪..........‬الســجل املدني‬\n      ‫رقــم ‪ ..........‬وبســؤاله عمــا لديــه أجــاب قائـاً‪ :‬إننــي أعمــل يف مكافحــة‬\n      ‫املخــدرات وأشــهد أن املصــدر اتصــل علــى املدعــى عليــه اخلامــس ‪ ....‬معــه‬\n      ‫علــى بيــع حبــوب مبائتــي ريــال‪ ،‬وكان املصــدر مشــغل الصــوت اخلارجــي‬\n      ‫جلهــاز اجلــوال‪ ،‬ثــم بعــد ذلــك انتقلنــا للموقــع وكان املدعــى عليــه اخلامس‬\n      ‫واقفــا يف الشــارع وركــب مــع املصــدر‪ ،‬ولــم نشــاهد االســتالم والتســليم‬\n      ‫ثــم اجتهــوا ونحــن نراقــب وأخــذوا املدعــى عليــه الرابــع ‪ ،..........‬ثــم‬\n      ‫اجتهــوا إلــى بيــت املدعــى عليــه الثانــي‪..........‬وكان ينتظرهــم عنــد‬\n      ‫البــاب بلبــس رياضــي ودخلــوا البيــت ودخــل معهــم املصــدر ثــم خــرج‬\n      ‫املصــدر بعــد عشــر دقائــق وســلمنا خمــس حبــات‪ ،‬ومكثنــا نراقــب‬\n      ‫البيــت والحظنــا املدعــى عليــه الثانــي ‪.........‬يخــرج كل عشــر دقائــق‬\n      ‫ويحصــل بينــه وبــن بعــض األشــخاص احتــكاك ويظهــر مــن حالهــم أن‬\n\n\n‫‪319‬‬\n\f‫بينهــم اســتالم وتســليم ألنهــم يحضــرون بســيارات ودبابــات وتتــم املبادلــة‬\n‫بســرعة شــديدة‪ ،‬ثــم داهمنــا العمــارة وكان املدعــى عليــه الثانــي ‪.........‬‬\n‫عنــد البــاب فقبضنــا عليــه ثــم دخلنــا الشــقة فوجدنــا املدعــى عليهــم‬\n‫األول والثالــث واخلامــس يف شــقة يف الــدور األول واملدعــى عليــه الرابــع‬\n‫نــازال مــن الــدور الثانــي‪ ،‬ووجدنــا مــع املدعــى عليــه اخلامــس ‪.........‬املبلــغ‬\n‫املرقــم وقطعــة حشــيش كبيــرة وحبــوب كثيــرة تزيــد علــى مائــة حبــة‬\n‫‪،‬كمــا وجدنــا مــع املدعــى عليــه الثالــث ‪.........‬حبــوب وحشــيش‪،‬‬\n‫ووجدنــا مــع املدعــى عليــه األول ‪.........‬حبــوب يف جيبــه اخللفــي وال أذكــر‬\n‫عــدد احلبــوب و كميــة احلشــيش هــذا مــا لــدي ‪ ،‬كمــا أحضــر ‪..........‬‬\n‫حامــل الســجل املدنــي رقــم ‪..........‬وبســؤاله عمــا لديــه أجــاب قائـاً‪ :‬إننــي‬\n‫أعمــل يف مكافحــة املخــدرات وأشــهد أن املصــدر اتصــل علــى املدعــى‬\n‫عليــه اخلامــس ‪..........‬واتفــق معــه بيــع حبــوب ال أذكــر كــم قيمتهــا‪،‬‬\n‫وكان املصــدر مشــغل الصــوت اخلارجــي جلهــاز اجلــوال‪ ،‬ثــم بعــد ذلــك‬\n‫انتقلنــا لبيــت املدعــى عليــه اخلامــس وركــب مــع املصــدر‪ ،‬ولــم نشــاهد‬\n‫االســتالم والتســليم ثــم اجتهــوا ونحــن نراقــب إلــى جهــة ‪ .....‬وأخــذوا‬\n‫املدعــى عليــه الرابــع ‪ ،..........‬ثــم اجتهــوا إلــى بيــت املدعــى عليــه الثانــي‬\n‫‪.........‬ودخلــوا البيــت ودخــل معهــم املصــدر ثــم خــرج املصــدر وســلمنا‬\n‫خمــس حبــات‪ ،‬ومكثنــا نراقــب البيــت قريبــا مــن الســاعتني والحظنــا‬\n‫املدعــى عليــه الثانــي ‪.........‬يخــرج كل عشــر دقائــق ويحصــل بينــه وبــن‬\n‫بعــض االشــخاص احتــكاك ويظهــر مــن حالهــم أن بينهــم اســتالم‬\n‫وتســليم‪ ،‬ثــم داهمنــا العمــارة فوجدنــا املدعــى عليهــم األول والثانــي‬\n‫والثالــث واخلامــس يف شــقة يف الــدور األول واملدعــى عليــه الرابــع نــازال‬\n‫مــن الــدور الثانــي‪ ،‬ووجدنــا مــع املدعــى عليــه اخلامــس ‪.........‬املبلــغ املرقــم‬\n\n\n                                                                                           ‫‪320‬‬\n\f      ‫وحشــيش وحبــوب كثيــرة تزيــد علــى مائــة حبــة‪ ،‬كمــا وجدنــا مــع‬\n      ‫املدعــى عليــه الثالــث ‪.........‬حبــوب وحشــيش‪ ،‬ووجدنــا مــع املدعــى عليــه‬\n      ‫األول ‪ .....‬حبوب يف جيبه اخللفي ال أذكر عددها هذا ما لدي‪،‬وبعرض‬\n      ‫الشــهود وشــهادتهم علــى املدعــى عليــه الثانــي ‪.........‬أجــاب قائ ـاً‪ :‬أمــا‬\n      ‫الشــهود فهــم الذيــن قبضــوا علينــا‪ ،‬وشــهادتهم غيــر صحيحــة وذلــك أن‬\n      ‫األشــخاص الذيــن كنــت أقابلهــم هــم مــن جيرانــي‪ ،‬ولــم يحصــل بينــا‬\n      ‫بيــع وشــراء أو اســتالم وتســليم لشــيء محظــور‪ ،‬هكــذا أجــاب‪،‬‬\n      ‫وبعــرض الشــهود وشــهادتهم علــى املدعــى عليــه الثالــث قــال أمــا الشــهود‬\n      ‫فــا أذكرهــم وأمــا شــهادتهم بشــأن احليــازة فصحيحــة‪ ،‬ولــم أكــن‬\n      ‫أعلــم عمــا ســوى ذلــك شــيئاً‪ ،‬هكــذا أجــاب‪ ،‬وبعــرض ذلــك علــى‬\n      ‫املدعــى عليــه الرابــع ‪.........‬أجــاب قائـاً‪ :‬أمــا الشــهود فهــم الذيــن قبضــوا‬\n      ‫علينــا وأمــا شــهادتهم فغيــر صحيحــة‪ ،‬والصحيــح أنــي ركبــت مــع‬\n      ‫املصــدر واملدعــى عليــه اخلامــس ألجــل إيصالــه للشــقة التــي يريــد‬\n      ‫اســتئجارها ولــم أكــن أعلــم عــن احلبــوب شــيئا‪ ،‬ثــم ذهبنــا لبيــت أخــي‬\n      ‫ألجــل انتظــار صاحــب الشــقة‪ ،‬هكــذا أجــاب وبعــرض الشــهود‬\n      ‫وشــهادتهم علــى املدعــى عليــه اخلامــس ‪.........‬قــال‪ :‬أمــا الشــهود فهــم‬\n      ‫الذيــن قبضــوا علينــا وأمــا شــهادتهم فغيــر صحيحــة وذلــك أن املصــدر‬\n      ‫أعرفــه و أعــرف أخيــه وهــو يتعاطــى املخــدرات فركبــت معــه ألجــل‬\n      ‫الذهــاب للبنــك ‪ ....‬وطلبــت منــه مائتــي ريــال قرض ـاً‪ ،‬ثــم دخلنــا البيــت‬\n      ‫وقبضــوا علينــا ومعــي احلبــوب واحلشــيش لكنهــا ليســت بالكميــة التــي‬\n      ‫ذكرهــا الشــهود وإمنــا عــدد احلبــوب خمســة وســتون حبــة‪ ،‬واحلشــيش‬\n      ‫خمســة وخمســون جــرام‪ ،‬هكــذا أجــاب‪ ،‬وبســؤال املدعــي العــام هــل‬\n      ‫لديــه زيــادة بينــة قــال‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‪ ،‬ثــم جــرى‬\n\n\n‫‪321‬‬\n\f‫االطــاع علــى محضــر القبــض والتفتيــش املــدون علــى ملــف االســتدالل‬\n‫اللفــة ‪ 1‬صفحــة ‪ 13-11‬كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه‬\n‫األول املــدون علــى لفــة رقــم ‪ 60‬وإقــرار املدعــى عليــه الثالــث املــدون‬\n‫علــى لفــة ‪ 55‬وإقــرار املدعــى عليــه اخلامــس املــدون علــى لفــة رقــم ‪66‬‬\n‫كمــا جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي الصــادر مــن‬\n‫مركــز مراقبــة الســموم والكيميــاء الطبيــة الشــرعية مبكــة املكرمة‬\n‫برقــم ‪..........‬يف ‪1433/08/25‬ه ـ فوجدتهــا طبــق مــا ذكــره املدعــي‬\n‫العــام يف دعــواه كمــا جــرى االطــاع علــى صحيفــة الســوابق للمدعــى‬\n‫عليــه الثانــي ‪.........‬الصــادرة مــن اإلدارة العامــة لألدلــة اجلنائيــة برقــم‬\n‫‪.........‬يف ‪1433/08/23‬ه ـ واملتضمنــة ثــاث ســوابق األولــى حيــازة‬\n‫املخــدرات والثانيــة حيــازة املخــدرات وشــرب املســكر والثالثــة ســرقة‬\n‫وبعرضهــا عليــه صــادق عليهــا‪ ،‬كمــا جــرى االطــاع علــى صحيفــة‬\n‫الســوابق للمدعــى عليــه الثالــث ‪.........‬الصــادرة مــن اإلدارة العامــة لألدلة‬\n‫اجلنائيــة برقــم ‪.........‬يف ‪1433/08/24‬ه ـ واملتضمنــة وجــود ســت ســوابق‬\n‫األولــى محاولــة دخــول منــزل لغــرض ســيئ والثانيــة اعتــداء الســلب‬\n‫والثالثــة ســرقة ســيارات وأمــوال وإتــاف والرابعــة واخلامســة والسادســة‬\n‫حيــازة واســتعمال مخــدرات وبعرضهــا عليــه صــادق عليهــا‪ ،‬كمــا جــرى‬\n‫االطــاع علــى صحيفــة الســوابق للمدعــى عليــه الرابــع ‪.........‬الصــادرة‬\n‫مــن اإلدارة العامــة لألدلــة اجلنائيــة برقــم ‪.........‬يف ‪1433/08/24‬ه ـ‬\n‫واملتضمنــة وجــود عشــرين ســابقة األولــى انتحــال شــخصية رجــال األمــن‬\n‫والثانيــة شــرب املســكرات ومحاولــة اللــواط والثالثــة والســابعة والثامنــة‬\n‫والتاســعة والعاشــرة شــرب املســكرات والرابعــة ســرقه مــن ســيارات‬\n‫واخلامســة اســتدراج طفــل أو طفلــة والسادســة شــرب املســكرات‬\n\n\n                                                                                      ‫‪322‬‬\n\f      ‫واســتدراج طفــل أو طفلــة وقيــادة الســيارة وهــو بحالــة ســكر واحلاديــة‬\n      ‫عشــرة ســرقة محــات جتاريــة والثانيــة عشــرة حيــازة ســاح بــدون‬\n      ‫ترخيــص وذخيــرة وشــرب املســكر وســرقة مــن ســيارة والثالثــة عشــرة‬\n      ‫شــرب املســكر وتكســير زجــاج ســيارة والســرقة منهــا والرابعــة عشــرة‬\n      ‫اشــتباه ســكر واخلامســة عشــرة شــرب املســكر وحيازتــه واعتــداء‬\n      ‫والسادســة عشــرة شــرب املســكر وقيــادة الســيارة وهــو بحالــة ســكر‬\n      ‫والســابعة عشــرة دخــول منــازل لغــرض ســيئ وفعــل فاحشــة الزنــا وســرقة‬\n      ‫والثامنة عشــرة ترويج واســتعمال املخدرات والتاســعة عشــرة والعشــرون‬\n      ‫حيــازة املخــدرات وبعرضهــا عليــه صــادق كمــا جــرى االطــاع علــى‬\n      ‫صحيفــة الســوابق للمدعــى عليــه اخلامــس الصــادرة مــن اإلدارة العامــة‬\n      ‫لألدلــة اجلنائيــة برقــم ‪.........‬يف ‪1433/8/24‬ه ـ واملتضمنــة وجــود عشــر‬\n      ‫ســوابق األولــى شــرب مســكر‪ ،‬والثانيــة فعــل فاحشــة اللــواط‪ ،‬والثالثــة‬\n      ‫اجتمــاع علــى مفســدة‪ ،‬والرابعــة اســتعمال وترويــج مخــدرات‪ ،‬واخلامســة‬\n      ‫والســابعة‪ :‬حيــازة مخــدرات‪ ،‬والسادســة حيــازة ســاح بــدون ترخيــص‪،‬‬\n      ‫وحيــازة ذخيــرة‪ ،‬والثامنــة حيــازة وترويــج مخــدرات‪ ،‬وحيــازة ســاح‬\n      ‫بــدون ترخيــص‪ ،‬وحيــازة ذخيــرة‪ ،‬والتاســعة‪ :‬ترويــج مخــدرات‪،‬‬\n      ‫والعاشــرة مخالفــة تعليمــات‪ ،‬وبعرضهــا عليــه صــادق عليها ‪ ،‬ويف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام واملدعــى عليهــم الثانــي والثالــث والرابــع‬\n      ‫واخلامــس‪ ،‬ولــم يحضــر املدعــى عليــه األول وقــد مت طلبــه مبوجــب‬\n      ‫خطابنــا رقــم‪ ..........‬يف ‪1434/3/3‬ه ـ وقــرر املدعــي العــام قائـاً‪ :‬أطلــب‬\n      ‫احلكــم علــى احلاضريــن وتأجيــل احلكــم علــى الغائــب املدعــى عليــه‬\n      ‫األول ‪ ..........‬إلــى حــن إحضــاره هكــذا قــرر ‪ ،‬ثــم جــرى االطــاع علــى‬\n      ‫القــرار الشــرعي الصــادر مــن احملكمــة املســتعجلة مبكــة املكرمــة‬\n\n\n‫‪323‬‬\n\f‫برقــم ‪2/244‬يف ‪1418/5/12‬ه ـ واملتضمــن ثبــوت إدانــة ‪ ..........‬بترويــج‬\n‫ثــاث حبــات مــن حبــوب اإلمفيتامــن احملظــورة عــن طريــق البيــع كمــا‬\n‫جــرى ســؤال املدعــى عليــه الثالــث و اخلامــس هــل تعاطيــا مــن احلبــوب‬\n‫واحلشــيش التــي يف حوزتهمــا‪ ،‬فأجــاب كل واحــد منهمــا قائــا‪ :‬لــم‬\n‫أتعــاط شــيئا منهــا هكــذا أجابــا‪ ،‬كمــا جــرى ســؤال املدعــى عليــه‬\n‫الرابــع هــل اســتلم املدعــى عليــه اخلامــس املبلــغ املرقــم مــن املصــدر‬\n‫بحضرتــه قــال ‪ :‬ال هكــذا أجــاب‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وشــهادة الشــاهدين‪ ،‬ومــا جــرى االطــاع عليــه مــن أوراق‬\n‫املعاملــة‪ ،‬ومبــا أن املدعــى عليــه الثانــي أنكــر دعــوى املدعــي العــام‬\n‫بجعــل بيتــه وكــر ًا لبيــع وتعاطــي املخــدرات واالجتمــاع علــى املفســدة‬\n‫ودفــع بعــدم علمــه بحــال املوجوديــن معــه‪ ،‬وملــا جــاء يف شــهادة الشــاهدين‬\n‫مــن مشــاهدة املدعــى عليــه الثانــي ميــارس تســلم ًا وتســليما للواقفــن عنــد‬\n‫بــاب بيتــه‪ ،‬وتعــدد ســوابقه املماثلــة‪ ،‬ومبــا أن املدعــى عليــه الثالــث‬\n‫صــادق علــى دعــوى املدعــي العــام بحيــازة احلبــوب واحلشــيش املذكــورة‬\n‫يف دعــواه بقصــد التعاطــي وأنكــر االجتمــاع علــى املفســدة‪ ،‬مــع تعــدد‬\n‫ســوابقه املماثلــة ومبــا أن املدعــى عليــه الرابــع أنكــر دعــوى املدعــي‬\n‫العــام‪ ،‬ومبــا أن مصادقتــه علــى ركوبــه مــع املدعــى عليــه اخلامــس‬\n‫واملصــدر ودخولــه املنــزل يقــوي التهمــة يف حقــه الســيما مــع كثــرة‬\n‫ســوابقه املماثلــة‪ ،‬ومبــا أن املدعــى عليــه اخلامــس أنكــر دعــوى الترويــج‬\n‫أو احليــازة بقصــد الترويــج‪ ،‬ولــم يقــم املدعــي العــام البينــة املوصلــة علــى‬\n‫ذلــك‪ ،‬ومبــا أنــه صــادق علــى حيــازة احلبــوب واحلشــيش بقصــد التعاطــي‪،‬‬\n‫ومبــا أن مــا جــاء يف شــهادة الشــاهدين‪ ،‬ووجــود املبلــغ املرقــم معــه‪،‬‬\n‫ووجــود احلبــوب احملظــورة مــع املصــدر‪ ،‬مــع كبــر كميــة احلبــوب‬\n\n\n                                                                                       ‫‪324‬‬\n\f      ‫واحلشــيش التــي يف حوزتــه ووجــود ســابقة الترويــج عليــه وتعــدد ســوابقه‬\n      ‫املماثلــة كل ذلــك يقــوي التهمــة القويــة يف حقــه بالترويــج لــذا كلــه فقــد‬\n      ‫ثبتــت لدينــا توجــه التهمــة يف حــق املدعــى عليهــم الثانــي والثالــث والرابــع‬\n      ‫واخلامــس باالجتمــاع علــى مفســدة كمــا ثبــت لدينا إدانــة املدعى عليهما‬\n      ‫الثالــث واخلامــس بحيــازة احلبــوب احملظــورة واحلشــيش بقصــد التعاطــي‬\n      ‫كمــا ثبــت لدينــا توجــه التهمــة القويــة يف حــق املدعــى عليــه اخلامــس‬\n      ‫بالترويــج لــذا كلــه فقــد حكمنــا مبــا يلــي ‪ :‬أو ًال ‪ /‬صــرف النظــر عــن‬\n      ‫دعــوى املدعــي العــام بقتــل املدعــى عليــه اخلامــس تعزيــر ًا وســجن وجلــد‬\n      ‫املدعــى عليــه الرابــع اســتناد ًا للفقــرة ‪ 1‬مــن املادة ‪ 38‬لعــدم ثبوت موجبه‪،‬‬\n      ‫ثاني ـ ًا ‪ /‬تعزيــر املدعــى عليــه الثانــي بســجنه تســعة أشــهر اعتبــار ًا مــن‬\n      ‫تاريــخ إيقافــه وجلــده مائــة جلــدة مفرقــة علــى دفعتــن مقــدار كل دفعــة‬\n      ‫خمســون جلــدة بــن كل دفعــة واألخــرى أســبوع ًا لقــاء توجــه التهمــة يف‬\n      ‫حقــه باالجتمــاع علــى املفســدة‪ ،‬ثالث ـ ًا ‪ /‬تعزيــر املدعــى عليــه الثالــث‬\n      ‫بســجنه ســنتني اعتبــار ًا مــن تاريــخ إيقافــه لقــاء حيازتــه احلبــوب احملظورة‬\n      ‫واحلشــيش ومنعــه مــن الســفر مــدة مماثلــة لســجنه رابعـ ًا ‪ /‬تعزيــر املدعــى‬\n      ‫عليــه الثالــث بســجنه ســتة أشــهر وجلــده مائــة جلــدة مفرقــة علــى دفعتــن‬\n      ‫مقــدار كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى أســبوع ًا‬\n      ‫لقــاء توجــه التهمــة يف حقــه باالجتمــاع علــى مفســدة ‪ ،‬خامسـ ًا ‪ /‬تعزيــر‬\n      ‫املدعــى عليــه الرابــع بســجنه ســتة أشــهر اعتبــار ًا مــن تاريــخ إيقافــه‬\n      ‫وجلــده مائــة جلــدة مفرقــة علــى دفعتــن مقــدار كل دفعة خمســون جلدة‬\n      ‫بــن كل دفعــة واألخــرى أســبوعا لقــاء توجــه التهمــة يف حقــه باالجتمــاع‬\n      ‫علــى املفســدة ‪،‬سادس ـ ًا ‪ /‬تعزيــر املدعــى عليــه اخلامــس بســجنه ســنتني‬\n      ‫اعتبــار ًا مــن تاريــخ إيقافــه لقــاء حيازتــه احلبــوب احملظــورة واحلشــيش‬\n\n\n‫‪325‬‬\n\f‫ومنعــه مــن الســفر مــدة مماثلــة لســجنه ‪ ،‬ســابع ًا ‪ /‬تعزيــر املدعــى عليــه‬\n‫اخلامــس بســجنه أربــع ســنوات وجلــده ثالثــة آالف جلــدة مفرقــة علــى‬\n‫ســتني دفعــة مقــدار كل دفعــة خمســون جلــدة بــن كل دفعــة واألخــرى‬\n‫أســبوع ًا لقــاء توجــه شــبهة الترويــج واالجتمــاع علــى املفســدة يف حقــه‬\n‫ومصــادرة جهــاز الهاتــف اجلــوال العائــد إليــه املذكــور يف دعــوى املدعــي‬\n‫العــام وإلغــاء شــريحته ومصــادرة املبلــغ املضبــوط بحوزتــه وقدره ســتمائة‬\n‫وثمانــون ريــا ًال ســعودي ًا ‪ ،‬كمــا جــرى إفهــام املدعــي العــام بــأن احلكــم‬\n‫علــى املدعــى عليــه األول ســيتم حــن إحضــاره ‪ ،‬وبعــرض احلكــم علــى‬\n‫الطرفــن قــرر املدعــى عليهــم الثانــي والثالــث والرابــع القناعــة كمــا‬\n‫قــرر املدعــى عليــه اخلامــس واملدعــي العــام االعتــراض بالئحــة وجــرى‬\n‫تســليمهما نســخة مــن احلكــم حــا ًال لتقــدمي اعتراضهمــا عليــه خــال‬\n‫ثالثــن يوم ـ ًا وإن لــم يقدمــا اعتراضهمــا ســيتم الرفــع حملكمــة‬\n‫االســتئناف خــال خمســة وأربعــن يومـ ًا وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                           ‫نبينا محمد ‪ .‬حرر يف ‪1434/3/9‬هـ‬\n       ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده ‪ ،‬وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائية اخلماســية الثانيــة مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم‪ ..........‬وتاريــخ‬\n‫‪1434/5/7‬ه ـ املرفــق بهــا القــرار رقــم ‪..........‬وتاريــخ ‪1434/3/10‬ه ـ‬\n‫الصــادر مــن أصحــاب الفضيلــة القضــاة باحملكمــة العامــة مبكــة‬\n‫املكرمــة ‪..........‬املتضمــن دعــوى املدعــي العــام ضــد‪.......... /‬ورفقــاه‬\n                   ‫املتهمــن يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والئحته االعتراضيــة تقرر باألكثرية‬\n\n\n                                                                                      ‫‪326‬‬\n\f      ‫املوافقــة علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                       ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪327‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":309,"source_page_end":327,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b8cd74660b6f09544f95b7e3af46ec77cc7e540022f5b8a07c42f5ba635b8d4e","normalized_text_hash":"1b1075f0059dbc45f7b242527b210bdc0b090463e9bb90669af0092e7ae0cb4a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p309-3459136"},{"id":"ea139d78-d75a-55ac-a11e-ffe829330a2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -االجتار يف احلشيش املخدر - تعاطي احلشيش املخدر -تضليل جهة التحقيق ومقاومة الشرطة -وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة ومصادرة السيارة واجلوال والشريحة املستخدمة يف اجلرمية واإلبعاد عن الباد واملنع من السفر.","document_number":"3459075","case_number":"3420255","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/12","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -االجتار يف احلشيش املخدر - تعاطي احلشيش املخدر -تضليل جهة التحقيق ومقاومة الشرطة -وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة ومصادرة السيارة واجلوال والشريحة املستخدمة يف اجلرمية واإلبعاد عن الباد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3459075 :‬تاريخه‪1434/01/12 :‬هـ‬\n                     ‫رقم الدعوى‪3420255:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34219160‬تاريخه‪1434/5/21 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر‪ -‬االجتــار يف احلشــيش املخــدر ‪-‬‬\n‫تعاطــي احلشــيش املخــدر ‪ -‬تضليــل جهــة التحقيــق ومقاومــة الشــرطة‬\n‫‪ -‬وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ومصــادرة‬\n‫الســيارة واجلــوال والشــريحة املســتخدمة يف اجلرميــة واإلبعــاد عــن‬\n                                               ‫البــاد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n    ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليهــم لقيامهــم بترويــج مخــدر احلشــيش‪،‬‬\n‫بقصــد الكســب املــادي‪ ،‬مت القبــض علــى املدعــى عليهــم يف شــقة‬\n‫وبحوزتهــم احلشــيش املخــدر أقــر املدعــى عليهــم بالترويــج والتعاطــي‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫احلشــيش‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى عليهــم بالســجن‬\n‫واجللــد والغرامــة مــع تشــديد العقوبــة عليهــم ومصــادرة جهــاز اجلــوال‬\n‫املســتخدم يف اجلرميــة وإلغــاء اخلدمــة عــن الشــريحة‪ ،‬إبعــاد الثالــث عــن‬\n‫البــاد بعــد االنتهــاء مــن تنفيــذ عقوبتــه ومنــع األول والثانــي والرابــع‬\n\n                                                                                  ‫‪328‬‬\n\f      ‫مــن الســفر خــارج البــاد بعــد انتهــاء تنفيــذ عقوبتهــم تعزيــر األول‬\n      ‫والرابــع شــرعا لقــاء مقاومتهــم للفرقــة القابضــة وتعزيــر الثالــث شــرعا‬\n      ‫لقــاء محاولتــه تضليــل جهــة التحقيق‪.‬حكمــت احملكمــة بثبــوت إدانــة‬\n      ‫املدعــى عليــه األول والثالــث والرابــع بترويــج احلشــيش بقصــد االجتــار‬\n      ‫والتعاطــي‪ ،‬وإدانــة الثانــي بالشــروع يف تســليم احلشــيش املخــدر‪،‬‬\n      ‫فقــررت احملكمــة احلكــم علــى املدعــى عليهــم األول والثالــث والرابــع‬\n      ‫بالســجن تســع ســنوات يحتســب منهــا مــدة إيقافهــم بســبب القضيــة‪،‬‬\n      ‫وجلــد كل واحــد منهــم ألــف جلــدة مفرقــة علــى عشــرين دفعــة بــن‬\n      ‫كل دفعــة وأخــرى عشــر أيــام‪ ،‬إلزامهــم بدفــع غرامــة ماليــة قدرهــا‬\n      ‫ألــف وخمســمائة ري ــال علــى كل واحــد منهــم‪ ،‬ســجن املدعــى عليــه‬\n      ‫الثانــي ســت ســنوات يحتســب منهــا مــدة إيقافــه بســبب القضيــة‪،‬‬\n      ‫وجلــده ثمانــن جلــدة لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬وجلــده ســتمائة‬\n      ‫جلــدة مفرقــة علــى اثنــا عشــر دفعــة بــن كل دفعــة واخــرى عشــرة أيــام‬\n      ‫وذلــك بعــد احلــد بشــهر‪ ،‬وغرامــة ماليــة قدرهــا ألــف وخمســمائة ري ــال‪،‬‬\n      ‫ومصــادرة الســيارتني املســتخدمتني يف اجلرميــة‪ ،‬ومصــادرة جهــاز اجلــوال‬\n      ‫واملســتخدم يف اجلرميــة وإلغــاء اخلدمــة عــن الشــريحة‪ ،‬إبعــاد املدعــى‬\n      ‫عليــه الثالــث خــارج البــاد بعــد انتهــاء تنفيــذ عقوبتهــم‪ ،‬ومنــع األول‬\n      ‫والثانــي والرابــع مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتهــم مــدة‬\n      ‫مماثلــة حملكوميتهــم‪ ،‬قــرر املدعــى عليهــم عــدم قناعتهــم باحلكــم ‪ ،‬مت‬\n                             ‫تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪..........‬وتاريــخ‬\n‫‪1434/01/12‬ه املقيــدة باحملكمــة برقــم ‪1434/01/11 ..........‬ه ففــي‬\n‫يــوم الثالثــاء املوافــق ‪1434/01/27‬ه ـ افتتحــت اجللســة الســاعة ‪: 45‬‬\n‫‪10‬وفيهــا تقــدم املدعــي ‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم(‪ )..........‬وتكليــف رقــم ‪.........‬وتاريــخ ‪1433/3/6‬ه ـ بالئحــة دعــوى‬\n‫وفيهــا أدعــي علــى ‪ ، .........../‬عســكري برتبــة جنــدي أول‪ ،‬موقــوف‬\n‫بالســجن العــام مبحافظــة جــدة بأمــر متديــد التوقيــف رقــم(‪ ).........‬بتاريــخ‬\n‫‪1433/6/21‬ه ـ ‪)29( ،..........‬عامـاً‪ .......... 2،‬ســعودي اجلنســية مبوجــب‬\n‫بطاقــة رقــم (‪ ، )..........‬موقــوف بالســجن العــام مبحافظــة جــدة بأمــر‬\n                      ‫متديــد التوقيــف رقــم (‪ ).........‬بتاريــخ ‪1433/6/21‬هــ‪.‬‬\n‫‪ )32( ،.......... .3‬عام ـاً‪ ،‬مينــي اجلنســية مبوجــب اقامــة رقــم‬\n‫(‪،)..........‬موقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد التوقيــف‬\n                                      ‫رقــم‪ .........‬بتاريــخ ‪1433/6/21‬هــ‪.‬‬\n‫‪ )40( ،.......... .4‬عاماً‪ ،‬ســعودي اجلنســية مبوجب بطاقة رقم (‪،)..........‬‬\n‫موقــوف بالســجن العــام مبحافظــة جــدة بأمــر متديــد التوقيــف رقــم‬\n                                           ‫(‪ ).........‬بتاريــخ ‪1433/6/21‬هــ‪.‬‬\n‫ـاء إلخباريــة مــن احــد املتعاونــن ملكافحــة‬‫بتاريــخ ‪1433/6/15‬ه ـ وبنـ ً‬\n‫املخــدرات مبحافظــة جــدة مفادهــا وجــود شــبكة تقــوم بتهريــب وترويــج‬\n‫املخــدرات مــن منطقــة جيــزان إلــى محافظــة جــدة‪ ،‬وأنــه مت االتفــاق مــع‬\n\n                                                                                      ‫‪330‬‬\n\f      ‫أحــد عناصــر هــذه الشــبكة يتواجــد علــى جــوال رقــم (‪ )..........‬علــى‬\n      ‫شــراء (‪ )35‬خمســة وثالثــون كيلــو مــن مــادة احلشــيش املخــدر مببلــغ‬\n      ‫(‪ )13000‬ثالثــة عشــر ألــف ريــال للكيلــو الواحــد علــى أن يســتلم‬\n      ‫كامــل الثمــن أو ًال ثــم يحضــر الكميــة‪ ،‬وخوف ـ ًا مــن فقــدان املبلــغ‪،‬‬\n      ‫مت االتفــاق معــه علــى شــراء كيلــو واحــد منهــا حتــى يتــم معرفــة هويــة‬\n      ‫هــذا الشــخص ومــكان تخزيــن باقــي الكميــة‪ ،‬وبنــاء علــى مــا توفــر‬\n      ‫مــن معلومــات‪ ،‬مت تفتيــش املتعــاون وســيارته تفتيشـ ًا دقيقـاً‪ ،‬و ُزود بثمــن‬\n      ‫كيلــو احلشــيش املتفــق عليــه مبلــغ مرقــم قــدره (‪ )13000‬ريــال‪ ،‬إلمتــام‬\n      ‫عمليــة الشــراء‪ ،‬ويف املوعــد واملــكان املتفــق عليــه ‪ ،‬حضــر املدعى عليه‬\n      ‫يقــود ســيارة مــن نــوع (‪ ).....‬لوحتهــا ‪.........‬وتقابــل مــع املتعــاون ثــم تلقــت‬\n      ‫الفرقــة القابضــة مــن املتعــاون إشــارة بإمتــام االســتالم والتســليم‪،‬عندئذ‬\n      ‫تقــرر متابعــة الســيارة املنــوه عنهــا للوصــول ملــكان تخزيــن الكميــات‬\n      ‫املتبقيــة‪ ،‬فتــم رصدهــا حتــى توقفــت أمــام إحــدى املبانــي الســكنية‬\n      ‫داخــل احلــي ثــم دخــل املدعــى عليــه املبنــى وبعــد ربــع ســاعة خــرج يرافقــه‬\n      ‫املدعــى عليــه الثالــث وبحوزتهمــا حقيبــة كبيرةيقومــان بســحبها حتــى‬\n      ‫وضعاهــا يف الصنــدوق اخللفــي للســيارة ثــم حتــرك املدعــى عليــه األول‬\n      ‫بالســيارة بينمــا عــاد املدعــى عليــه الثالــث إلــى املبنــى مــرة أخــرى‪،‬‬\n      ‫ومبتابعــة السيارةشــوهدت تتوقــف أمــام إحــدى الشــقق املفروشــة ثــم‬\n      ‫ترجــل منهــا املدعــى عليــه األول ودخــل املبنــى وتبــن بأنــه يســكن فيهــا‬\n      ‫منــذ أســبوع‪ ،‬وباتصــال املتعــاون عليــه مــرة أخــرى لطلــب باقــي الكميــة‬\n      ‫املتفــق عليها‪،‬أفــاد املدعــى عليــه األول بــأن الكميــة محجــوزة لشــخص‬\n      ‫آخــر‪ ،‬وبعــد مــرور ســاعتني‪،‬خرج وتوجــه ســير ًا علــى قدميــه إلــى الشــارع‬\n      ‫العــام ثــم تقابــل مــع املدعــى عليــه الثانــي الــذي حضــر إليــه يقــود ســيارة‬\n\n\n‫‪331‬‬\n\f‫مــن نــوع (‪ ).....‬لوحتهــا ‪.........‬فتــم القبــض عليهمــا وأثنــاء ذلــك قام املدعى‬\n‫عليــه األول مبقاومــة الفرقــة القابضــة ومحاولــة التخلــص مــن مفتــاح‬\n‫الســيارة (‪ )......‬الــذي كان يحملــه يف يــده وبتفتيشــه ضبــط يف جيبــه‬\n‫األميــن مبلــغ مالــي قــدره (‪ )1000‬ريــال‪ ،‬تبــن أنــه جــزء مــن املبلــغ املرقــم‬\n‫املســلم لــه و ضبــط بحوزتــه اجلــوال الــذي مت التنســيق معــه بواســطته‬\n‫وتبــن أنــه مــن نــوع (‪ )....‬وبداخلــه شــريحة اتصــال حتمــل الرقــم ذاتــه‬\n‫الــوارد يف البــاغ‪ ،‬كمــا ضبــط بحوزتــه مفتاح الســيارة (‪ )....‬وبتفتيشــها‬\n‫وجــد يف صندوقهــا اخللفــي حقيبــة كبيــرة ضبــط بداخلهــا (‪ )35‬خمســة‬\n‫وثالثــون بالطــة مــن مــادة احلشــيش املخــدر بلــغ وزنهــا جميع ـ ًا (‪36320‬‬\n‫جــم) ســتة وثالثــون ألف ـ ًا وثالثمائــة وعشــرون جرام ـ ًا ‪ .‬ومبناقشــته عــن‬\n‫مصــدر احلشــيش املخــدر ‪ ،‬أفــاد بأنــه عائــد للرابــع الــذي يســكن يف‬\n‫الــدور الثالــث شــقة رقــم (‪ )10‬مــن املبنــى الســكني الــذي شــوهد يخــرج‬\n‫منــه مــع املدعــى عليــه الثالــث وهمــا يحمــان احلقيبــة املشــار إليهــا‪،‬‬\n‫وأضــاف بــأن الثالــث والرابــع أحضــرا هــذه الكميــات مــن احلشــيش‬\n‫املخــدر مــن منطقــة جــازان إلــى محافظــة جــدة مســتخدمني ســيارة‬\n‫مــن نــوع (‪ )......‬جــرى صنــع جتاويــف خاصــة وســرية بداخلهــا لهــذا‬\n‫الغــرض‪ ،‬وبانتقــال الفرقــة القابضــة إلــى املبنــى الســكني املنــوه عنــه‬\n‫ومتابعتــه شــوهد الثالــث يخــرج منهــا متوجه ـ ًا إلــى ســيارة متوقفــة أمــام‬\n‫املبنــى هــي الســيارة ذاتهــا املنــوه عنهــا مــن األول‪ ،‬وعنــد محاولتــه فتــح‬\n‫الســيارة مت القبــض عليــه وبســؤاله عــن مالــك الســيارة‪ ،‬أفــاد بأنهــا‬\n‫عائــدة للرابــع املتواجــد داخــل الشــقة رقــم (‪ )10‬مــن املبنــى وبدخــول‬\n‫املنــزل وتفتيشــه وجــد الرابــع وعنــد القبــض عليــه قــام مبقاومــة الفرقــة‬\n‫القابضــة وبتفتيــش املنــزل وجــد داخــل دوالب يف املدخــل املــؤدي إلــى‬\n\n\n                                                                                        ‫‪332‬‬\n\f      ‫املجلــس علبــة ســجائر ضبــط بداخلهــا قطعةيشــتبه أنهــا مــن احلشــيش‬\n      ‫املخــدر بلــغ وزنهــا (‪ 40‬جــم) أربعــون جرامـاً‪ ،‬وبتفتيــش املجلــس وجــدت‬\n      ‫(مزهريــة) ضبــط بداخلهــا مبلــغ (‪ )12,000‬اثنــي عشــر ألــف ريــال‪،‬‬\n      ‫بفحصهــا تبــن أنــه باقــي املبلــغ املرقــم املســلم ‪ ،‬وقــد أفــاد األول والثالــث‬\n      ‫أثنــاء ذلــك أنهمــا قامــا بحمــل احلقيبــة ووضعهــا يف صنــدوق الســيارة (‪)....‬‬\n      ‫بإيعــاز مــن الرابــع وأفــاد الثالــث أنــه الرابــع أحضــرا كميــات احلشــيش‬\n      ‫املخــدر مــن منطقــة جيــزان إلــى محافظــة جــدة وكان عددهــا (‪)36‬‬\n      ‫ســت وثالثــون بالطــة‪ ،‬مســتخدمني الســيارة (‪ ).....‬املتوقفــة أمــام املبنــى‬\n      ‫والعائــدة للرابــع ومســجلة ملكيتهــا باســم زوجتــه‪ ،‬وبتفتيشــها تبــن‬\n      ‫بأنهــا مــن نــوع (‪ ).....‬لوحتهــا (‪ ).........‬ووجــد بداخــل جتاويــف ومخابــئ‬\n      ‫ســرية كمــا عثــر علــى آثــار الســتخراج احلشــيش املخــدر منهــا‪ ،‬وبســؤال‬\n      ‫األول عــن صاحــب الكميــة أكــد بأنهــا عائــدة للرابــع وأنــه يحضرهــا‬\n      ‫هــو الثالــث مــن منطقــة جيــزان إلــى محافظــة جــدة عــن طريــق شــخص‬\n      ‫يف جيــزان يدعــى‪......... /‬موجــود علــى جــوال رقــم ‪.........‬وبفحــص جــوال‬\n      ‫الرابــع عثــر محفوظـ ًا يف ذاكرتــه بإســم ‪ ،....‬وأثنــاء القبــض علــى الرابــع‬\n      ‫اتصــل علــى جوالــه املدعــو‪......... /‬ومكــن الرابــع مــن الــرد وكان يقــول‬\n      ‫املتصــل لــه (كيــف حالــك ‪ ).........‬إال أنــه أجابــه (مــن ‪ ).........‬وهــو مــا‬\n      ‫أثــار شــك املتصــل فســأله (هــل أنــت طيــب اشــبك مــا تعرفنــي) ورفــض‬\n      ‫الرابــع التعــاون واإلجابــة عليــه ثــم أغلــق املدعــو ‪.........‬هاتفــه اجلــوال‪،‬‬\n      ‫وقــد قــام املتعــاون بتســليم الفرقــة القابضــة املــادة املشــتراه مــن األول‬\n      ‫وتبــن بأنهــا مــادة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ 1040‬جــم) ألــف‬\n      ‫وأربعــون جراماً‪.‬وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم (‪).........‬‬\n      ‫لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم والكيميــاء الطبيــة‬\n\n\n‫‪333‬‬\n\f‫الشــرعية مبحافظــة جــدة‪ ،‬ايجابيــة عينــة مــا ضبــط للحشــيش املخــدر‬\n‫واحتوائهــا علــى املــادة الفعالــة لــه‪ ،‬املــدرج بجدول املواد املخــدرة رقم (‪)1‬‬\n‫فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي رقــم م‪ 39/‬بتاريــخ ‪1426/‬هـ‪.‬باســتجواب األول‬\n‫اعتــرف بضبــط (‪ )35‬خمســة وثالثــون بالطــة مــن مــادة احلشــيش املخــدر‬\n‫بلــغ وزنهــا جميعـ ًا (‪ 36,320‬جــم) ســتة وثالثــون ألفـ ًا وثالثمائــة وعشــرون‬\n‫جرام ـاً‪ ،‬ضبطــت يف صنــدوق ســيارته كمــا اعتــرف بأنــه ضبــط معــه‬\n‫(‪ )1000‬ألــف ريــال‪ ،‬مــن املبلــغ املرقــم ‪ .‬وباســتجواب الثانــي اعتــرف‬\n‫بتعاطــي احلشــيش املخــدر مــن الســابق‪ ،.‬وباســتجواب الثالــث‪ ،‬اعتــرف‬\n‫بنقــل (‪ 36320‬جــم) ســتة وثالثــون ألفـ ًا وثالثمائــة وعشــرون جرامـاً‪ ،‬مــن‬\n‫مــادة احلشــيش املخــدر بقصــد االجتــار‪ ،‬كمــا اعتــرف ببيــع (‪)1040‬‬\n‫ألــف وأربعــون جرام ـاً‪ ،‬مــن مــادة احلشــيش املخــدر‪ ،‬وحيــازة (‪40‬جــم)‬\n‫أربعــون جرام ـاً‪ ،‬مــن نوعهــا بقصــد التعاطــي‪ ،‬وأضــاف يف أقوالــه بأنــه‬\n‫هــو مــن وضــع (‪ )35‬بالطــة مــن احلشــيش املخــدر يف ســيارة األول وهــو‬\n‫مــن قــام ببيــع كيلــو احلشــيش املخــدر وقبــض ثمنــه (‪ )13000‬ريــال‪،‬‬\n‫ســلم املدعــى عليــه األول منهــا (‪ )1000‬ألــف ريــال‪ ،‬واملتبقــي وضعــه‬\n‫يف بيــت الرابــع‪، .‬وباســتجواب الرابــع اعتــرف بضبــط جــزء مــن املبلــغ‬\n‫املرقــم وقــدره (‪ )12000‬ريــال يف منزلــه كمــا اعتــرف بضبــط (‪40‬‬\n‫جــم) أربعــون جرامـ ًا مــن مــادة احلشــيش املخــدر يف منزلــه وبســؤاله عــن‬\n‫الســيارة مــن نــوع (‪ ).....‬لوحتهــا (‪ ).........‬أفــاد بأنهــا مســجلة بإســم زوجتــه‬\n‫ولكنهــا عائــدة لــه وال يســتخدمها ســواه منــذ شــراؤها‪ .‬وبفحصهــا ورد‬\n‫خطــاب مديــر مكافحــة املخــدرات مبحافظــة جــدة رقــم ‪.........‬بتاريــخ‬\n‫‪1433/7/26‬ه ـ مرفقـ ًا بطيــه محضــري تفتيــش يؤكــدان أنــه بفحــص‬\n\n\n                                                                                          ‫‪334‬‬\n\f      ‫الســيارة املشــار إليهــا مت االشــتباه يف مواقــع وأجــزاء منهــا وتبــن وجــود‬\n      ‫مخابــئ ســرية بداخلهــا اســتخدمت حديثـ ًا يف تهريــب احلشــيش املخــدر‪.‬‬\n      ‫وباســتدعاء مالكــة الســيارة زوجــة املدعــى عليــه املذكــور‪ ،‬أفــاد‬\n      ‫مديــر مكافحــة املخــدرات يف خطابــه املشــار إليــه أنــه لــم يتــم العثــور‬\n      ‫عليهــا ومت التعميــم عنهــا بتعميــم إيقــاف خدمــات رقــم ‪.........‬وتاريــخ‬\n                                           ‫‪1433/7/14‬ه ـ ولــم حتضــر حتــى تاريخــه‪.‬‬\n      ‫وانتهــى التحقيــق إلــى توجيــه االتهــام إلــى كل مــن األول‪......... /‬‬\n      ‫والثالــث‪......... /‬والرابــع‪......... /‬بنقــل (‪ 37360‬جــم) مــن مــادة احلشــيش‬\n      ‫املخــدر بقصــد الترويــج‪ ،‬وبيعهــم مــا وزنــه (‪ 1040‬جــم) ألــف وأربعــون‬\n      ‫جراماً‪،‬منهــا بقصــد االجتــار‪ ،‬وحيــازة الثالــث والرابــع (‪ 40‬جــم) أربعــون‬\n      ‫جرام ـ ًا مــن ذات املــادة بقصــد الترويــج لهمــا وقصــد التعاطــي للثالــث‬\n      ‫أيض ـاً‪ ،‬وتوجيــه االتهــام لــأول والرابــع مبقاومتهــم للفرقــة القابضــة‬\n      ‫وللثالــث مبحاولــة تضليــل جهــة التحقيــق ‪ .‬وتوجيــه االتهــام للثانــي‬\n      ‫بالشــروع يف تســلم (‪ 36320‬جــم) ســتة وثالثــون ألفـ ًا وثالثمائــة وعشــرون‬\n      ‫جرام ـاً‪ ،‬مــن مــادة احلشــيش املخــدر بقصــد االجتــار وتعاطيــه الســابق‬\n                                                                       ‫للحشــيش املخــدر‪.‬‬\n                                                         ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ .1‬اعترافهــم جميعـ ًا بصحــة وقائــع القبــض والضبط املنــوه عنها واملدونة‬\n                 ‫يف الصفحــات رقــم (‪ )14-1‬مــن دفتــر التحقيــق املرفق لفة (‪.)38‬‬\n      ‫‪ .2‬مــا ورد يف اعترافــات املدعــى عليــه الثالــث املنــوه عنهــا واملدونــة علــى‬\n      ‫الصفحــات رقــم (‪ )14-10‬مــن دفتــر التحقيــق املرفــق لفــة (‪.3 .)38‬مــا‬\n      ‫ورد يف اعتــراف املدعــى عليــه الثانــي املنــوه عنــه واملــدون علــى الصفحات‬\n                                    ‫رقــم (‪ )8-7‬مــن دفتــر التحقيــق املرفــق لفــة (‪.)38‬‬\n\n\n‫‪335‬‬\n\f‫‪ .4‬شــهادة الشــهود الــواردة يف محضــر البــاغ والقبــض والتفتيــش املنــوه‬\n‫عنــه واملدونــن علــى الصفحــات رقــم (‪ )15 -2‬مــن ملــف إجــراءات‬\n‫االســتدالل املرفــق لفــة (‪.5.)1‬مــا ورد يف التقريــر الكيميائــي الشــرعي‬\n‫املنــوه عنــه واملرفــق لفــه (‪.6.)39‬مــا ورد يف محضــري التفتيــش وإعــادة‬\n‫التفتيــش املنــوه عنهمــا واملرفقــن لفــة (‪.7 .)59-58‬وجــود مخابــئ‬\n‫وجتاويــف ســرية يف ســيارة الرابــع‪ ،‬واعترافــه بــأن زوجتــه متلكهــا علــى‬\n‫الــورق فقــط و أنهــا عائــدة لــه وال يقودهــا غيــره منــذ شــراؤها‪ ،‬ومــا‬\n‫أثبتــه فحــص هــذه املخابــئ مــن أنهــا تســتخدم لتهريــب مــادة احلشــيش‬\n‫املخــدر‪ ،‬قرينــة قويــة علــى ضلوعــه يف ارتــكاب اجلرائــم املنســوبة إليــه‬\n‫وعلــى تخطيطــه املســبق المتهــان هــذه األعمــال‪ -8.‬مــا ذكــره األول‬\n‫للمتعــاون عندمــا طلــب منــه األخيــر باقــي كميــة احلشــيش املخــدر‬\n‫املتفــق عليهــا‪ ،‬بــأن الكميــة محجــوزة لشــخص آخــر وإيقافــه لســيارته‬\n‫مــدة ســاعتني وبداخلهــا هــذه الكميــة الكبيــرة‪ ،‬قرينــة علــى أنذلــك‬\n‫الشــخص ســيحضر الســتالم املخــدرات مــن مــكان وقــوف الســيارة‪.‬‬\n‫‪.9‬خــروج األول مــن الشــقق املفروشــة التــي يســكنها وهــي معروفــة‬\n‫ويســهل الوصــول إليهــا وترجلــه إلــى الشــارع العــام ومقابلتــه للثانــي قرينــة‬\n‫علــى عــدم صدقهمــا فيمــا أفــادا بــه عــن ســبب املقابلــة‪ .10.‬إفــادة األول‬\n‫أنــه يجهــل موقــع حــراج (‪ ).........‬وأنــه مقابلتــه للثانــي حتــى يســاعده يف‬\n‫الوصــول إليــه لشــراء أثــاث ملنزلــه يف صبيــا‪ ،‬يتناقــض مــع مــا أورده عــن‬\n‫ســبب حضــوره إلــى جــدة كمــا يتناقــض مــع مــا ورد يف محضــر القبــض‬\n‫عــن حتــركات املذكــور بســهولة داخــل مدينــة جــدة كمــا يظهــر‬\n‫مــن متابعتــه‪ .‬وحيــث إن مــا أقــدم املذكــورون وهــم بكامــل أهليتهــم‬\n‫املعتبــرة شــرع ًا فعــل محــرم شــرع ًا ومجــرم نظام ـاً‪ ،‬مبوجــب املــادة‬\n\n\n                                                                                       ‫‪336‬‬\n\f      ‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه‪،‬‬\n      ‫لــذا أطلــب إثبــات إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم بالعقوبــات‬\n      ‫األصليــة والتكميليــة التاليــة ‪.1:‬الســجن واجللــد والغرامــة مــع تشــديد‬\n      ‫العقوبــة عليهــم لتوفــر احلالــة الثانيــة بحــق األول واحلالــة الثالثــة بحقهــم‬\n      ‫جميع ـ ًا مــن البنــد (ثالث ـاً) مــن املــادة (‪ )37‬وذلــك اســتناد ًا للفقــرة (‪)2‬‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫املنــوه عنه‪.2.‬مصــادرة جهــاز اجلــوال ذو الرقــم املصنعــي (‪ ).........‬اســتناد ًا‬\n      ‫للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املنــوه عنــه وإيــداع قيمتهمــا يف حســاب املديريــة العامة ملكافحة‬\n      ‫املخــدرات مبؤسســة النقــد العربــي الســعودي‪ ،‬اســتناد ًا لبرقيــة ســمو‬\n      ‫وزيــر الداخليــة رقــم (‪ )40656/4/5/1‬وتاريــخ ‪1430/6/18‬هــ‪ ،‬وإلغــاء‬\n      ‫اخلدمــة عــن شــريحتي االتصــال رقــم (‪ ).........‬املســتخدمة يف ارتــكاب‬\n      ‫اجلرميــة وعــدم صرفهــا لــه لســوء اســتخدامها اســتناد ًا لتعميــم ســمو وزيــر‬\n      ‫الداخليــة رقــم(‪ )9798‬يف ‪1428/2/10-9‬هـ‪.3.‬النظــر شــرع ًا يف ملكية‬\n      ‫الســيارتني األولــى مــن نــوع (‪ ).....‬لوحتهــا (‪ ).........‬والثانيــة مــن نــوع (‪)....‬‬\n      ‫لوحتهــا (‪ ).........‬املســتخدمتني يف ارتــكاب اجلرميــة‪ ،‬ومصادرتهمــا‬\n      ‫وفــق مــا يتقــرر شــرع ًا اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املنــوه عنه‪.4.‬إبعــاد الثالــث‬\n      ‫عــن اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتــه اســتناد ًا للفقــرة (‪ )2‬مــن‬\n      ‫املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املنــوه‬\n      ‫عنه‪.5.‬منــع األول والثانــي والرابــع مــن الســفر خــارج اململكــة وذلــك بعــد‬\n      ‫انتهــاء تنفيــذ عقوبتهــم اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة املنــوه عنه‪.‬كمــا أطلــب تعزيــر‬\n\n\n‫‪337‬‬\n\f‫األول والرابــع شــرعاً‪ ،‬لقــاء مقاومتهمــا للفرقــة القابضــة وتعزيــر الثالــث‬\n                                 ‫شــرع ًا لقــاء محاولتــه تضليــل جهــة التحقيــق‪.‬‬\n‫وبســؤال املدعــى عليــه الرابــع ‪.........‬عــن دعــوى املدعــي العــام أجــاب‬\n‫ا ماذكــره املدعــي العــام مــن أنــه قبــض علــي داخل منزلــي وبرفقتي‬        ‫قائـ ً‬\n‫املدعــى عليــه الثالــث فهــذا صحيــح وامــا ماذكــره مــن اتهامــي فهــذا‬\n‫غيــر صحيــح والصحيــح مــا ذكرتــه هــذه إجابتــي وبســؤال املدعــى عليــه‬\n‫ا ماذكــره املدعــي‬     ‫الثانــي ‪.........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n‫العــام كلــه غيــر صحيــح هــذه إجابتــي وبســؤال املدعــى عليــه الثالــث‬\n‫ا ماذكــره املدعــي العــام‬     ‫‪.........‬عــن دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n‫كلــه صحيــح فقــد أخــذت ســيارة املدعــى عليــه األول وذهبــت بهــا إلــى‬\n‫جيــزان وقمــت بشــراء حشــيش مببلــغ ‪ 36000‬ريــال (ســتة وثالثــون ألــف‬\n‫ريــال) ونقلتهــا إلــى جــدة وبقيــت املدعــى عليهــم ليــس لهــم بهــا عالقــة‬\n‫هــذه إجابتــي وبســؤال املدعــى عليــه األول ‪ ..‬عــن دعــوى املدعــى العــام‬\n‫ا لقــد أعطيــت املدعــى عليــه الثالــث ســيارتي وقــام بنقــل‬      ‫أجــاب قائ ـ ً‬\n‫احلشــيش وأنــا ال أعلــم عــن ذلــك هــذه اجابتــي وبســؤال املدعــى العــام عــن‬\n‫بينتــه طلــب إمهالــه إلحضارهــا رفعــت اجللســة بتاريــخ ‪1434/1/27‬ه ـ‬\n‫الســاعة احلاديــة عشــر ‪ ،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                     ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة ففــي يــوم الثالثــاء املوافق‪1434/02/12‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪11:45‬وفيهــا حضــر املدعــي العــام كمــا أحضــر‬\n‫ال مــن ‪........../‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬      ‫للشــهادة ك ً‬\n‫رقــم (‪ )..........‬و‪.......... /‬اجلنســية مبوجــب الســجل املدنــي رقــم (‪)..........‬‬\n\n\n                                                                                        ‫‪338‬‬\n\f      ‫ا أبلــغ مــن‬\n                  ‫وبســؤال الشــاهد األول عــن مــا لديــه مــن شــهادة أجــاب قائ ـ ً‬\n      ‫العمــر ‪ 34‬عام ـ ًا وأعمــل بــإدارة مكافحــة املخــدرات مبحافظــة جــدة‬\n      ‫وليــس بينــي وبــن املدعــى عليهــم أي عــداوة وأشــهد بــاهلل العظيــم (بأنــه‬\n      ‫وردت إخباريــة بتاريــخ ‪1433/6/15‬ه ـ مــن أحــد املتعاونــن ملكافحــة‬\n      ‫املخــدرات مبحافظــة جــدة مفادهــا وجــود شــبكة تقــوم بتهريــب وترويــج‬\n      ‫املخــدرات مــن منطقــة جيــزان علــى محافظــة جــدة ومت االتفــاق مــع أحــد‬\n      ‫عناصــر هــذه الشــبكة موجــود علــى جــوال رقــم (‪ ).........‬علــى شــراء‬\n      ‫كميــة مــن احلشــيش املخــدر وســعر الكيلــو هــو ثالثــة عشــر ألــف ريــال‬\n      ‫علــى أن يتــم تســليم كامــل املبلــغ أو ًال ثــم يحضــر الكميــة وخوفــا مــن‬\n      ‫فقــدان املبلــغ مت االتفــاق معــه علــى شــراء كيلــو واحــد منهــا حتــى يتــم‬\n      ‫معرفــة شــخصيته ومعرفــة تخزيــن باقــي الكميــة حيــث مت تفتيــش‬\n      ‫املتعــاون تفتيــش دقيقـ ًا وزود بثمــن احلشــيش واملتفــق عليــه ومبلــغ مرقــم‬\n      ‫ثالثــة عشــر الــف ريــال إلمتــام عمليــة الشــراء ثــم حضــرت ســيارة مــن نــوع‬\n      ‫‪ ....‬لوحتهــا رقم‪.....‬وتقابــل مــع املتعــاون ثــم تلقــت الفرقــة القابضــة مــن‬\n      ‫املتعــاون إشــارة بإمتــام عمليــة االســتالم ومت متابعــة الســيارة حــى توقفــت‬\n      ‫أمــام إحــدى املبانــي الســكنية داخــل احلــي وبعــد ربع ســاعة خــرج املدعى‬\n      ‫عليــه ‪.........‬ويرافقــه ‪.........‬بحوزتهمــا حقيبــة كبيــرة يقومــان بســحبها‬\n      ‫حتــى وضعاهــا يف الصنــدوق اخللفــي للســيارة ثــم حتــرك املدعــى عليــه ا‬\n      ‫ألول بالســيارة بينمــا عــاد املدعــى عليــه الثالــث إلــى املبنــى مــرة أخــرى‬\n      ‫ومبتابعــة الســيارة توقفــت أمــام إحــدى الشــقق املفروشــة ثــم ترجــل منهــا‬\n      ‫املدعــى عليــه األول ودخــل املبنــى وتبــن بأنــه يســكن فيهــا منــذ أســبوع‬\n      ‫وباتصــال مــرة أخــرى لطلــب باقــي الكميــة املتفــق عليهــا أفــاد املدعــى‬\n      ‫عليــه األول بــان الكميــة محجــوزة لشــخص آخــر وبعــد مــرور ســاعتني‬\n\n\n‫‪339‬‬\n\f‫خــرج وتوجــه ســير ًا علــى قدميــه إلــى الشــارع العــام ثــم تقابــل مــع ‪.........‬‬\n‫الــذي حضــر إليــه يقــود ســيارة مــن نــوع ‪ ......‬لوحتها‪.........‬فتــم القبــض‬\n‫عليهمــا وبتفتيــش ‪ ....‬ليعثــر علــى مبلــغ الــف ريــال جــزء مــن املبلــغ املرقــم‬\n‫وضبــط بحوزتــه اجلــوال الــذي مت التنســيق معــه بواســطة وبتفتيش ســيارة‬\n‫‪ ....‬وجــد يف صندوقهــا حقيبــة كبيــرة بهــا خمســة وثالثــون بالطــة مــن‬\n‫مــادة احلشــيش املخــدر ومبناقشــته عــن مصــدر احلشــيش أفــاد بأنــه‬\n‫عائــد إلــى‪ .........‬الــذي يســكن بالــدور الثالــث مــن املبنــي الســكني‬\n‫الــذي شــوهدا يخرجــان منهــا وقــال بــان ‪.........‬و‪.........‬أحضــرا هــذه‬\n‫الكميــات مــن منطقــة جيــزان مســتخدمني ســيارة ‪ ....‬حيــث جــرى صنــع‬\n‫جتاويــف خاصــة وســرية بداخلهــا لهــذا الغــرض وباالنتقــال الــى املبنــي‬\n‫الســكني ومتابعتــه شــوهد ‪.........‬يخــرج منــا متوجهــا ً إلــى ســيارة متوقفــة‬\n‫ومت القبــض عليــه وقــال بــان الســيارة عائــدة للمتهــم ‪.........‬املتواجــد‬\n‫داخــل الشــقة وبدخــول املنــزل عثــر بداخلــه علــى علبــة ســجائر وقطعــة‬\n‫يشــتبه بانهــا مــن احلشــيش املخــدر ومزهريــة بهــا اثنــي عشــر الــف ريــال‬\n‫وبفحصهــا تبــن أنــه املبلــغ املرقــم واعتــرف بأنهــم احضــروا الكميــة‬\n‫مــن جيــزان وعددهــا ســت وثالثــون بالطــة حشــيش وأن الســيارة مــن نــوع‬\n‫‪ ....‬لوحــة رقــم ‪.........‬وقــد قــام املتعــاون بتســليم الفرقــة القابضــة املــادة‬\n‫املشــتراة مــن األول وتبــن بأنهــا مــن احلشــيش املخــدر ومت تســليم كافــة‬\n‫الكميــات املضبوطــة برفقــة األشــخاص إلدارة املخــدرات التخاذ الالزم‬\n‫ا أبلــغ‬‫وبســؤال الشــاهد الثانــي ‪.........‬عــن مالديــه مــن شــهادة أجــاب قائـ ً‬\n‫مــن العمــر ‪ 30‬عامــا وأعمــل بــإدارة مكافحــة املخــدرات مبحافظــة جــدة‬\n‫وليــس بينــي وبــن املدعــى عليهــم أي عــداوة وأشــهد بــاهلل العظيــم مبثلمــا‬\n‫شــهد بــه األول كمــا حضــر لتزكيــة الشــاهد ‪.........‬ســعودي اجلنســية‬\n\n\n                                                                                          ‫‪340‬‬\n\f      ‫مبوجــب ســجل رقــم‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا بــأن الشــاهدين مــن أهــل‬    ‫رقــم ‪.........‬وشــهد كل واحــد منهمــا قائ ـ ً‬\n      ‫الصــاة والصــاح وأقبــل بشــهادتهما لــي وعلــي هكــذا شــهدوا رفعــت‬\n      ‫اجللســة بتاريــخ ‪1434/1/12‬ه ــالساعة الثانيــة عشــر‪ .‬وبــاهلل التوفيــق ‪،‬‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/01/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 1434/01/11..........‬ه ـ‬\n      ‫ففــي يــوم الثالثــاء املوافــق‪ 1434/02/26‬ه ـ أفتتحــت اجللســة وفيهــا‬\n      ‫حضــر املدعــي العــام واملدعــى عليــه األول ‪..........‬واملدعــى عليــه الثانــي‬\n      ‫‪ ..‬واملدعــى عليــه الثالــث ‪ ..........‬واملدعــى عليــه الرابــع ‪..........‬وبعــرض‬\n      ‫مــا مت ضبطــه ســابق ًا مــن شــهادة الشــهود علــى املدعــى عليهــم وبســؤال‬\n      ‫ا مــا ذكــره الشــهود غيــر‬   ‫املدعــى عليــه األول عــن الشــهادة أجــاب قائ ـ ً‬\n      ‫صحيــح هــذه إجابتــي وبســؤال املدعــى عليــه الثانــي عــن الشــهادة أجــاب‬\n      ‫ا مــا ذكــره الشــهود غيــر صحيــح هــذه إجابتــي وبســؤال املدعــى‬         ‫قائ ـ ً‬\n      ‫ا مــا ذكــره الشــهود غيــر صحيــح‬     ‫عليــه الثالــث عــن الشــهادة أجــاب قائـ ً‬\n      ‫ا مــا‬\n           ‫هــذه إجابتــي وبســؤال املدعــى عليــه الرابــع عــن الشــهادة أجــاب قائـ ً‬\n      ‫ذكــره الشــهود غيــر صحيــح هــذه اجابتــي‪ .‬وبســؤال املدعــى عليــه األول‬\n      ‫ا نعــم اعترفــت بأنــه ضبــط داخــل ســيارتي ‪....‬‬    ‫عــن اعترافــه اجــاب قائـ ً‬\n      ‫احلشــيش املخــدر والســيارة مســتأجرة ليســت لــي كمــا ضبــط علــى‬\n      ‫األلــف ريــال بحوزتــي منحــه ايــاه املدعــى عليــه الثالــث فهــذا صحيــح‬\n      ‫وبســؤال املدعــى عليــه الثانــي عــن اعترافــه بتعاطــي احلشــيش اجــاب‬\n\n\n‫‪341‬‬\n\f‫ا اعتــرايف صحيــح وأنــا أتعاطــى احلشــيش املخــدر ســابق ًا وبســؤال‬            ‫قائ ـ ً‬\n‫ا مــا اعترفــت بــه كلــه صحيــح هــذه‬    ‫الثالــث عــن اعترافــه أجــاب قائ ـ ً‬\n‫ا نعــم‬‫إجابتــي وبســؤال املدعــى عليــه الرابــع عــن اعترافــه أجــاب قائ ـ ً‬\n‫اعتــرف بأنــه ضبــط علــى مبلــغ اثنــا عشــر ألــف ريــال داخــل منزلــي‬\n‫كمــا أن الســيارة مــن نــوع ‪ .....‬رقــم لوح\\تهــا ‪...‬تعــود ملكيتهــا لزوجتــي وأنا من‬\n‫يســتخدمها هــذه إجابتــي ‪ .‬رفعــت اجللســة للتأمــل بتاريــخ ‪1434 / 02 / 26‬هـ‬\n‫الســاعة احلاديــة عشــر وخمــس واربعــون دقيقــة‪ .‬واهلل املوفــق‪ ،‬وصلــى‬\n                           ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪3420255‬‬\n‫وتاريــخ ‪1434/01/12‬ه ـ املقيــدة باحملكمــة برقــم ‪3476535‬وتاريــخ‬\n‫‪ 1434/01/11‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/03/02‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــى عليهــم األول والثانــي والثالــث والرابــع‬\n‫واملدعــي العــام هــذا وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي رقــم ‪ /2186‬ك ش م لعــام ‪1433‬ه ـ واملرفــق باملعاملــة علــى لفــة‬\n‫رقــم ‪ 39‬يتضمــن ايجابيــة مــا مت ضبطــه واحتــواء املــادة املضبوطــة علــى‬\n‫مــادة احلشــيش املخــدر وعلــى محضــر القبــض واملرفــق علــى لفــة رقــم ‪1‬‬\n‫يتضمــن هــذا نصــه ( وقــد أفــاد املتهــم الثالــث انــه كان يرافــق املتهــم‬\n‫الرابــع املدعــو‪......... /‬اثنــاء احضارهــا مــن جــازان حتــى وصلنــا مدينــة‬\n‫جــدة وافــاد املتهــم األول بــأن الكميــة قــد قــام باخراجهــا مــن داخــل‬\n‫الســيارة داخــل جتاويــف ســرية) كمــا تضمنــت مــا هــذا نصــه (وبســؤال‬\n‫املتهــم األول عــن صاحــب الكميــة افادبانــه ‪......... /‬يحصــل عليهــا مــن‬\n\n\n                                                                                             ‫‪342‬‬\n\f      ‫شــخص يف جــازان يدعــى ‪.........‬موجــود علــى جــوال رقــم ‪..........‬وهــو‬\n      ‫الــذي يتقابــل معــه وبســؤال املتهــم الرابــع عــن مصــدر الكميــة رفــض‬\n      ‫االرشــاد عليــه والتعــاون مــع اإلدارة علم ـ ًا بــأن رقــم ‪ ....‬وجــد مخــزن‬\n      ‫بجــوال املتهــم ‪.........‬وكان يتصــل عليــه اثنــاء القبــض عليــه وقــد مكــن‬\n      ‫مــن الــرد عليــه وعلــى مســمع مــن الفرقــة حيــث افــاد املدعــو ‪......... /‬‬\n      ‫بقولــه كيــف حالــك ‪.........‬إال أن املتهــم ‪.........‬ردعليــه وقــال لــه مــن‬\n      ‫‪.........‬ممــا اثــار الشــك وســألة هــل انــت طيــب أشــبك مــا تعرفنــي ورفــض‬\n      ‫التعــاون والــرد عليــه وبعدهــا اقفــل املدعــو ‪.........‬جوالــه علم ـ ًا بــأن‬\n      ‫املتهــم الرابــع ‪.........‬لدينــا عنــه اخباريــات تفيــد بانــه مــن كبــار مروجــي‬\n      ‫املخــدرات ويحضــر كميــات كبيــرة مــن مدينــة جــازان إلــى جــدة ) علــى‬\n      ‫الصفحــة رقــم ‪ 14 ،13‬وعلــى محضــر اســتجواب املدعــى عليهــم وعلــى‬\n      ‫صحائــف ســوابقهم فوجــد كمــا ذكــر املدعــي العــام فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى االجابــة ومــا قــرره الطرفــان وحيــث صــادق املدعــى‬\n      ‫عليــه الثالــث ‪.........‬علــى دعــوى املدعــي العــام وأقــر بنقــل ‪ 37360‬ســبعة‬\n      ‫وثالثــون ألف ـ ًا وثالثمائــة وســتون بقصــد الترويــج والبيــع منهــا كمــا‬\n      ‫أعتــرف املدعــى عليــه األول بالتحقيــق بضبــط خمســة وثالثــون بالطــة‬\n      ‫مــن احلشــيش املخــدر وضبــط مبلــغ ألــف ريــال املرقــم واعتــراف الثانــي‬\n      ‫بتعاطــي احلشــيش املخــدر واعتــراف الرابــع بضبــط مبلــغ ‪ 12000‬ريــال‬\n      ‫احلكومــي مبنزلــه والســيارة عائــدة لــه ولتجهيــز الســيارة للترويــج كمــا‬\n      ‫انــه لــم يتعــاون يف كشــف املجرمــن واملفســدين يف األرض وملــا تضمنــه‬\n      ‫محضــر القبــض ومحضــر االســتجواب والتقريــر الكيمــاوي الشــرعي‬\n      ‫املشــار اليــه أعــاه وحيــث مــا قامبــه املدعــى عليهــم فعــل محــرم شــرع ًا‬\n      ‫يســتحقوا العقوبة طبق ًا للقواعد الشــرعية ووفق ًا للمواد ‪56 ، 53 ، 38‬‬\n\n\n‫‪343‬‬\n\f‫مــن نظــام مكافحــة املخــدرات ولوجــود ســابقة علــى املدعى عليــه الرابع‬\n‫ترويــج املســكرات ولــكل مــا تقــدم فقــد ثبــت لــدي إدانــه املدعــى عليــه‬\n‫االول ‪.........‬والثالــث ‪......‬والرابــع ‪........‬بنقــل ‪ 37360‬جــم مــن احلشــيش‬\n‫املخــدر بقصــد الترويــج وبيعهــم مــا وزنــه ‪ 1040‬جــم منهــا بقصــد االجتــار‬\n‫وحيــازة الثالــث والرابــع أربعــون جرام ـ ًا مــن ذات املــادة بقصــد الترويــج‬\n‫لهمــا وقصــد التعاطــي وإدانــة الثانــي بالشــروع يف تســليم ســتة وثالثــن‬\n‫ألف ـ ًا وثالثمائــة وعشــرين جرام ـ ًا مــن احلشــيش املخــدر بقصــد االجتــار‬\n‫وتعاطيــه منهــا مــن الســابق وقــررت تعزيرهــم لقــاء مــا اســند اليهــم مبــا‬\n‫يلــي‪ .‬أو ًال ســجن املدعــى عليــه األول ‪.........‬واملدعــى عليــه الثالــث ‪.........‬‬\n‫واملدعــى عليــه الرابــع ‪.........‬كل واحــد منهــم تســع ســنوات يحتســب‬\n‫منهــا مــدة ايقافهــم بســبب هــذه القضيــة وجلــد كل واحــد منهــم الــف‬\n‫جلــدة مفرقــة علــى عشــرين دفعــة بــن كل دفعــة وأخــرى عشــرة أيــام‬\n‫وغرامــة ماليــة قدرهــا ألــف وخمســمائة ريــال علــى كل واحــد منهــم‬\n‫‪ .‬ثاني ـ ًا ‪ :‬ســجن املدعــى عليــه الثانــي ســت ســنوات يحتســب منهــا مــدة‬\n‫ايقافــه بســبب هــذه القضيــة وجلــده ثمانــن جلــدة حــدا لقــاء تعاطيــه‬\n‫احلشــيش املخــدر وجلــده ‪ 600‬جلــدة مفرقــة علــى اثنــا عشــر دفعــه بــن‬\n‫كل دفعــة واخــرى عشــرة ايــام وذلــك بعــد احلــد بشــهر وغرامــة ماليــة‬\n‫قدهــا ‪ 1500‬ريــال ‪ .‬ثالث ـ ًا ‪ :‬مصــادرة جهــاز اجلــوال املســتخدم يف اجلرميــة‬\n‫والغــاء شــريحته وإيــداع قيمتــه لــدى حســاب مكافحــة املخــدرات والغــاء‬\n‫اخلدمــة عــن شــريحة االتصــال رقــم ‪.........‬املســتخدمة يف اجلرميــة‪ .‬رابعـ ًا ‪:‬‬\n‫مصــادرة الســيارتني املســتخدمتني يف اجلرميــة األولــى مــن نــوع ‪ .....‬رقــم‬\n‫اللوحــة ‪.........‬والثانيــة مــن نــوع ‪ .....‬رقــم اللوحــة ‪.........‬خامس ـ ًا ‪ :‬ابعــاد‬\n‫الثالــث خــارج البــاد بعــد انتهــاء محكوميتــه ووضــع اســمه علــى قائمــة‬\n\n\n                                                                                            ‫‪344‬‬\n\f      ‫املمنوعــن مــن دخــول البــاد مــرة اخــرى ‪ .‬سادس ـ ًا ‪ :‬منــع األول والثانــي‬\n      ‫والرابــع مــن الســفر خــارج البــاد بعــد انتهــاء محكوميتهــم مــدة مماثلــة‬\n      ‫حملكوميتهــم وبذلــك حكمــت‪ .‬وبعــرض احلكــم علــى املدعــي العــام‬\n      ‫واملدعــى عليهــم قــرر املدعــي العــام عــدم القناعــة باحلكــم لقلــة العقوبــة‬\n      ‫بــدون الئحــة وقــرر املدعــى عليهــم معارضتهــم بــدون الئحــة‪ .‬جــرى النطــق‬\n      ‫باحلكــم بتاريــخ ‪1434 /03 /02‬ه ـ الســاعة العاشــرة والنصــف‪ .‬واهلل‬\n            ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة اإلســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة مبحافظــة جــدة املســاعد برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/4/7‬ه ـ املرفــق بهــا القــرار رقــم ‪1434/3/..........‬ه ـ الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪........../‬القاضــي باحملكمــة اجلزائيــة مبحافظــة‬\n      ‫جــدة املتضمــن دعــوى املدعــي العــام ضــد ‪.......... /‬ورفقــاه املتهمــن يف‬\n      ‫مخــدرات‪ ،‬احملكــوم فيــه مبــا دون بباطنــه ‪ ،‬وبدراســة القــرار وصــورة‬\n      ‫ضبطــه قررنــا املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪345‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":328,"source_page_end":345,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"23bef41e909f9910c8266d11d1e21ad03111c1d2d2adabf763367d663498dad0","normalized_text_hash":"3f6e0b84563ebef66faaed4913137085fe404175b73e033d8559502ddb972ab2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p328-3459075"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

